/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231006-4","meetingId":"r05-c-settlement","date":"2023年10月6日","dateIso":"2023-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件整理しています。","topics":[{"id":"topic-01","title":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、２９３ページ、健康づくり支援事業費、２９５ページ、ＡＥＤ管理費、３１１ページ、カラス及び外来種対策事業についてお伺いします。令和５年３月の予算特別委員会でも質問させていただきましたが、前回と今回の比較を踏まえて、実績や評判も示すよう求めました。","respondent":"若生健康課長","answer":"今回８月からアプリを開始していますけれども、参加者数につきましては、まずまず順調な滑り出しかなと考えています。今後、いろいろ事業者でも説明会をやったりとか、区としてもＳＮＳ等も活用しましてＰＲをやっていきたいと思ってあります。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"他の所管と連携した効果的な取組と考えますが、今後、アプリはどのように進んでいきますでしょうか。区のお考えを説明するよう求めました。","respondent":"若生健康課長","answer":"文化観光課やスポーツ推進課等のイベントとも連携しまして、そのコースを今回、そこを楽しみながら名所を回るなどという機能も追加しています。事業ですので、そういった展開についても、他自治体の事例も参考にしながら検討してまいりたいと思います。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、ＡＥＤ管理費についてお伺いします。品川区ではＡＥＤの設置を進められておりますが、現状の設置台数、設置場所、また今後の取組について示すよう求めました。","respondent":"若生健康課長","answer":"設置場所としましては、区が設置している公共的な施設、それから学校、文化施設等も含めたところで２９０台となっています。今後、どういったところに設置できるかというところは、内部で様々検討しています。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問・要望","question":"スポーツをしていないときの１７倍に高まると言われているので、また、先ほどの健康ポイントアプリと連携した取組などはいかがでしょうか。場所に行くだけではなく、講習会に参加された場合にはスペシャルポイント贈呈などはいかがか尋ねました。","respondent":"若生健康課長","answer":"他自治体では、消防が入っている当該の自治体であれば、そういったところと連携して支援をしている例もあることは認識しています。今後、区民の方に、使い方も含めまして、ＡＥＤを認識していただいて、即時に対応できるような周知に、より分かりやすく努めていきたいと思います。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"ハトのふん害についてもお伺いしますが、以前のご答弁で、区民からの相談に応じて注意、看板の設置、パトロールなどを実施して対応していると伺っておりますが、その後、区としてどのような取組をしているのか示すよう求めました。","respondent":"河内環境課長","answer":"ハトの対応ですが、業者のほうで対応することに変わりはございませんが、実績、それから方法、価格などを勘案いたしまして、しっかりと実績が上がるようなものを進めるとともに、補助金などにつきましても、他の自治体の動向などを踏まえて検討を進めているところです。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私からは、２点お伺いいたします。３０７ページの猫の不妊・去勢手術費助成、３０１ページの不妊治療助成事業について、それぞれお伺いしてまいります。","respondent":"舩木生活衛生課長","answer":"１９の地区を指定していたわけですけれども、新たにこういった取組を考えてみたいというお声を二、そういう部分をご案内しています。認定前の管理頭数が３８８頭に対しまして、現在２１８頭と、１７０頭ほど減少している状況にあります。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"共生モデル地区での不妊・去勢手術の数を見ると、着実に地域猫の数も減っているということを確認させていただきました。そういった意味で、例えば５人いれば、不妊・去勢手術を一般枠よりもさらに助成が利いたりしていくようにするのはいかがか尋ねました。","respondent":"舩木生活衛生課長","answer":"年内には区の中の規定を整備して、遅くとも年明けには区民の方に周知できるのではないかと考えております。活動の公益性とか公共性をしっかりと支援していくということが大切だと考えていますので、その点、考えていきたいと考えています。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"続きまして、３０１ページの不妊治療助成事業について質問いたします。ぜひ品川区独自で、特定不妊治療の先進医療に対するさらなる助成金制度を求めますが、品川区のご所見をお伺いしたいと思います。","respondent":"若生健康課長","answer":"かかった費用の１０分の７を助成するということで、あるいは自由診療に対する助成まで広げている区もあるということは認識しているところです。必要性を慎重に見極める必要があると考えていますので、都の状況ですとか、他自治体の実績なども注視しながら研究してまいります。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"意見","question":"１０分の７という手厚い支給がありますけれども、先進医療をしたらどうかとなったとき、混合診療になれば全て実費の支払いともなります。ほかの区ではやっているところもありますので、品川区として寄り添った対応として、今後検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"３２９ページのプレミアム付区内共通商品券発行助成について伺います。区商連の皆様と、令和６年度の政策要望に関して意見交換をさせていただきましたが、電子化への移行検討に対するサポートのご要望をいただきました。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問は、いわゆるデジタル商品券についてのご質問と認識しております。デジタル商品券は、ただいまご指摘のようなメリットがある一方で、利用者あるいは店舗側の課題もあるということで認識しています。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"デジタル化を一気に進めて得られる効果を考慮すれば、スマホ教室を年間１,０００回やっても２,０００回やっても、無駄ではないと考えます。おのおの課題への考えを説明いたしましたが、感想を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいまの店舗側の換金手数料の問題ですが、利用者側の対応ということでご指摘ございました。こういう課題をどうクリアにしてやっていくかということも含めまして、引き続き検討なり協議を続けてまいりたいと思います。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"これらの実現を要望し、このテーマを終わります。続いて、先ほど他の議員が質問されておりましたが、２９３ページの健康ポイント事業運営委託について伺います。","respondent":"若生健康課長","answer":"健康ポイント事業で昨年度実施後のアンケートに関して、１点目は、イベントポイントというところのイベントが少なかったという声がありました。１位が商品券の要望で、楽天ポイントなどのポイントに還元できるようにしたいとか、そういった声があったところです。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"次に、３２５ページの中小企業事業資金融資あっせんに関連して伺います。そこで、現在実施している緊急資金支援制度を利用することができるのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"現在、区では緊急資金としまして、物価高騰等総合支援資金というものを設けております。設備資金、運転資金というものに対して苦しい事業者の方に対して、利用が可能な制度となっているところです。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"増税分が考慮される税引き後利益５％減も対象にするか、もしくは消費税支払い分を融資対象にするなど、条件が満たしやすくなる変更を要望いたします。品川区が地元の税理士に依頼し、納税申告事務の相談教室を設け、納税手続をサポートするのはいかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"現在、スマホアプリのみで会計事務ができるようなソフトというのも出ていて、それに対する国の補助なども出ているところです。こういったいろいろな制度、相談制度も含めまして、ご支援・ご案内をする中で、対応を進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"どうしたらいいのかというのに対して相談をする窓口かと思うのですが、手取り足取りやってくれるものではないのかなと理解しております。ぜひとも前向きに今後ご検討いただきたいと要望させていただきまして、質疑を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"２９５ページ、休日診療委託、３０３ページ、予防接種費、３０１ページ、健康診査費、時間があれば２９５ページ、公衆浴場について伺います。以上３点伺います。","respondent":"若生健康課長","answer":"これを、通常の休日・祝日ですと、昼間は１医療単位を２班用意するということで、さっきの単価の２倍を委託料として支給しています。それから、いつから委託料が変わっていないのかというところについては、すみません、手元にデータがございませんので、答弁を差し控えします。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"少なくともこれは継続すべきではないでしょうか、伺います。ですから、上げるべきではないでしょうか、伺いたいと思います。","respondent":"若生健康課長","answer":"その体制として委託料で実施していただくというのは大前提で、それは区の扱っている範疇と違う話になってきて、要は。そう考えますと、必ずしも診療が減ったことが問題かというところは、いろいろと考える必要があると認識しています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は伺ったのですが、少なくとも、今のコロナの加算をやめる状況ではないと思うのですけれども、少なくともこれは継続すべきではないか。医師会の皆さんも、そういう強い思いがあるわけですが、もう一回伺いたいと思います。","respondent":"若生健康課長","answer":"コロナの加算についてですけれども、これは今年度も継続はしております。次年度の予算の話になってきますので、こちらでも医師会の状況とかも十分確認しながら、これについては考えていきたいと思います。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"十分確認した上で、しっかりと私は継続してほしいと求めました。既に中野区などは始めていると伺っていますが、お考えを伺います。","respondent":"坂野保健予防課長","answer":"国の検討状況を総合的に勘案しまして、ＨＰＶワクチンの男性接種に係る区市町村への支援について検討してまいります」という答弁がされているです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ぜひ素早い対応というのをお願いしたいと思いますし、品川区として、ぜひやってほしいと求めました。分かればでいいのですけれども、就学前の追加接種をやっているお子さんというのはどれぐらいいらっしゃるのか、分かれば伺いたいと思います。","respondent":"坂野保健予防課長","answer":"ＤＰＴの追加接種ということですが、申し訳ございません、区として何人、どれぐらいやっているかという数字の把握は、持っていない状況です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほとんどおられないと思うのです。ですから私は、就学前の三種混合ワクチン接種への助成というのも実施してほしいと求めましたが、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"今、三種混合ワクチンについては、ワクチンそのものの変更とか、接種時期の追加あるいは変更等も含めて、総合的に国のほうで検討しておりますので、区としてはその動向を注視してまいりたいと考えております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"１点だけ。区民や関係者から要望が上がっているのですが、ぜひやってもらいたいのですが、やっていない理由というのをお伺いします。","respondent":"坂野保健予防課長","answer":"特定健診での超音波検査ということですけれども、具体的にどの部位が対象なのかが分からないものですから、何ともお答えし難いところです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"確認","question":"３１８ページ、３２９ページ、これは時間があればお伺いいたします。確認したいのですが、トレーナーのレベルをある程度落としてやられているのか、その点はいかがか尋ねました。","respondent":"若生健康課長","answer":"個人レッスンというか、パーソナルレッスンを中心にやっている、ある程度そういった層の方がご利用されているようなところを聞いてあります。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"エスフォルタ直営店と同じようなレベルのトレーニングとか、そうしたご指導をいただけると、大変ありがたいと感じております。その点はいかがお考えなのかということと、健康センター事業で区民の健康増進の効果というのは出ているのでしょうか、伺います。","respondent":"若生健康課長","answer":"最近は２４時間ですとか、そういう意味では、民業圧迫にはなっていないかなと認識しています。満足度調査の結果を見ましても、満足度というのは８割を超えている状況でございまして、そういったところで十分効果は出ているものと認識しています。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"今、モニタリングのお話が出ましたけれども、令和４年度の総括シートによりますと、令和２年度・令和３年度は収支で赤字が出ております。これはコロナが原因かなと思っているのですけれども、令和４年度は収支がぴったり０円になっているのですが、これはどういった理由なのか尋ねました。","respondent":"若生健康課長","answer":"令和２年度については大幅に補填といいますか、区としてその分を穴埋めというか、そういうことをしています。先日モニタリング調査でご報告した収支０円になっているのは、令和４年度は戻ってはきたのですけれども、収支が０になっているという状況です。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"区民料金が品川健康センターは５００円、荏原健康センターは４００円になっているのですけれども、区民の方と区外の方が同じという状況だと思います。ですが、そろそろ区民の料金と区外の方の料金に差をつけるべきかなと考えておりますけれども、その点はいかがお考えか尋ねました。","respondent":"若生健康課長","answer":"５００円、１００円安くしているところですけれども、区民のほうが優先に利用していただけるような配慮をしているところです。受付事務が煩雑になるとか、いろいろそういったところもございまして、現状では料金に差を設けるのは難しいというところで認識しております。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"住所確認とかをすればいいだけかなと思っていますので、そろそろ区民の方が５００円だったら、よろしくお願い申し上げます。品川区に問合せが来ているのか、また、そうした症状が出ている方などの把握をされているのか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"ワクチン接種後の、いわゆる後遺症、遷延する症状ということのご質問かと考えています。ただ、健康被害救済制度の受付窓口ですので、そうしたところはしっかりと区民の方に説明して、受付をしていきたいと考えています。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"新型コロナワクチン後遺症対策プログラムを打ち出して、ふるさと納税型クラウドファンディングで皆様からのご協力を募るということをやっております。こうした現状に対する区のご見解と、区民に対し適宜適切な情報提供をしていっていただきたいと考えていますけれども、お考えはいかがか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"国の審議会で検討いただいておりまして、その中で、現在重大な懸念は認められないという評価をされていると受けているところです。様々ありますので、ワクチンを打つことによるデメリットとリスクをお伝えした上で、ご自身が受けるかどうかをご判断いただければと考えています。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"そうなると、実際の出産にかかる費用に近くなってきているとは思うのですが、今回、ギフト給付についてお伺いしたいと思います。区としてのお考えを伺います。","respondent":"若生健康課長","answer":"出産される方とか子育てをされる方への支援を主眼としておりまして、国の説明では、後の説明で。これは都道府県の広域連携をしてくださいという国の考え方もございまして、今後もクーポンというところで、区としては進めていきたいと考えています。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問・要望","question":"私も厚生労働省のガイドも確認いたしまして、将来的にクーポン広域連携など、効率的な給付方法について検討いただきたいということを確認しています。今年度の妊娠８カ月頃アンケートの結果を踏まえて検討ほしいと求めましたが、今年度のアンケート内容についても併せてお伺いいたします。","respondent":"若生健康課長","answer":"現金での検討です。繰り返しになってはしまうのですが、システム的な対応などがいろいろ煩雑になってきて、なかなか難しいところだとは考えてあります。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"物価高騰の中、家計に充てることは十分子育てにつながると考えておりますので、こちらは利用者の声もしっかり聴いていただきたいと要望いたします。かかりつけ医紹介窓口の利用ターゲットは、全区民になるか尋ねました。","respondent":"若生健康課長","answer":"かかりつけ医療定着推進事業についてですが、ターゲットは区民全体ということになってございまして、特に限定してございません。それから、利用者の年齢層等の属性については確認していないところなので、区としても把握していないところです。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"かかりつけ医紹介窓口から病院を紹介した際の引継ぎ体制などはありますでしょうか。この２点について見解を伺います。","respondent":"若生健康課長","answer":"そういった窓口を平日９時から５時までというところで、現状、電話とファックスもしくは来所というところになってあります。通常そういったものがない方で、困ったときにというところの引継ぎというところについては、考えてまいりたいと思います。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"１点目に、予防接種費についてお伺いいたします。２点目に、母子保健指導事業費についてもお伺いいたします。","respondent":"坂野保健予防課長、若生健康課長、石橋品川保健センター所長、小林商業・ものづくり課長","answer":"私から、予防接種アプリの利用実績についてだけお話ししたいと思います。今年の８月末時点ですが、２,４６４のアカウントで… 母子手帳アプリのご紹介がありましたけれども、こちらについては国の検討会で、そういったところの動向を注視してまいりたいと考えております。… 産後は赤ちゃん訪問や育児学級、健診、産後ケア事業などで、赤ちゃんと産婦のケアを実施しております。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"応援ギフトのメニューに入れていただくなど、必要な方が利用しやすいような工夫を要望いたしますが、区のご見解をお聞かせください。観光客誘致の取組にも注目しておりますが、今日は産業経済費ですから、行政評価シートの１０３ページのモンゴル高専についてお伺いいたします。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長","answer":"ご指摘にありましたように５月に、あるいは就職というところも含めた、いろいろ現地の学生との交流というのもやってきたところです。その中で、日本企業に対して技術的な部分、あるいは将来的な交流というところで… 今、委員からご指摘があったとおり、産後のお母さんが一人で抱え込んでしまうという事象は、出産後間もなく起こり得るとこちらも認識しております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"例えば交流した企業数が３社など、交流に関する指標も実績に追加していただくとよいのではないかと考えていますが、区のお考えをお聞かせください。例えば、五反田バレーとモンゴルとの実際の取引につなげていくためのステップを踏んでいくようなイメージを持っておりますが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"こういったことが将来的に、日本の就職というところでも活きてくる分野ではないかと考えています。区内中小企業の関心としましては就職が高いので、それプラス交流ということも今後拡大していけるように、いろいろ進めてまいりたいと考えております。","id":"exchange-035"},{"speaker":"澤田委員","kind":"質問","question":"３２７ページ、品川区運送事業者等燃料費高騰対策支援金、３０３ページ、各種がん検診についてお伺いします。対象事業の分野は運輸・水産とありますが、この事業の具体的な支援対象と支援実績について、示すよう求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいま、品川区運送事業者等燃料費高騰対策支援金についてのご質問がございました。トータルの支援実績としましては、３０８件です。","id":"exchange-036"},{"speaker":"澤田委員","kind":"確認","question":"支援対象、支援実績ともに確認いたしました。なぜ低かったのかとお思いでしょうか、そのお考え、区としての見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"昨年度、令和４年度の補正予算で実施した事業でございまして、２月１３日から３月１７日という期間の中で実施したものです。もう１点、品川区としてこういった助成金を実施する場合には、あるいは議会関係の広報の中でも情報を流させていただいたところです。","id":"exchange-037"},{"speaker":"澤田委員","kind":"質問・要望","question":"区報での周知や、団体、個別にタクシー会社などへの周知をされているということで、しっかり周知もされていることが確認できました。令和５年度も引き続き、支援策を継続して行っていただきたいと要望いたしますが、区としての見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"運輸事業者向け燃料費高騰緊急対策事業というものが実施されておりまして、中小の貨物運送事業者に対する支給というのも実施されているところです。こういった国とか都の経済支援という対応も含めて状況を見ながら、経済動向として、引き続き考えてまいりたいと思います。","id":"exchange-038"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ、困っている事業者の方たちのために何ができるかということを、区としても考えていただくことを要望いたします。続きまして、３０３ページ、各種がん検診についてお伺いします。","respondent":"若生健康課長","answer":"区では４０歳以上の世帯へ、まず、がん検診全体の個別のご案内通知を年度の前半にお送りしています。乳がんが５％、子宮がん検診は５.３％、受診率が増加しているといった効果が出てきているところです。","id":"exchange-039"},{"speaker":"澤田委員","kind":"質問","question":"それぞれパーセンテージも上がっているということで、ぜひこの取組を続けていただけたらと思います。１０月１日はピンクリボンデーとして、区内の１３橋梁がピンク色にライトアップされ、こちらはＳＮＳなどでは発信されたのか尋ねました。","respondent":"若生健康課長","answer":"１０月１日のピンクリボンデーのライトアップは、河川下水道課のライトアップのところとタイアップしてやらせていただいておりまして、ＳＮＳの発信というのはやっておりませんでしたので、今後検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問・要望","question":"例えばどうやったら防げるか、ぜひ併せて行っていただきたいのと、検診の大切さなどを訴えかけていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"最初に、３０３ページの予防接種委託、高齢者インフルエンザのワクチン接種についてお伺いいたします。医療的な部分でお伺いしますが、今年の流行の特徴をお知らせほしいと求めました。","respondent":"坂野保健予防課長","answer":"最新の数字ですけれども、東京都全体で定点当たり１６.５８ということで、この時期としては非常に異例のインフルエンザの流行が観測されているです。感染を抑える効果というよりも、重症化を抑えて、例えば入院などの件数を減らしていくという効果があるものかなと考えています。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢者の方の健康を守るという視点で、一部負担ではなくて、全額しっかりワクチン接種の助成をしていただきたいというのが公明党の要望であります。東京都との連携というのはばっちりであると考えていますので、その辺を強力に進めてほしいと求めましたが、見解を伺います。","respondent":"坂野保健予防課長","answer":"東京都と連携して、高齢者のワクチンの２,５００円の部分をというお話です。東京都とお話する機会等があれば、こういう意見があって、考えてくださいと、ぜひ意見は言いたいと思っています。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区が設定している目標よりも高い結果が出ていると確認していますが、予防と検診が発症を抑えていく重要な鍵となっていると思います。キャッチアップを含めて、さらなる勧奨を要望いたしますが、見解を伺います。","respondent":"坂野保健予防課長","answer":"令和６年度末、ですから令和７年３月までがキャッチアップ期間と今の時点では言われております関係で、未接種者に対する個別の勧奨を計画しています。時期は未定ですが、来年の夏前後をめどに考えているところです。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"区長もそのＳＮＳに反応されていたことも確認しておりますけれども、大きく集団免疫をつけていく中で、これを抑えていくと。よく情報を得て、早めに品川区として進めてほしいと求めましたが、改めて見解を伺います。","respondent":"坂野保健予防課長","answer":"ＨＰＶワクチンの男性への補助です。もし東京都から何らかのスキームが出た場合には、区としても考えていきたいと思いますので、よろしくお願いします。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都のスキームが出たらということですが、品川区はやりたいのだという姿勢をしっかり示した上で、スキームを待っていただきたい。その方向で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"おぎの委員","kind":"質問","question":"本日は３０３ページ、新型コロナウイルスワクチン接種についてお伺いします。品川区でも予防接種健康被害救済制度の申請の窓口を行っているようですが、品川区では、申請は現在何件か尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"書類に不備がないかを確認しましたら、東京都、また国に進達するという制度になっております。区の８月末現在の受理件数ですが、３６件受理しておりまして、そのうちの２９件を東京都・国に進達しています。","id":"exchange-047"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ワクチン接種を個人の判断に委ねる以上、品川区はホームページにおいて、デメリットの部分も周知に努めていると言えるでしょうか。これで区民にきちんと周知をしているとは言い難いと思われますが、どうか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"給付が決定しましたら、その給付手続につきましても、責任を持って速やかに進めていきたいと考えています。区のホームページでの周知ですが、厚生労働省のご案内をするとともに、区としましてもホームページを工夫していきたいと考えています。","id":"exchange-048"},{"speaker":"ひがし委員","kind":"質問","question":"最初に、母子保健費の産後ケア事業、特に日帰り型についてお伺いいたします。とても評判がよかったと伺っておりますが、また課題があれば、併せて説明を求めました。","respondent":"石橋品川保健センター所長","answer":"３％というところになっておりまして、昨年度はホテルで実施をしておりましたので、今後周知をしっかり図っていきたいとは考えております。","id":"exchange-049"},{"speaker":"ひがし委員","kind":"質問","question":"産後４か月未満の母親が、このような電話、また書類の作成などは負担になるのではないでしょうか。電話でのヒアリングもしているということをお伺いしておりますが、ネットで申込みができるようにするなど、デジタル化を進めていくべきだと思います。","respondent":"石橋品川保健センター所長","answer":"空き状況やケアの希望の確認をするなどということもあり、現在は電話にて受付を実施しております。利用者の年齢層なども検証し、より利用しやすい申請方法、空き状況の確認方法を検討してまいります。","id":"exchange-050"},{"speaker":"ひがし委員","kind":"質問・要望","question":"予約のデジタル化、また、仕組みのブラッシュアップについても検討していただきたいと要望します。このような事例を聞き、私は早期発見の観点においても課題だと感じておりますが、区としてはどのように捉えているのか尋ねました。","respondent":"若生健康課長","answer":"障害ですとか、あるいはエレベーターがなかったりといった状況もあるということで、そういったお問合せも区にいただいているところです。そういったところを課題として認識しているところではありますが、そういった対応というところにつきましては、実施医療機関ですとか。","id":"exchange-051"},{"speaker":"ひがし委員","kind":"質問","question":"例えば、現在送られている検診用紙の病院の一覧に何か一言記載するなど、配慮があればと思うのですが、いかがでしょうか。答えられる範囲でご見解をお願いします。","respondent":"若生健康課長","answer":"お知らせを検診の実施機関の一覧に表示してはというご提案でしたが、例えば車椅子対応可とか書いても、実際通れるかどうかとか、幅とか、いろいろその方の状況によっても異なるので、なかなか一律には難しいですけれども、今後、医師会等と意見交換してまいりたいと考えています。","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"３０５ページ、横断して３２３ページの中小企業活性化事業費、時間があれば３０５ページの新型コロナウイルス感染症対策をお聞きします。９月の本会議において、それ以外の場所においての設置の検討はありますか尋ねました。","respondent":"若生健康課長","answer":"ＡＥＤの設置拡大につきましては、様々検討を進めているところでございまして、まずはコンビニへの設置に向けて、今検討を進めているところで、その設置を進めていった先に、またほかのところについては検討してまいりたいと考えています。","id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本当だったら、１分蘇生作業が遅れると１０％救命率が下がるというデータもあって、本当に泣く泣く断念したというようなこともあります。初期費用ですと３２万円余まで、やはり命を守るというところで検討してほしいと求めましたが、いかがか尋ねました。","respondent":"若生健康課長","answer":"基本健康課として進めていることは、区立の施設であれば設置が済んでいるですが、そのようなところは課題であると考えております。それから設置補助、まずは確実にコンビニへの設置というところについて進めて、その後助成等も視野に入れて考えてまいりたいと思います。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"横断的なことだと思うのですけれども、ぜひ早急に、前向きに進めてほしいと求めました。中小事業活性化事業ですけれども、あっ旋事業というのは、物価高騰等総合支援資金というような名目のあっ旋事業でよろしいか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"そのとおりで結構です。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私が聞き逃していたら申し訳ないのですが、結果的におっしゃられた税引後利益にしてほしいというような要望に対しては、お答えはいかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"物価高騰等総合支援資金につきましては、やはり目的として、物価高騰というところを対象に要件としております。そういったところでは、そういった売上条件をつけていないものもありますので、そのような中で活用できるものもあろうかと思います。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えばインボイスの導入でお困りの方において使えるあっ旋事業というのは、制度的にどういったものがありますか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"例えばそういったインボイス対応も含めてということで、そのほかにも小規模事業者を対象としたような専用メニューがありますので、そういった中で活用できるものもあろうかと思います。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それが区の中でできることがあれば、例えばそういった支援事業など、やっていけるようなことをぜひ考えていただきたい。多くの、そこで何か区で現在考えていることなど、そういったものがもしあれば、示すよう求めました。","respondent":"小林商業・ものづくり課長","answer":"こういった中での活用や、あるいはインボイスに関わるところでいきますと、国の支援制度があります。このようなものを適切にご案内しながら、支援を進めてまいりたいと思います。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"時間がないので要望だけですけれども、やはり品川区のホームページを見ても、内容が薄いなと感じます。国の事業とはいえ、そこは区でしっかりできる限りのことをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こしば委員","kind":"質問","question":"小児インフルエンザワクチンに関連しまして、インフルエンザワクチンの乳児への接種費用についてお伺いいたします。その前の６か月から１歳までの間の乳児のワクチン接種費の補助が今年度も見送られた、この理由について区のお考えを説明するよう求めました。","respondent":"坂野保健予防課長","answer":"実際問題、幾つかの区が少しずつ拡大をしていまして、現状６か月から打てる区が、２３区のうち８区です。大事な課題だと私も認識しておりますので、今後年齢の拡大については検討していきたいと考えております。","id":"exchange-060"},{"speaker":"こしば委員","kind":"質問","question":"理由についてお聞きしたので、ちょっとその辺りも。もう１回答弁いただけるようでしたらお願いします。","respondent":"坂野保健予防課長","answer":"従前より、１歳から１５歳というものでやっていたので、ご要望はいただいていたと。実際問題、１歳からやっている自治体がかなり多いということも現状です。","id":"exchange-061"},{"speaker":"こしば委員","kind":"質問・要望","question":"そして支援すべき乳児を育てるご家庭に対しては、大体２万円前後となる親子の接種費用を全てご家庭で負担しなければならないということにもなります。その８区で、今後もこの６か月以上のワクチン接種の拡充に向けて強く求めたいと思いますが、改めてご見解をお伺いいたします。","respondent":"坂野保健予防課長","answer":"今お話あったとおり、この８区というものも少しずつ増えてきて８区になっているという現状もありますので、今後、検討の俎上に乗せていきたいと考えております。","id":"exchange-062"},{"speaker":"こしば委員","kind":"提案","question":"ぜひ強く要望して、時間があまりないので次の質問へ進みます。実習形式で子どものケアを実際に学ぶ教室こそ、安心して子育てに取り組める提案だと、会派としても実現を要望してきた経緯がありますとの意見を述べました。","respondent":"石橋品川保健センター所長","answer":"令和５年２月、品川保健センターにて、乳幼児健診にいらした３３８名の保護者の方に、薬の飲ませ方というアンケートを実施させていただきました。今後その件に関する相談が増えたり、お子さんを持つご家庭からの要望がありましたら、検討していきたいと考えています。","id":"exchange-063"},{"speaker":"こしば委員","kind":"質問・要望","question":"今お答えいただきましたとおり、アンケートからたくさんの気づきがあったと思います。ぜひその気づきを具体的な政策、施策に置き換えて、検討の先、ぜひ実現に向けて取り組んでいただきたいと思いまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"つる委員","kind":"質問・要望","question":"３１３ページ、３２９ページ、消費者啓発費について伺っていきたいと思います。保健衛生のほうを伺っていきたいと思いますが、その対象とする事業についての裁量というものは区にあるのかどうか、これを説明するよう求めました。","respondent":"若生健康課長","answer":"医師会等への助成金のお尋ねです。環境衛生協会に助成金を支給しているところでございまして、こちらにつきましては、区の要綱に基づいて支給をさせていただいているところです。","id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"アドバイスしたくてもできない、分からない、こうした課題も一方であるというようにも伺いました。このような社会福祉士などを雇用する、そのような枠組みの中でこの助成金というものは、枠として活用できるのかどうか説明を求めました。","respondent":"若生健康課長","answer":"かかりつけ医、ちょっと医療以外で対応できない部分については、適宜区にお問合せをつないでいただいているような状況もあるかと認識しています。しながわガイドもありますけれども、それも含めまして、ちょっと考えていきたいと思います。","id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"過日の第２回定例会で、産後ケアの拡充という視点で質問させていただきまして、その拡充を求めたところであります。それが満たされる部分もあろうかと思いますが、ぜひ今の回数増に対する検討状況と年齢の拡充についての考え、これを説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"私のほうも表記が違うことは認識しておりまして、修正させていただきたいと考えていますので、よろしくお願いいたします。対象の拡大、こういったところは今検討しているところになりますので、しっかり取り組んでまいりたいと考えています。","id":"exchange-067"},{"speaker":"つる委員","kind":"提案","question":"ここは時間の関係で答弁は特に求めるものではありませんが、それこそ先ほどの話ではないですが、あるのであれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長","answer":"この中で、ただいまご指摘ありましたファッションショーも、初めてエシカル商品のイベントとして実施するところです。実施に当たりましては、その反応を見ながら、今後またよりよい啓発イベントを考えていきたいと考えています。 先ほどの答弁ですが、まずは利用回数の増加について検討してまいります。乳腺炎についてですが、母乳ケアを産後ケアの中で拡大するということで、対応を検討しています。","id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ですから、そこはぜひそういったものを組み合わせてやってほしいと求めましたが、お答えください。令和になってどのようなイメージなのか尋ねました。","respondent":"河内環境課長、若生健康課長、品川品川区清掃事務所長","answer":"一方で、カラスの対策の中で、区の、例えば苦情の報告件数ですが、令和３年、４年と増加してきている状況です。カラスの捕獲方法も含めて… がん検診の啓発というところで、ご提案等いただきました。国など様々な情報と併せまして、効果的な周知の方法をＳＮＳも含めまして検討してまいりたいと思… 今まではやはり臭い、汚れ等、こういったところが非常に気になる点でした。","id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これ、ＤＸだ何だといろいろ言って、スマホを使えない人はどうするのですかという話になるのです。ポイントカードがあるではないですか、まだ。","respondent":"佐藤企画課長","answer":"地域通貨の内容および効果につきましては、委員ご紹介のとおりということで私どもも認識しております。もしくは区民の方の参加をより進めることであったり、今後様々な視点から、情報収集しながら考えていきたいと考えています。","id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問","question":"いろいろ支払い方法もあって、でも、それはもう民間の企業でも同じではないですか。デメリットの話も出ていますけれども、私はこれメリットしかないのではないかなと思うのですが、最後にどうか尋ねました。","respondent":"佐藤企画課長","answer":"委員の様々なご提案でありましたり、メリット、デメリットのご紹介をいただいております。そちらに関しましては区として十分認識しておりますので、様々な角度から、収支も含めて、その有効性、活用性も含めて検討してまいります。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから２つ目は、２９２ページの健康推進費から、リプロダクティブ・ヘルス・アンド・ライツの取組を求めて質問したいと思います。もっと増やすべきではないかということで質問したとき、でも医師会の先生に伺ったら、２回でいいとは言っていないと。","respondent":"若生健康課長","answer":"令和元年６月から開始しておりまして、当初から４５歳と５５歳という、当初この２年齢で開始をしているという経緯があります。必要性は十分認識しているものの、その他の任意で区がやっている健診については、状況を見ながら検討を進めていくということで考えてあります。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことなので、ぜひ早期発見・早期治療、失明させないためにも、検診を４０歳からで毎年に拡大していただきたい。今改めて、リプロダクティブ・ヘルス・アンド・ライツについて、担当部署としてどう考え、捉えているか、認識を伺いたいと思います。","respondent":"若生健康課長","answer":"リプロダクティブ・ヘルス／ライツについての認識です。リプロダクティブ・ヘルス／ライツ、こちらについては女性の生涯を通じた健康を支援する取組の重要性について認識を高めるという観点を持ちつつも。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問","question":"この権利だということ、自己決定とそれのケアを受ける権利だという、権利という認識があるか伺いたいと思います。先日も総務費のところで少し質問したのですけれども、ポイントなのではないかと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"若生健康課長","answer":"権利としての認識があるかですが、先ほどの答弁とちょっと繰り返しのところもありますけれども、そういった生殖に関することや自己決定権、そういったところも含めまして、女性の健康を支援する概念というように、区としては捉えているところです。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこをなぜどこで聞いても言えないのかというのが、ちょっと私は理解できないところです。環境整備、取組が求められていると思うのですけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"以前の答弁でも申し上げたところではありますけれども、健康プラン２１に女性の健康を守るといった項目を掲げてあります。考え方として、女性の健康を支援するというような観点での取組の考え方は含んでいるというような認識ですので。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう本当に先進国としては異常な低さという状況ですから、これに対して区としてどう認識してどう取り組むかということが求められていると思います。１人で追い詰められている状況だということだったのですけれども、区としても相談の窓口をつくるべきではないかと思うのですが、いかがか尋ねました。","respondent":"若生健康課長","answer":"きちんと組織的な対応といいますか、きちんと関係機関と共有して対応を進めているところですので、今後もそういった形で進めてまいりたいと考えております。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"包括的性教育については、これは教育費なのでここでは答弁を求めませんけれども、私は大人も性教育を受けないまま大人になっていると思うのです。本当に世界から見ても遅れた状況ですから、このことについても取り組むべきだと思うのですが、いかがか尋ねました。","respondent":"石橋品川保健センター所長、若生健康課長","answer":"私からは、望まぬ妊娠の件数ということでお話しいたします。こちらの件数に関しましては、統計を特に取っておりませんので持ち合わせておりません。 大人の性教育、ちょっと性教育の観点が非常に健康部門でも把握するのは難しいというところは考えております。やはりこれは国全体でいろいろ考えていかなければならない課題ではないかと認識しています。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう国がとっくに遅れているので、自治体としてもぜひとも取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"田中委員","kind":"質問・要望","question":"３２７ページ、産業経済費、商店街活性化事業についてお伺いします。関連して、衛生費の３１１、３１９ページにありますカラス対策も絡めてお伺いしていきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"ただいまご指摘のありました補助２９号線に関わる商店街の振興ということで、ご質問ございました。その先ということでいきますと、いろいろ商店街に対する支援をやっておりますので、こういった中で商店街と一緒に進めてまいりたいと考えております。","id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"その間も、再三申し上げている道路整備が終わった後の商店街が再生するところまで対応いただけるような支援を、ぜひお願いしたいと思います。ハト対策といった視点も含めて、環境課としてこのようなアーケード内の対策が行われるのかどうか確認していきたいと思います。","respondent":"河内環境課長","answer":"こういったものの対応を進めているところでございまして、保護の対象となっているところから、なかなか難しい対象です。対応といたしましては、ケース・バイ・ケースの中で最適解を出しながら、今対応しています。","id":"exchange-080"},{"speaker":"田中委員","kind":"質問","question":"ですから、ハトの巣を作りづらいようなアーケードの構造にしていくことも、このような対策につながるのかなと思います。私はぜひこの事業を活用することで、動物も愛護しながら対策を講じていくということも必要かと思いますが、いかがですか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問につきまして、活性化事業ということで商店街の支援のメニューがあります。ちょっと個別に、このような事業をできるだけ活用できるように、我々も相談対応していきたいと考えています。","id":"exchange-081"},{"speaker":"田中委員","kind":"質問・要望","question":"１つ、平成二十数年頃に東京都商店街振興組合連合会の要望も受けまして、結果的にはつけることができました。大田区などもできておりますので、ぜひこういったことも前向きに捉えていただいて、新しい支援策を講じてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは２９９ページ、妊婦健康診査、３０５ページ、精神保健事業、３２５ページ、景況調査委託等、この３点をお伺いしたいと思います。この点について区の見解をお聞きしたいということと、そこを確認させていただきたいということと、未受診の要因についても併せて、答えるよう求めました。","respondent":"若生健康課長","answer":"区としてこの重要性を踏まえて実施しているところでございまして、低い理由につきましては、やはり様々あろうかとは思います。そこと若干かぶるところもございまして、それにしても若干低いということは、課題として認識しています。","id":"exchange-083"},{"speaker":"こんの委員","kind":"提案","question":"こうしたことはどうでしょうかとご提案をしたいのですが、それは、こうしたことも受診の促進につながるのではないかと考えます。いかがか尋ねました。","respondent":"若生健康課長","answer":"ご指摘いただいたとおり、若干今分かりにくい状況があるというところは認識できましたので、こちらは工夫をしてまいりたいと思います。クリーニングというものも１つの方法かとは思いますけれども、まず受診率の向上に向けて、啓発に注力してまいりたいと考えています。","id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"今障害者、妊産婦の方々のこうした健診にもこうしたことは考えられるということだと思いますので、ぜひこの先ご検討などしてほしいと求めました。件数などが分かれば教えていただきたいということと、この入院についての実態など、簡潔に説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"医療保護入院の件数は、品川区では年間約３００件前後を推移しているような状況になっております。それから主治医がいらっしゃる場合は主治医と連絡を取ったりして、細やかな連携や調整など、そういった相談支援を行っているところです。","id":"exchange-085"},{"speaker":"こんの委員","kind":"意見","question":"そうした場合に、民間の移送事業者を活用するわけですが、その料金が１０万円から１５万円かかるというのです。この点についてご見解を説明するよう求めました。","respondent":"榎本荏原保健センター所長","answer":"民間の救急などを利用されることも承知しております。ご本人の病識がなく、同意がない中で進めていくということもございまして、なかなかその移送費の支援というものは難しいと考えております。","id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私はこれはぜひ積極的にやっていただきたいと思っていて、コロナの前は研修で１週間や２週間ぐらい、やめたほうがいいと思っておりました。２年なのか、このようなことがやはり品川区でぜひあってほしいと思っていて、この辺のところをぜひもう一度取り組んでほしいと思っていまして。","respondent":"崎村人事課長","answer":"行政と異なる考え方や業務の進め方などを学ぶことによって、ある意味行政としての施策の在り方を再考するですとか、これまで実施してまいりました。","id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"意見","question":"例えば東京２０２０大会組織委員会へ派遣をしたら、もう一度その辺のところも踏まえて、何があってもやっていくのだと。ぜひその辺のところをもう一度、どのように取り組んでいくか言っていただければありがたいと思いますとの意見を述べました。","respondent":"崎村人事課長","answer":"あと品川区で働き続けたいというような組織風土をつくっていくことも非常に重要だと考えておりますので、そういったことも併せて取り組んでいきたいと考えております。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは関連するかどうか分からないのですが、これをいろいろお伺いすると、なかなか限られるということがあると思っています。では休みの時間をどう活用してということもあると思うのですが、これはどうやって取り組もうと考えていらっしゃるか、これも併せてお願いします。","respondent":"崎村人事課長","answer":"今年の４月ですけれども、全庁に向けて、例えば職員の兼業の扱いについてアナウンスをしたところです。といいますのも、今お話しした社会貢献や地域貢献の活動にはあると考えておりますので、積極的に職員については進めていきたいと考えております。","id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは分かるのだけれども、ぜひそこは範囲を広げてほしいなと、これはお願いだけしておきます。やってしまったほうがいいと思って、このような方向から入っていくことも１つだと思いますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"西村委員","kind":"提案","question":"様々委員から質問が既にありますので、私からは具体的に提案をします。改めて拡充の要望をさせてほしいと求めました。","respondent":"石橋品川保健センター所長","answer":"養育者の方の悩みや相談内容は赤ちゃんによって違うため、２人目以降の出産も大変であるということも大変認識しております。先ほども申し上げましたが、国の要綱が改正されたこともありますので、今後宿泊型の事業についても検討は進めていきたいと考えております。","id":"exchange-091"},{"speaker":"西村委員","kind":"質問","question":"日帰りの所要時間２時間半と同じように、時間の拡充を検討していただくことはいかがでしょうか。区のお考えを伺います。","respondent":"石橋品川保健センター所長","answer":"いろいろ悩みを抱えていらっしゃる方が多いということで、産婦により産後の不安や悩みが違うことは認識しております。こちらもケア内容の充実を含めまして、どのくらいの時間が必要かということも併せて検証してまいります。","id":"exchange-092"},{"speaker":"西村委員","kind":"質問・要望","question":"実際に受けられたお母さんから、６０分以上いてくださったというようなお話も聞いたことがありまして、改善につなげてほしいと求めました。所長の思いと意気込みを説明するよう求めました。","respondent":"石橋品川保健センター所長","answer":"当然、事業自体のバージョンアップをしていくということも必要だとは考えておりますし、きれいで充実した設備が整っているものになります。利用者の方に、品川区の産後ケアはすごくいいよねと言っていただけるような事業を目指して頑張ってまいります。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問","question":"ホームページやチラシの多言語化、メニュー改正などのメニューがありましたが、コロナ禍で少し取組は落ち着いていると伺っています。７月補正で計上するに至った経緯等をお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"それを受けまして、この補助事業を使って、実際に商店街のほうでもまた多言語化対応の取組を進めようという具体的な動きが出てまいりました。品川周辺で、インバウンド向けの対応というものがより進むのではないか、区としても支援してまいりたいと考えています。","id":"exchange-094"},{"speaker":"西村委員","kind":"提案","question":"総務費でインバウンド対応力の強化について提案させていただきましたけれども、この産業経済と捉えてどうお考えか、お聞かせほしいと求めました。ＰＲ販路の拡大、サービス醸成などに支援の助成ができないか、現状の取組と区のお考えを伺いますとの意見を述べました。","respondent":"小林商業・ものづくり課長","answer":"この多言語化対応というものがありますし、観光客をどう受け入れていくかという取組は商店街の支援でも重要であると考えております。このような部分は、観光部門とも連携して進めてまいりたいと思います。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、中小企業活性化事業費について伺ってまいりたいと思います。商店街でも使っていただいていると伺っています。","respondent":"小林商業・ものづくり課長","answer":"個人事業主、中小企業を問わず、法人問わずということで対象として実施しています。このような取組の中で、今物価高騰、エネルギー価格の高騰などにも、事業者支援で使っていただければと考えています。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"予防にもなりますが、接種していない方々と接種した方々で具体的なエビデンスというか、データ効果が出るのは何年も後になると伺っております。なぜ男性が接種する必要があるのかということ、何か対策といいますか、アイデアや区のお考えがあればお聞かせほしいと求めました。","respondent":"坂野保健予防課長","answer":"予防接種法上の定期接種については、第５条の１項に定期接種がありますので、積極的勧奨が行政はできるということです。未接種者に対する個別の勧奨など、そのような手をいろいろ工夫して、接種率の向上に努めてまいりたいと考えております。","id":"exchange-097"},{"speaker":"西村委員","kind":"意見","question":"引き続き周知に努めてほしいと求めました。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、このコロナ禍の影響で、どのように事業内容が変更しているのか、現在はどのような活動状況にあるのでしょうか。それも説明を求めました。","respondent":"若生健康課長","answer":"令和２年度と令和３年度はほぼ休止といった状況でございましたけれども、令和４年度につきましては、活動を元に戻していく方向で各地区進めてきたところです。","id":"exchange-099"},{"speaker":"木村委員","kind":"意見","question":"コロナが５類に変わりまして、この安心感とは、どのようなことでこの安心感があると思われますか。これもお考えを説明するよう求めました。","respondent":"若生健康課長","answer":"コロナ５類後の状況と安心感です。これはとても人気のあるプログラムで、そういったことも、委員のおっしゃる安心というものにつながっているように認識しております。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひこの事業、いろいろと事業ありますけれども、頑張ってほしいと求めました。次に２９５ページからですけれども、１,０００万円余ですが、その意味を説明するよう求めました。","respondent":"若生健康課長","answer":"ちょっと名前が似ているふれあい健康塾の違いですけれども、健康塾のほうは区内のシルバーセンター等の２３か所の会場で、週１回実施しております。６か月を１つのコースとしているプログラムで、実施内容については、割と活動的な高齢者の方を対象にしている。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"定員数はどれぐらいを見込んでいるのか、そしてこの健康塾の最終点、目標はどのような点においての健康づくりなのでしょうか。説明を求めました。","respondent":"若生健康課長","answer":"コロナ対策として、定員を半数程度で２グループに分けてということで、それぞれ隔週で実施しておりまして、これは現在も継続しています。体の機能を維持、もしくは高めていただいて、健康に過ごしていただくということを目標にしています。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"会場はシルバーセンターだと思いますけれども、定員数は今言われました二十何名ですか、それを２つに分けるということでありますが、この健康塾の最終点、目標というものを、もう一度説明を求めました。","respondent":"若生健康課長","answer":"目標、到達点というところで、ちょっと繰り返しになってしまうのですが、参加していただいた方に少しでも健康増進をしていただく、体の機能を高めていただいて、生き生きと暮らしていただくと、そういったところを目標、到達点としています。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"現在の品川区に、この品川区をつくり上げてきた高齢者の皆さん、今までのこの方々も本当に大事にしてほしいと求めました。そして、人情味あふれる品川づくりをぜひお願いしたいのですが、行政としてのこれからのお考えをもう一度説明を求めました。","respondent":"若生健康課長","answer":"こういった健康づくりの施策を横断的に進めていって、区民の健康増進、福祉の向上に努めてまいりたいと考えています。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"１点目ですが、担当が違うとなれば指摘していただきたいのですけれども、避暑シェルターの担当はどこになるのでしょうか。お聞きします。","respondent":"勝亦総務課長","answer":"夏場の避暑シェルターにつきましては、総務課で全庁の調整、取りまとめを行っております。","id":"exchange-105"},{"speaker":"西本委員","kind":"提案","question":"今年の夏はコロナが５類になったということでは、特に暑かったですから、どうもそのような雰囲気ではなかった。これに対しての指導や改善提案というものは、総務課でよろしいのか尋ねました。","respondent":"勝亦総務課長","answer":"ちょっと実情等については、各施設において管理しているというところで、こちらのほうで具体的な現状、指導という形は取ってはおりません。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"掲げているのはいいのですけれども、では誰が指導するのですかということなのです。ですから、総務課のほうできっちりと確認をするとか、いかがか尋ねました。","respondent":"塚本委員長、勝亦総務課長","answer":"ちょっと款が各所管にわたってしまうので、これは総務課として一応答えられる範囲で答えていただければと思います。 避暑シェルターにおきましては、できるだけ区民の方が来やすいような整え方をしたいと考えています。利用しやすく、気持ちよく使っていただけるように対応していただくことは、それぞれの施設でもやっていくことだと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"次に、２９５ページのＡＥＤ管理費のところですが、今、女性に配慮したＡＥＤの使用方法というものがあります。そのようなものをぜひ啓発していただきたいと思うのですが、それは、その情報は行っていますか尋ねました。","respondent":"若生健康課長","answer":"女性に配慮したＡＥＤの使用方法ということで、こういったやり方の説明があるということは、私どもも情報をキャッチしているところでございまして、今後ホームページ等でそういったものも掲載できるような形で、工夫をしていきたいと考えております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そういうやり方があるのですから、ＡＥＤのマップというものがあります。ですから、どのように使えるのかというところまで訓練が必要になるかと思いますが、いかがか尋ねました。","respondent":"若生健康課長","answer":"町会などといったところで行われているところにということだったのですが、ちょっと周知の方法については今後検討してまいりたいと考えております。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"ですから、まず啓発をぜひお願いしたいと思います。それぞれ目的があると思うのですが、その目的、同じであればこれを統合していくのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守りおむつ定期便は１１月からスタート予定となりますが、育児の不安などをお伺いし、同時におむつなどの育児用品をお渡しする事業となります。","id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"くれぐれも二重行政、二重にするということのないように、それぞれ特徴を見いだして、協力しながらお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"若林委員","kind":"質問・要望","question":"それから、３２９ページのプレミアム付区内共通商品券発行助成では、令和４年度は商品券、紙で４億円と秋は６億円、足して１０億円ですかね。これは５億円というところで、ここら辺の確認なのですが、これは現状の確認です。","respondent":"坂野保健予防課長、舩木生活衛生課長、小林商業・ものづくり課長","answer":"それで、それに準じて保健所設置市区、これに特別区が入ります。これ、１分、２分で説明できるレベルではないものですから、申し訳ございません。これまで新型コロナウイルス、約３年間、本当に様々な対応を取ってまいりました。報告書という形でまとめ上げていく予定ですけれども、そういうことを待た… この中で、商連に加盟している、加盟していないというところは、今データがございませんので、こちらはお答えができないところです。","id":"exchange-112"},{"speaker":"若林委員","kind":"意見","question":"この商店街、都の補助金等を使っているものもありますけれども、区の独自財源でやっているものがあります。そういったものを中心に、しっかりと私はまた見詰め直す時期ではないかなと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"３２３ページのシルバー人材センターについてお尋ねします。シルバー人材センターの事務局の方々はご苦労されていると思いますが、仕事の発注元と契約の状況について、現在どのような状況かお伺いします。","respondent":"小林商業・ものづくり課長","answer":"ただいま、インボイス制度の対応に伴っての影響ということでお尋ねがございました。その分の発注額の適正化ということをシルバー人材センター本体で対応することにより、会員の方にご負担が出ないようにということで対応する旨。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"区のほうが、つまり発注元の区が、十分確保されているかということをお尋ねします。そういった状況の中で、区で十分確保されているのか尋ねました。","respondent":"遠藤財政課長","answer":"シルバー人材センターの委託契約のお話かと考えています。出てきた部分で当然値上がりしているといいますか、出てきた見積りに沿った形で、予算計上はしていく形になるのかなと思っているところです。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、課長におっしゃっていただいたように、今後の発注元としての区の立場というのは大変重要になってくると思います。今、財政課長にお話しいただきましたけれども、所管の商業・ものづくり課長としての支援に対する決意を伺います。","respondent":"小林商業・ものづくり課長","answer":"会員の希望ですとか経験・能力に応じて仕事を引き受け、その分で収入も取っていただくという大変大事な取組だと考えております。引き続き、こういった活動について支援してまいりたいと考えております。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、約１億８,０００万円を要求したのですが、約２,２００万円を減らされた状況で、今年度の運営は円滑にいっているのか尋ねました。","respondent":"河内環境課長","answer":"努力してやっている状況でございまして、お客様に迷惑をかけていないというところで認識しています。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"意見","question":"どうして増やすというふうに要求したのかというところをお尋ねして、約２,２００万円も要求から減らされたけれども、大丈夫なのかと。どの点を増やそうとしたけれども削られて、それでも、どの点を増やそうとしたというところをお尋ねしていますとの意見を述べました。","respondent":"河内環境課長","answer":"視察などの対応で事業担当も必要なのですが、一方で、やはりご来場者を賜るためには広報活動の活性化ということも大事になっております。やはりほかとの兼ね合いがありまして、適正化というところで、そういったところに落ち着いたところです。","id":"exchange-118"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書３２５ページ、関連して主要施策の成果報告書１７ページの、どちらも事業承継支援事業について質問いたします。そこで、最初にお伺いいたします。","respondent":"小林商業・ものづくり課長","answer":"こうした中で、きちんと日本経済・社会を支えるような雇用・技術が失われることのないよう、区としても重要性を大変認識しています。品川区ではいずれの部分についても認識しつつ、あるいは、それに伴う設備投資に関する助成支援の措置なども取っているところです。","id":"exchange-119"},{"speaker":"まつざわ委員","kind":"質問","question":"そこでお伺いします。そうした難しい課題に適切な助言や指導を行っていくために、どのような専門家をそろえているのか、示すよう求めました。","respondent":"小林商業・ものづくり課長","answer":"あるいは株式、事業用資産の相続・贈与など、多くのステップを踏む必要があると考えているところです。こうなってきますと、こういう事業承継に関わるものにつきましては、これらの専門知識を有するスタッフというものをこの事業のために用意しています。","id":"exchange-120"},{"speaker":"まつざわ委員","kind":"質問","question":"事業承継の設備投資助成などを行っている、そういうご説明でしたが、これら全体の要は事業の実績というのはいかがでしょうか。私の感覚では、成果報告書でもありますこの執行率が伸び悩んだ理由について、示すよう求めました。","respondent":"小林商業・ものづくり課長","answer":"１つは、例えば設備投資を行いたいという要望がございましたら、それに対する支援助成を行っております。設備投資支援というのが、助成率２分の１ですけれども、事業の有効活用をしてまいりたいと考えております。","id":"exchange-121"},{"speaker":"まつざわ委員","kind":"質問","question":"すなわち後継者が親族内や社内にいない場合でも、品川区の今の支援制度では、社外への引継ぎも相談の対象となるのでしょうか。ご見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"この３つの分類の中でもやはり一番難しい分類と言われているところでございまして、支援対象に位置づけているところです。あるいはこういうことによって経済発展にもつながるのではないかというところで、ご支援できればと考えているところです。","id":"exchange-122"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"最後になりますけれども、実は東京商工会議所の方からも要望がある話の中で、団体要望のヒアリングをお聞きして私が感じたことであります。支援機関同士のつながりの強化、また情報交換の拡充を進めてほしいと考えますが、ご見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいま産業支援の組織にいろいろ団体がある中で、こういう連携が重要ではないかというご指摘がございました。区内事業者の皆さんの力になると考えておりますので、こういう団体間の連携というところ、区でも必要な取組をやっていきたいと考えています。","id":"exchange-123"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ商業・ものづくり課が中心となりまして、そういった企業支援機関をつなぐかけ橋になっていただくことを要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは３０１ページ、不妊治療助成事業を伺います。こうした助成について、品川区でもご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"若生健康課長","answer":"周知啓発については今後、区としてもいろいろ検討していかなければならないところかなと認識しています。これは男性の治療も含めまして、全体的に区の方で検討して、いろいろ調査をしながら考えてまいりたいと考えています。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問・要望","question":"この相談体制をご検討いただきたいのと、電話番号が令和５年で変わっていたりするという、ぜひこちらはご修正ほしいと求めました。相談体制をぜひ整備していただきたいという点が１個と、この２点、。","respondent":"若生健康課長","answer":"一定程度そういった知識も持っている職員が対応して、相談体制については、そういったところについても情報収集してまいりたいと思います。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"では、どういうふうにこの知識を高めていくのかというところで、これはやり方に気をつけないと、やはりライフプランとの関係で難しい。こういうふうなやり方もあると思いますので、最後にご意見をほしいと求めました。","respondent":"若生健康課長","answer":"他自治体の事例も踏まえて、検討してまいります。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"私は３２９ページ、共通商品券普及促進事業と、あと３２７ページ、運送事業者等燃料費高騰対策支援金についてお聞きしたいと思います。区内産業の現状について、区として今どのように捉えられているか、ご見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"１つ、一番大きいのは、やはり今物価高騰をめぐる対応ですとか、あるいは新型コロナの後の景気回復の状況です。あるいは、新しい産業を育てるという意味では創業支援政策なども含めまして、区内産業の活性化ということに取り組んでいるところです。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"お店、工場、製造業、建設業、そういう全体を見てどう思われますか。もう一度説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"こちらは、あるいは新型コロナの感染拡大のスタート時期というのを考えますと、その中では改善が少しずつ見られているところだとは思っております。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"それが現状ではないですか。もう一度ご見解を説明するよう求めました。","respondent":"小林商業・ものづくり課長","answer":"我々としては景況感を示す基本データで考えてはおりますけれども、それ以外に、小規模の事業者はその中で特にどうなのかというようなお話もあります。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"さて、プレミアム付区内共通商品券を品川区で発行していますが、これは産業振興政策なのですか。簡単に説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"幅広い意味では産業振興といいますか、区内経済の下支えのためにやっているものです。ただ、その中で、実際、やはり商店街の振興ということでやっている側面もあります。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"そして、発行数はいつも完売しているのでしょうか。そういうデータというのはあるのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"春のほうが当初４万冊ということでこれを発行いたしました。通常よりはより多くの買物を商店街の中でしていたと、それが３割程度というデータですけれども、そういうものは商連で把握しています。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"これは、最高１人８冊なのですか。区の予算でごく僅かな区民の皆さんに恩恵を与える仕組みをつくっているというのは、私はおかしいと思うのですが、どうか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"すみません、答弁の最初に１点訂正します。１０％あるいは２０％というプレミアム率の中で、やはり地域の区民、こういうものでやはり経済効果が一つあるのではないかと考えています。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"今の時期はもう変えるべきではないのですか。経営資源として、品川区において、このほかに何か事業支援はしているのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"それは設備投資を行う対象ということで、全業種、個人事業主か法人か問わずです。上限８０万円ということで区で支援しておりまして、あるいは製造業と、そういった幅広い業種で使っていただいているものです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"燃料費が上がっているから、物価が上がっているから、上げてやっているのですか。そういう補助というのが、支援が大事ではないのか尋ねました。","respondent":"塚本委員長、小林商業・ものづくり課長","answer":"やや款を超えているところもあるのですが、商業・ものづくり課としての範囲でお答えいただければ。 どの範囲でお答えできるかですけれども、やはり今、物価高騰というものがあります。ですので、品川区の産業支援の助成金ですとか、そういうものの中も、こういう動向を踏まえて考えていきたいと考えております。","id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"一般質問で、区の取組を着実に進めるために年度ごとの目標を立て、毎年検証を求めました。それぞれについて今年はどれだけ進めるのか、どこまで進んだのかということを検証するべきだと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"ＣＯ２を取り巻く状況ですが、皆さん、本当に取り組んでいらっしゃるところだと思います。２０３０年のカーボンハーフがありまして、２０３０年のゴールに向かいまして、適切に進めてまいりたいと考えているところです。","id":"exchange-136"},{"speaker":"のだて委員","kind":"質問","question":"しっかりと計画持って進めていくということが、２０３０年のカーボンハーフを実現するということになっていくと思うのです。そうした取組で本当にカーボンハーフを実現することができるのかと思いますので、チェックの仕方をまた伺いたいと思います。","respondent":"河内環境課長","answer":"人口数が、１割程度増加しているあおりを受けてというところで、進捗がなかなか進んでいないという点もあります。こういったところの各分野の目標値に向かいまして、そういったところを含めまして、目標に向かいましての進捗管理をしっかり行いたいという考えです。","id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"年間としては６８ｋｔですか、削減をしていくということですけれども、着実にカーボンハーフに向けて進めていくということになると思います。それぞれを具体的にどう進めていくのかということを、しっかり区民にも分かるように示していただきたいと思うのですけれども、いかがでしょう。","respondent":"河内環境課長","answer":"多角的なところで皆さんに啓発を行い、２０年に一度、そういったもののチャンスがめぐってまいります。そういった細かい積み重ねをすることによりまして、環境目標の達成に向けまして進んでいきたいと考えているところです。","id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"一般質問では、太陽光発電と蓄電池設置助成額の拡充を求めました。この需要等を踏まえ検討というのはどういうことなのか、どういう意味なのか、伺います。","respondent":"河内環境課長","answer":"年間におきましては、今まで区民の中で年間４０件前後の補助ですが、令和５年度になりまして、蓄電池の数も相当伸びてきてまいります。そういった需要を捉まえまして、伸ばせるところは非常に伸ばしていき、削減に向けて進めてまいりたいと考えているところです。","id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区として、今、増えてきて４１件ということですけれども、なかなか進まない、その原因は何だと考えているでしょうか。１つは周知が弱いのではないかということも思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"検討を進めてまいりたいと思いますが、現在のところ、各区の平均的な中でインセンティブが働くものと考えているところです。東京都の補助もございまして、そういったところに重ねてどこまで補助をするかというバランス感覚も必要かと考えています。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり助成額が多くなれば、その分、つけようという人も多くなると思うのです。設置をさらに促進していくためにも助成額の拡充を求めたいと思いますが、いかがか尋ねました。","respondent":"河内環境課長","answer":"１人当たりの補助額をたくさんあげるということは、全体で考えますと、全体の人数が減ってくるというような状況も考えられるかと思います。そういったところから、助成額につきましては、適正なレベルでまずは進めてまいりたいと考えているところです。","id":"exchange-141"},{"speaker":"のだて委員","kind":"質問・要望","question":"このことにも助成をすべきだと求めましたけれども、条件は２０万円ということですから、いかがでしょうか。ぜひ独自の助成をしてほしいと求めましたが、いかがか尋ねました。","respondent":"河内環境課長","answer":"アンケートなどを見ますとなかなか難しいかなと思っているところであるのですが、需要を見ながらそのようなところも考えていきたいと思っています。設置の費用につきましては、適正な情報を発信しながら、区民の方にご判断いただきながら進めていくことが大切かと考えています。","id":"exchange-142"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のは創エネの問題で、今度、省エネ対策としても、断熱化を進めてほしいということで求めてきました。義務化がされれば助成を考えるということなのか、それまでは実施しないということなのか、伺いたいと思います。","respondent":"河内環境課長","answer":"断熱の考え方ですが、外皮性能だけ上げればＣＯ２が減るものではないという捉え方もしております。さらにＣＯ２のドミノ倒しではないのですが、そういったところに踏み込む考えでいるというところで、そういった表現をしたものです。","id":"exchange-143"},{"speaker":"のだて委員","kind":"質問・要望","question":"医療機関でも気軽に受けられるように、公費負担を続けるように国に求めてほしいと求めましたが、いかがでしょうか。ですので、医療機関へのエールも込めて、国に公費負担を続けるよう求めてほしいと求めましたが、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"検査も当然、これもお話しいただいたところではありますけれども、抗原検査キットを無料で配布するということは現在考えておりません。そういうところかと思うのですけれども、これも国の決めですので、これを元に戻してくださいみたいな要望を区からする考えはございません。","id":"exchange-144"},{"speaker":"のだて委員","kind":"質問・要望","question":"５類に引き下げられて何もやらないというご答弁でしたけれども、自分がかかっているかどうかというのが分かるわけで、いかがでしょうか。やはりそれは効果があるということだと思いますので、この検査を拡充してほしいと求めましたが、いかがでしょう。","respondent":"坂野保健予防課長","answer":"はっきり言って、いろいろな考えがあります。なかなか検査を無料にしてアクセスを改善したから、それで感染が広がらないというのは、今のところは否定的な考えです。","id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、施設をどうにかしなければいけませんが、拡充を求めたいと思います。そういうことをこの産後ケアについても検討していただけないかと思うのですが、見解を伺います。","respondent":"石橋品川保健センター所長","answer":"心身のケアを実施しておりまして、自宅訪問型というものも行っておりますので、外出しづらい産褥期の方も活用していただけるものをやっております。関連団体、関係所管と連携しながら、産褥期を含めた女性の出産後の総合的な支援について検討してまいりたいと考えております。","id":"exchange-146"},{"speaker":"吉田委員","kind":"提案","question":"今年３月の予算特別委員会で組成調査のことを伺ったところ、組成調査については、一般廃棄物処理基本計画を作成しております。先ほど ＣＯ２削減のことが出ましたけれども、やはりごみは増えれば結局燃やすわけですから、それはＣＯ２を発生させるということにつながりますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"内容については、委員から詳しくご説明いただきましたので、今後の組成調査の件についてお話をしたいと思います。そういうところもいろいろ踏まえながら、組成調査の間隔についてはいろいろと研究してやっていきたいと考えています。","id":"exchange-147"},{"speaker":"吉田委員","kind":"提案","question":"大学と連携してはどうですか」というご提案をいただきました。大学などと連携して組成調査を行い、共同研究のような形でごみ減量を図ることを検討してはどうかというご提案なのですが、いかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"現在、組成調査を１年前に行って、それを終えて計画の方向性も出して、これからまた清掃事業を進めていこうと思っているところです。大学との連携等も今お話いただきましたので、そういう広い視野を持ちながら、研究していきたいと考えています。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうも２３区は、それから、海のほうにというのがあります。見解をお伺いします。","respondent":"品川品川区清掃事務所長","answer":"そういうことで資源化率をどんどん上げていって、燃やすごみの量を減らしていく。こういったことも一つ、大事な目線ではないかなと考えています。","id":"exchange-149"},{"speaker":"あくつ委員","kind":"質問","question":"３１１ページ、３１３ページ、マイボトルの利用促進とウォータースタンドの設置について伺ってまいります。協定では何基まで無償提供が可能なのか、また、３基は設置から８か月程度が現在経過していますけれども、利用状況や利用者の感想を説明するよう求めました。","respondent":"河内環境課長","answer":"設置箇所ですが、受付の横に１台設置させていただきまして、本庁舎５階の給湯室に入れしています。契約につきましては５基ですので、今、２基の設置に向けて調整をしています。","id":"exchange-150"},{"speaker":"あくつ委員","kind":"質問・要望","question":"体育館などでスポーツ飲料の粉を一緒に販売してもいいのではないですかという、自由な、ユニークなご意見も活発に出ていました。ここから質問ですが、区民ニーズのある場所への拡大をぜひ行っていただきたいと考えていますけれども、今後の展開についても示すよう求めました。","respondent":"河内環境課長","answer":"水を通して環境を考える、１つですが、そういった多様な意見をいただいたところです。町場におきましては、今後も連携した取組を視野に、進めてまいりたいと考えているところです。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問","question":"その点についてのご見解も伺いたいと思います。それを森澤区長と一緒に出たらいいのではないかとか、あとは桝太一さん、海洋研究者ですか、今、フリーアナウンサーの。","respondent":"河内環境課長","answer":"有名人の方との連携なども含めまして、いろいろ進めていき、こういったものの連携が広がるように工夫してまいりたいと考えているところです。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間が若干ありますので、各種がん検診、アピアランスケア支援の現状と制度拡充について伺います。購入されたものがウィッグとか胸部補正具なのか、その内訳も示すよう求めました。","respondent":"若生健康課長","answer":"アピアランスケア事業は、今年度７月から開始しております。がんの種類が分からないのは７件という状況です。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ざっと今伺うと、４７件あって、１０種類ぐらいのがんの姿が見えてまいりました。１６０件の予算を積んでいるので、今年度はまだ若干時間があるので余裕はあると思うのですが、ぜひこの拡大についてお伺いしたい。","respondent":"若生健康課長","answer":"アピアランスケア事業としてがん対策講演会というのを今年度２回、予算を取ってやっておりまして、１回目は６月に実施したところです。様々、がん相談支援センターとの連携というのも踏まえて、いろいろ啓発に努力していきたいと考えております。","id":"exchange-154"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"３１５ページ、粗大ごみからのリユース事業、時間があれば同ページの資源化センター管理運営費についてお伺いします。粗大ごみからのリユース事業についてお伺いします。","respondent":"品川品川区清掃事務所長","answer":"委員がご質問のリサイクル率の件ですが、木製の粗大ごみがやはり大半を占めまして、全体の２５％ぐらいになります。さすがに１点１点のものがありますので、あまり数字的な効果はないと、こういった状況です。","id":"exchange-155"},{"speaker":"せりざわ委員","kind":"提案","question":"これは提案なのですが、我々の会派でもいろいろ要望させていただいたドッグランというのを、品川区で作っていこうかという話もあると思うのです。そういったドッグランとか、関係するほかの所管との連携を取っていただきたいというのを、まず１点質問しますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"１２月から粗大ごみの中から衣装ケースもピックアップしまして、こちらは歳入として、買い取っていただけるという形で進めていく予定です。","id":"exchange-156"},{"speaker":"せりざわ委員","kind":"提案","question":"いろいろ議会で確認していたのですが、２年前の２０２１年の１０月６日、会派控え室で自民党の研究所長と呼ばれるようになった日でありました。具体的な提案をしていきなさいというようなお話をいただいて、２年前の当時、残念ながら当時は研究だったのですとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"ですので、多分、啓発というような形で区としても進めていく方向になるのかなとは思っております。申し訳ございません、調査し研究していきたい、このように思っております。","id":"exchange-157"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"新庁舎ができたときに区民の皆さんと弾けたらいいのではないですかという話もさせていただきましたが、いろいろなやり方が考えられると思うのです。子どもたちがこのアクリル板をどうやって使えるかなと考えることも、ぜひもう一度そこら辺も含めて、ご見解をお聞かせほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"事業所が、例えば区でアクリル板を使っているもの、残っているもので何かできないかというようなところはあるかと思います。ほかの市区町村などの対応も研究し、あとアクリル板で一体どういうものができるかというところも非常に大切だと思います。","id":"exchange-158"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今年もしくは来年が最後の研究ではなく検討の段階だと思いますので、そこの力をぜひ込めていただいて、リサイクルを推進していただければ。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":124746,"voices":369}},{"id":"r05-20231010-4","meetingId":"r05-c-settlement","date":"2023年10月10日","dateIso":"2023-10-10","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を162件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"３６７ページ、防災普及教育費、普及啓発経費、３５５ページ、しながわ水族館運営費についてお伺いいたします。防災普及教育費、普及啓発経費として、３５２万３,４６２円が計上されていますが、普及啓発としてどのような取組を行っていらっしゃるのか尋ねました。","respondent":"平原防災課長","answer":"普及啓発経費につきまして、お答えいたします。普及啓発経費では、区内小・中学生から応募いただく防災ポスターコンクールのほか、マンション防災アドバイザーの取組などを行っているものです。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"一方で、品川区には多くの高層マンションが建設されておりますが、町会・自治会への参加率は低いとのお声もお聞きしております。区としても、先ほど課長がおっしゃっていたように、現在行われているマンション防災アドバイザーの成果や課題を、示すよう求めました。","respondent":"平原防災課長","answer":"その中で、防災に関する講演や防災訓練の支援などを行っておりまして、令和４年度では講演を６件、訓練支援を１１件行っているところです。","id":"exchange-002","title":"町会・自治会支援"},{"speaker":"澤田委員","kind":"質問","question":"防災訓練が週末の土日に行われることも多いことを考えますと、１年間で回れるマンションの数は限られてしまうのではないでしょうか。もう一人、アドバイザーを増やすなど、区として考えていらっしゃる対策・対応などがありましたら説明を求めました。","respondent":"平原防災課長","answer":"このため、マンション防災を強化してまいりたいと考えています。３階以上かつ１５戸以上のマンションまで拡大することを考えてございまして、そのための体制をしっかり整備してまいりたいと考えています。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"続きまして、３５５ページ、しながわ水族館運営費についてお伺いいたします。現在の進捗状況を説明するよう求めました。","respondent":"高梨公園課長","answer":"今年度に入りまして、７月より事業者公募の受付を開始いたしまして、これまで事業者からの提案の説明やヒアリングなどを実施してきたところです。１１月に向けて、事業者を選定し、公表していく予定としています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"提案","question":"お伺いしたいのは、リニューアルした際の夜間営業を提案されてきたと思いますが、改めて私からも夜間営業を要望いたします。実現に際して、課題や配慮すべき内容について、現在、区としてはどのようにお考えか尋ねました。","respondent":"高梨公園課長","answer":"夕方から夜間の時間帯における需要について、公園も含めて、魅力的な空間となるように検討を進めてまいりたいと考えています。大井競馬場など周辺の施設とのコラボレーション・連携なども、これから決定する事業者と共に検討を進めてまいりたいと考えています。","id":"exchange-005"},{"speaker":"澤田委員","kind":"意見","question":"それもまた、リニューアルを待っている区民の皆さんが、楽しみにされるのではないかと考えています。例えば３００日というような形でリニューアルの前後を楽しむことをアピールすることや、多くの方々に、区のご見解を説明するよう求めました。","respondent":"高梨公園課長","answer":"しっかりと区民の皆様に情報が届けられるように、広報等、周知には力を入れてまいる考えです。ホームページやＳＮＳをはじめ、参加していただけるよう、積極的に取り組んでまいりたいと考えています。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは２点、お伺いいたします。３６５ページの感震ブレーカー普及経費、また３３７ページの無電柱化推進事業について、それぞれお伺いしてまいります。","respondent":"羽鳥防災体制整備担当課長","answer":"令和４年度までの実績が確定しているものですが、令和４年度に関しましては４９件の補助をさせていただいて、累計で５５４件になります。今年度は、今、事業を進めているところですけれども、１０件程度、申請が来ていると聞いております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"確認","question":"令和４年に４９件、あと今年度までで５５４件ということで、着実に推進が進んでいるということを確認させていただきました。東京都の事業ですが、品川区として、この事業との連携や、この事業に合わせた取組などがあれば、ぜひ教えてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"は感震ブレーカーの実績についてですけれども、もう一度ご説明しますと、令和４年度までで、累計で５５４件の申請を頂いております。東京都と連携して、感震ブレーカーのお知らせをしている区のホームページに、東京都のご案内も載せているという状況です。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"やはり、コンセント型の簡易タイプより、住宅全体を網羅して通電をストップさせる分電盤型タイプの感震ブレーカーを普及させるべきだと感じています。より一層の啓発運動をしていくチャンス、契機になるのではと思いますが、区のお考えをお聞きできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"特定機器遮断型ではなくて、一括してブレーカーを落とすタイプということで、上位機種のほうを助成させていただいているです。区も今後、東京都と連携して、ぜひ感震ブレーカーのＰＲを強化してまいりたいと考えております。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"第一次緊急輸送道路の競馬場通り、広域避難場所周辺の文庫の森から補助第２６号線の区間を優先的に整備・推進されていると認識しています。この２路線での今後のスケジュール、完成の時期、課題などをお聞きできればと思います。","respondent":"森道路課長","answer":"今現在、２路線で無電柱化の計画実施を進めておるところですけれども、競馬場通りにつきましては令和１１年度の完成を目指して進めております。工事が長い期間続きますので、安全第一で、通行される方の利便性をなるべく損なわないように進めていければと考えております。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"提案","question":"競馬場通りが令和１１年、文庫の森、補助第２６号線が令和８年と確認させていただきました。たけうち忍元区議会議員が昨年の一般質問で提案された内容ではありますが、現在、また区の今後のお考えを改めてお聞きできればと思いますとの意見を述べました。","respondent":"森道路課長","answer":"区といたしましては、例えば競馬場通りですと、東京電力、ＮＴＴなど４社が今、参画されて、電線を地下に埋めようという形で進めているところです。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"３３１ページ、３５５ページの、時間次第で３４９ページの広町地区整備検討について伺います。３３１ページの駅周辺等放置自転車対策事業について伺います。","respondent":"工藤交通安全担当課長","answer":"１つは、Ｓｕｉｃａなどの交通系ＩＣカードを使ったもの、もう一つは、ＰａｙＰａｙなどのＱＲコードを使ったものとなります。利用率ですが、交通系ＩＣカードは７０％、ＱＲコードが５％といった状況です。","id":"exchange-012"},{"speaker":"山本委員","kind":"確認","question":"例えば五反田駅には、３か所に当日利用の駐輪場がありますが、向かうときに空き情報を確認しておけば、安心して効率的に利用できます。区のお考えをお伺いいたします。","respondent":"工藤交通安全担当課長","answer":"お気に入り等に登録していただければスムーズにお使いいただけると思うのですが、初めての方には親切さに欠けるかといったところです。委員から頂いたご提案を含め、情報掲載の方法については、どんな形がいいのか検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"先日ご提案いたしました、より多くの方々に認知いただき、有効活用していただけるのではないかと考えます。せっかくのデータですので、併せて有効活用の検討を要望いたしますとの意見を述べました。","respondent":"工藤交通安全担当課長","answer":"アプリの展開につきましては、こちらは全庁的に関係するものとなってまいりますので、関係部署と連携しながら研究してまいりたいと考えています。その他、委員からご提案いただきました事項につきましても参考とさせていただきながら、今後、研究してまいりたいと思います。","id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"次に、３５５ページのＰａｒｋ－ＰＦＩ導入に向けた調査・検討についてお伺いいたします。公園の雰囲気に合うかまどベンチを設置するなどの工夫もあり、民間事業者の提案をうまく活かした、魅力的かつ機能的な公園でしたとの意見を述べました。","respondent":"高梨公園課長","answer":"本年の６月ですが、現在はこれから行う予定の公募に向けまして、公募指針の作成に向けた準備を行っているところです。公募指針の作成を行った後に、事業者の公募を開始する計画です。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"先週末も秋の運河花火まつりがあり、私も伺いましたが、多くの区内外の方が訪れており、とてもにぎわっておりました。このようなイベント運営に係る関係者や近隣の方との協議はされていらっしゃいますか尋ねました。","respondent":"高梨公園課長","answer":"これら魅力あるイベントとしっかり連携できるよう、地域と融合できる事業者を選定することが重要であると考えています。現在、地域の各団体とは、本事業の指針策定に向けて協議を開始しています。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"品川区が条件として求める重要なものは何でしょうか。それから具体案になりますが、防災機能の強化、非常用トイレの拡充などを、公園施設整備の一つとして求めることはいかがか尋ねました。","respondent":"高梨公園課長","answer":"先ほど申しましたとおり、地域の各団体と連携することというところは最も重要なポイントであると所管課としては考えているところです。本事業を行う中で、防災機能の充実についての提案というところは、公募を行う上で優位となる評価項目になり得るという認識です。","id":"exchange-017"},{"speaker":"山本委員","kind":"提案","question":"そして民間事業者のよい提案や工夫を引き出して、利用者にとってプラスとなり、特徴のある公園づくりを望みます。初めてのＰａｒｋ－ＰＦＩ制度の活用ということで、この経験を蓄積し、今後の公園整備などの中で活かしていただくことを併せて要望いたしますとの意見を述べました。","respondent":"高梨公園課長","answer":"しながわパパママ応援サイトの中でも、「こうえんしょうかい」としてエリア別に主立った公園の概要をご案内しています。様々な場面でご利用いただいていると認識していますが、まだまだ区民の皆様のニーズに合った形に改良の余地があると考えているところです。","id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"さらに、やはり区民の皆様に分かりやすくご案内していただきたいというところがございまして、私から何点かご提案を申し上げます。区として、お考えをお伺いいたしますとの意見を述べました。","respondent":"高梨公園課長","answer":"皆様に使いやすいホームページの形というものは、日々進歩、よりよいものにどんどん改善してきているものだと考えています。区としても現状に甘んじることなく、よりよい、より見やすいホームページの作成というところで努めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"中長期的にはアプリのご検討などもしていただきたいというところで、利用者目線で分かりやすく示していくということをご検討いただきたいです。広町地区整備検討については、時間も限られておりますので、またの機会でお話しさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、この事態を受けて、品川区としてはどんな動きを取ったのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その後、区には９月２９日に第２報として、各航空会社への、それからトルコ当局への指導を行ったというお話を頂いたところです。区としては同時に、口頭ではありますが、早期の原因究明と再発防止について、国に強く求めたです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"次に、武蔵小山地区開発について大きく２点伺います。改めて伺いたいというのが１つと、再開発組合がまだ解散していないようなのですけれども、それはどんな理由なのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"各再開発の権利者の戻りですが、また個人情報等もございまして、再開発組合から情報に関しては非公表という形で聞いてあります。やはり維持管理、実際に物事が動いていく中で修繕したいところが出てきていますので、そういったところを今行っているです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"伺うのですけれども、それとも、そもそもつかんでいないということなのでしょうか。ほかの第一種市街地再開発事業についても権利関係はどうなのか、どれぐらいの人が戻ってきているのか等々のつかみについて伺いたいと思います。","respondent":"中道都市開発課長","answer":"ですので、そういったことは区はきちんと把握はしておりますが、組合のほうで、そういった情報は非公表です。ほかの地区におかれましても、区でそういった管理というのは徹底しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"そのまちづくりが適正だったかどうかを検討するのに、そこのところを出さずして、どうやって検討するのですか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"老朽化した建物、またインフラの整備といったことで、都市の魅力を向上させる、またはその地域の経済を活性化させるといったことも目的です。区民の方が地域で話合いを行われて、そうした中で進んでいる再開発事業ですので、区としては今後も支援していきたいと考えています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"従前に住んでいた方がどれだけマンションに戻ってきたか、住み続けられたかというのは、もう関係ないということなのですか。だから品川区議会に出さないということなのか尋ねました。","respondent":"中道都市開発課長","answer":"ですので、区議会には、情報の共有化というのは、きちんと区は行っていくつもりです。人々の快適性や、訪れる方を増やすといったことも効果の一つですので、総合的なまちづくりというところで進めているです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そういう方がどれぐらいいるかというのも、総合的に検討という名の下に明かさないというのは、ひどいのではないですか。あまりに偏っていると思うのですけれども、もう一度お願いします。","respondent":"中道都市開発課長","answer":"一方で、区としましては、もちろん３分の２をクリアしたから、まちづくりを進めるというものではございません。皆さんが住みやすいまち、または安心して住めるといったところで進めているものですので、地域の中で同意した中で進めているです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、組合員からのこうした質問に答えないということはあり得ないと思うのですが、今後回答は来るということでよろしいのでしょうか。そして、区としても、早く回答を出してくださいと準備組合に促していただきたいのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"今、準備組合に情報開示がですが、まずは区としましては、そこの中身をしっかりと把握したいと思います。それに対して、出せる情報、出せない情報というのは、基本的にはやはり準備組合で判断していただくというものになります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私はさきの一般質問で、現況の地区内の借地権者数について伺いました。伺いますけれども、権利関係の確認を要する方が複数名いるとはどういうことなのか尋ねました。","respondent":"中道都市開発課長","answer":"再開発事業ですが、事業者は、やはり地域の方々、準備組合または組合です。借地権者におかれましては民民の契約ということもありますので、区としては、区が自ら、そこの数を把握するということはございません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、高規格オフィス、高規格住宅とは何なのでしょうか。右上に「バス車庫等」とありまして、都営アパートという記述はありませんが、この「等」に含まれているのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今後のまちづくり、都営住宅の扱いにつきまして、現在、東京都と協議会が主体になって進めているものと認識しています。単純に言いますと、子育てに特化したとか、防災性に特化したといった意味合いと認識しております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"確認","question":"ですから、私はそこをはっきり伺いたいのですが、では残すということでよろしいですか。伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"施設管理者である東京都と協議している段階で、現在、何も決まっていない状況です。区としましては、全体を考えて良好な住環境を整備するよう、協議会には求めているものです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"３６３ページ、３４５ページ、関連して羽田新ルートについてお伺いいたします。決定の方向なのでしょうかということと、資料で提案箇所として挙げられているところが、この提案箇所のままでよろしいのか尋ねました。","respondent":"高梨公園課長","answer":"広く事業者の方々から、現在、飲食関係に収益施設を限定してといったところではございません。区が考える候補地として、東品川海上公園の中で事業を実施する場所というところで、場所を決定しているところではございません。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"安定的に収益を相当程度稼げる施設、それをしっかり運営できる事業者にならないといけないと考えておりますけれども、その点は大丈夫なのでしょうか。そうした事業者・施設に対して、いかがお考えなのか尋ねました。","respondent":"高梨公園課長","answer":"長期間、どのような収支計画でその特定公園施設の管理・運営を行っていくのかといったところも、公募の中で求めていきたいと考えています。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"提案箇所もまだ未定ということですけれども、結局、そこに今まであった遊具や木はどうなるのだというお声も一方であります。いろいろなお声がありますけれども、その辺りはいかがお考えか尋ねました。","respondent":"高梨公園課長","answer":"東品川海上公園と一体となる、公園の魅力もさらにその施設によって高めることができるような施設を、事業者に求めてまいりたいと考えています。あってはならないと考えていますので、かつ公園の機能がさらに充実するといった事業を、事業者には求めてまいりたいと考えています。","id":"exchange-033"},{"speaker":"筒井委員","kind":"提案","question":"この提案箇所の辺りというのは照明が非常に暗くて、特に女性の方から、夜歩くのが怖いというようなお声が届いております。これは事業者が負担するのかどうか、その辺りの環境整備ということもぜひ行っていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"高梨公園課長","answer":"公園全体としての魅力を高めるために事業者にどこまでやっていただくかといったところをしっかりと求めてまいりたいと考えています。通常の公園の管理の中で迅速に、業者が決まる前に対応させていただきたいと考えていますので、よろしくお願いします。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、今のところ認定件数が３件しかなくて、非常に少ないと感じております。各マンションを管理している管理会社に対して周知すべきだと考えているのですけれども、その点、いかがお考えか尋ねました。","respondent":"竹田住宅課長","answer":"委員ご指摘のとおり、今現在、３件のマンションの認定をしたところです。こちらの認定の申請の手続は若干複雑なところがありますので、管理組合に丁寧にご説明し、認定件数の増加に努めてまいりたいと考えております。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"現行ルートの固定化を回避していただき、品川区の住宅街を飛ばないようなルート変更を、ぜひ積極的に求めていっていただきたいと考えております。まず２０２３年度、「評価（３ｒｄ）」、区は状況把握はされているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた第５回が昨年の８月というところでございまして、その８月の時点で、次回の開催予定が、次年度、来年の夏から秋にかけてです。検討状況も含めて、国にはその検討状況についてお聞きしているのですが、その辺をお示しいただいていないというような状況です。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。パイロット側との調整・確認が必要で、その辺りはぜひ国に対しても求めていっていただきたいと思うのですけれども、その点はいかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"現在の検討状況、それから、それが品川区にどういう形で落とし込まれていくのかというところも含めて、具体的に早急に国に示していただけるように、これまでも申し入れてきていますが、今後も強くしっかりと申入れをしていきたいです。","id":"exchange-037","title":"町会・自治会支援"},{"speaker":"せらく委員","kind":"質問・要望","question":"日陰づくりという点をお聞きしたいのですが、遊具の設置には方角が考慮されていると、会議録で確認しました。遊具以外での日陰づくり、日よけシェードなど、公園設計での暑さ対策の考え方を伺います。","respondent":"高梨公園課長","answer":"設置に至る考え方ですが、非常に多くの子どもに遊んでいただく公園といったところを基準に、ミストについては設置しています。設計の段階で設置し、今ある大きな木をしっかりと活かして、公園の中での日陰を確保するといったところで進めさせていただいているところです。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"このようなご意見は、これまで区に届いていますでしょうか。解決策として周知していることがありましたら示すよう求めました。","respondent":"高梨公園課長","answer":"様々ご要望を聞きながら、今後、折を見て拡大していきたいと考えています。人工芝を設置させていただいたところですので、利用者の声を聞きながら、今後も啓発というところで取り組んでまいりたいと考えます。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"最後の質問になるのですけれども、区民公園の交通アクセスについて伺っていきたいと思います。京浜急行の立会川駅と大森海岸駅から各徒歩５分、一時閉鎖したときの無料送迎バスの運行については、どのように検討されていますか尋ねました。","respondent":"高梨公園課長","answer":"これから水族館のリニューアルに関する運営準備事業者と設計事業者の選定後、そこは事業者としっかりと話し合ってまいりたいと考えています。特に水族館に関しましては、基本的には今後、リニューアル後も継続することを前提に考えてまいりたいと思ってあります。","id":"exchange-040"},{"speaker":"せらく委員","kind":"意見","question":"まだリニューアルの基本計画もこれからだと思いますが、区民の皆様のニーズに応えていただきまして、リニューアル後、来場者の増加も見込まれると思いますので、場合によっては増便など、状況に合わせてご対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、防災関係組織経費、応急活動対策費についてお伺いしてまいります。２０１７年７月と２０２０年９月の一般質問で、要配慮者や子育て経験者など、防災会議における女性委員についてお伺いいたしました。","respondent":"平原防災課長","answer":"こちらにつきましても、早期に１５％、それから令和７年度までにさらに３０％を目指すといったところについても変更はございません。区単独では直ちに達成というところは難しいと認識しておりますが、一方で、目標達成に向けて取り組んでまいりたいと考えています。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"万が一、民間事業者が被災してしまうなど何かあった場合に、そのようなケースにおける区のリスク回避の考え方についても確認させてください。第３の手段、例えばＡ倉庫が被災したらどうするのかなどについても、集中と分散のバランスを意識した再編成をお願いしたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"今後、特性に応じて備蓄する物資や、効果的かつ機能的に搬入・搬出するための資機材を整備するということで考えているところです。そういった皆様の力をお借りしながら、災害時の輸送体制を整備していくという状況です。","id":"exchange-043"},{"speaker":"横山委員","kind":"確認","question":"様々準備していただいているということが確認できましたので、よかったと安心しております。図上訓練というのと実動訓練、３種類あるようなのですけれども、それぞれ簡単にどういった訓練なのかを説明するよう求めました。","respondent":"伊藤災害対策担当課長","answer":"国重点訓練ですが、全国を６か所に分けておりまして、基本的には国が主導して行う国民保護共同訓練となっています。図面や地図などを使用しまして、災害対策本部等におきましてメンバーが集まりまして、どのように災害が発生した場合に活動するか検討する会議です。","id":"exchange-044"},{"speaker":"横山委員","kind":"確認","question":"お伺いしてまいりますが、こちらは国の部分だと思うのですが、もし何か品川区との関係性がありましたら確認させてください。今年度は、弾道ミサイルを想定した住民避難訓練が３６の県と市で実施される予定となっていますが、区のご見解をお伺いいたします。","respondent":"伊藤災害対策担当課長","answer":"国民保護地域ブロック検討会につきましてですが、全国を６ブロックに分けて、それぞれのブロック内で検討等を行う会議です。警察と、どのように対応していくべきなのかということを検討してございまして、そういった課題を俎上にのせまして検討してまいりたいと思います。","id":"exchange-045"},{"speaker":"横山委員","kind":"意見","question":"万一の有事に備えて国民保護計画が現実に運用できますように、国や都の最新情報を注視しながら、随時見直しをお願いしたいと思います。長期的には防災協定等の締結に限らず、双方の強みを活かして協力体制の強化へとつなげてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書３４５ページ、都市防災まちづくり事業費の中から用地取得費と、３６５ページの防災関係組織経費の全般について質問します。５００万円余は、木密解消のための土地取得だと思いますが、この５００万円余という数字がどの土地を取得した経費なのか、示すよう求めました。","respondent":"小川木密整備推進課長","answer":"令和４年度の用地取得の内容ですが、令和４年度は、用地の取得に係ります土地の測量委託、また物件調査、鑑定評価委託を計上させていただいているのと、あとは豊町五丁目ののんき通りにおける道路拡幅用地、約１.６平米の取得費といった内容になってあります。","id":"exchange-047"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"権限は東京都にあるから、消防団と品川区の関係というのは、どうしても弱くなってしまうのです。はその辺の区の考え方から、示すよう求めました。","respondent":"伊藤災害対策担当課長","answer":"現在実施している各地区での総合防災訓練におきましては、事前の説明会から、連携を取っていただいているような状況です。引き続き、訓練や地域の行事などを中心に、地域と消防団、区との連携強化に努めてまいりたいと考えております。","id":"exchange-048"},{"speaker":"まつざわ委員","kind":"質問","question":"消防団というのは区民の命を守るために活動しているのですから、どうしたらできるかというのを考えていくのが重要であると考えています。ご見解を説明するよう求めました。","respondent":"伊藤災害対策担当課長","answer":"消防団倉庫につきましては、委員ご指摘のとおり、区民の安全安心を守る上で非常に重要な施設であると認識しております。本件につきまして、防災課だけで考えられる問題ではないと考えますので、情報を共有化しまして、今後、検討させていただきたいと存じます。","id":"exchange-049"},{"speaker":"まつざわ委員","kind":"提案","question":"団の倉庫というのは早急な対応を求めていますので、一生懸命やっていただいておりますが、それ以上に頑張ってやっていただきたいというのが本心です。新庁舎といった中に、訓練場所を確保していただくなどの対応を求めますが、ご見解を説明するよう求めました。","respondent":"伊藤災害対策担当課長","answer":"こちらについては、区でも同様に対応させていただきたいと存じます。どのような体制であれば実施できるか、またできないのかなど、関係課と共有させていただければと存じます。","id":"exchange-050"},{"speaker":"まつざわ委員","kind":"意見","question":"要は、消防団が大規模災害においてはどう動いていくのかということです。ぜひご見解を説明するよう求めました。","respondent":"伊藤災害対策担当課長","answer":"こちらにつきましても、国や東京都の動向を注視して、情報収集に努めてまいります。防災区民組織、消防署との連携強化に、区としても引き続き努めてまいります。","id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問","question":"これは本当にすばらしいので、例えばこの防災学校の講習を修了したら、区で認めた資格を発行するのはどうでしょうか。有事の際、判断ができる人材を育てていくべきと考えますが、ご見解をお願いします。","respondent":"平原防災課長","answer":"防災区民組織コースにつきましては、修了証、カードサイズのものはお渡ししています。今後、周知に努めてまいるほか、様々なコースを充実させていただきたいと考えています。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"私からは、３３７ページ、橋梁維持管理費、３３９ページ、舟運活性化、３５３ページ、公園・児童遊園整備費から伺ってまいります。そしてこのデッキの改修計画というのが、どれくらいの規模となって、いつぐらいなのかということをお伺いいたします。","respondent":"森道路課長","answer":"東口のペデストリアンデッキですけれども、平成元年に架設されまして、３５年程度が経過しています。５０年や７０年といったスパンで、区としては考えているところで、しっかりと改修を進めていくです。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"このデッキから１階に降りるには、階段の利用と、ヤマダ電機の店舗内、また、きゅりあんのエレベーターがあります。このエレベーターの利用時間をそれぞれお伺いいたします。","respondent":"森道路課長","answer":"既存のエレベーターですけれども、きゅりあんのエレベーター、西友側に降りるところにつきましては、朝の８時３０分から２５時まで、もう一つの、きゅりあんの中にありますエレベーターにつきましては、８時３０分から２１時３０分までと確認しております。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"周辺には大きな病院もあることから、しっかりこのデッキに品川区として、大きな改修に向けてはもう少し時間がかかりそうな現状も確認いたしました。利用時間は何時から何時までですと、分かりやすい表示の看板を改めて設置してほしいと求めましたが、見解を伺います。","respondent":"森道路課長","answer":"委員ご提案のような時間のことであったり、１階に降りられますというようなことが分かりづらいというところは認識しております。区といたしましても、少し看板まで離れているところもありますので、そういった案内表示につきましては検討していきたいと考えております。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"その共存という視点から、犬の居場所、水飲み場やトイレの整備を公園の中にしっかりとつくっていただきたいというのが要望です。しっかり共存できる体制を品川区にお願いしたいと思うのですが、水飲み場や犬のトイレの設置についての見解をお伺いいたします。","respondent":"高梨公園課長","answer":"以前からご要望いただいているところですが、公園の再整備の際に、地域の皆様の声を聞きながら設置を進めてまいりたいと考えています。これから、犬が入れる公園で再整備を予定している公園が増えてまいりますので、前向きに検討してまいりたいと考えています。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"この要因は何か、伺います。今後、満足度５０％ということを品川区が掲げられておりますけれども、この目標達成に向けての取組をお伺いいたします。","respondent":"北原河川下水道課長","answer":"水質の悪化の件についてですが、目黒川は降雨の際には下水道の水が出てしまうということで、それが臭気の原因になっていると認識しています。令和２年度より下水道局が一部、そちらの動向も確認しながら、区としても要望していきたいと考えています。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"やはり水辺を求めて来る方というのは多く、品川区民の方にもいらっしゃって、屋形船の体験乗船も八潮地域で行いましたけれども、大変好評であります。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、３６５ページの防災費のところで防災相互協定について、３４３ページ、景観まちづくり推進事業についてお聞きします。協定を結んでいる自治体と定期的に、協定内容にある受入れ施設等の情報を取り合っているのか示すよう求めました。","respondent":"平原防災課長","answer":"現在のところ１０件の協定を締結しておりまして、東京都外の自治体で言いますと、全部で３１自治体との間で協定関係にあります。一部の災害時相互応援協定では、年１回訓練を行うなどして、連絡体制の確認あるいは災害時の実際の動きなどの確認を行っているところです。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"区外の状況ですと、やはり距離的にも随時知ることができませんので、定期的な情報共有、また共に進める防災訓練などの活動、非常に心強いと思います。今後、ほかの自治体から打診があった場合は、さらに協定先を増やすということは予定していらっしゃいますか尋ねました。","respondent":"平原防災課長","answer":"他自治体から、品川区とそのような形でというふうになりましたら、実際に話合いを進めながら、どういったことができるのか、相互にどのようなメリットがあるのかといったことを検証しながら、最終的には協定という形までいければと考えているところです。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"提案","question":"次に、景観まちづくり推進事業についてお聞きします。宿場町の雰囲気と調和したデザインや色彩の提案など、この景観アドバイザーというのはどういった業者の方で、委託内容を説明するよう求めました。","respondent":"鈴木都市計画課長","answer":"当然ながら専門的な建築士の方等もいらっしゃって、旧東海道の町並みに合った建物改修等を行っていただくためのアドバイスを定期で行っているです。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"ただいま、相談の件数の実績はどれぐらいか尋ねました。","respondent":"鈴木都市計画課長","answer":"アドバイザーの委託の件数ですが、令和４年度の実績が２２件ございまして、延べ８６人の方にご相談いただいているというような状況です。","id":"exchange-062"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区民の方々の暮らしのほかに、観光や歴史景観としてのまちづくり事業ということで、ぜひ住民の方とよく話し合って進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"目標設定の根拠、また今年度の結果として区民からの要望件数は９６６件となっておりますが、この結果は区としてどのように捉えているのでしょうか。区としては、団体からこのようなご意見を毎年頂いていると思いますが、この要望に対して、現在どのような対応を検討しているのか尋ねました。","respondent":"森道路課長、伊藤災害対策担当課長、工藤交通安全担当課長","answer":"目標としては行政評価の中で３０％としていますけれども、効果的に早めの段階で、まず見つけていければと考えています。すぐに対応が可能と考えておりまし… 今年５月に実施いたしました避難所開設訓練におきましては、視覚・聴覚障害者の方々に実際に訓練会場に足を運んでいただきました。… うち、委員からご説明のあったアプリの関係ですが、それに対応したものは、残念ながらございません。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"My City Report）」にするなどして、一目で分かりやすくするなどの工夫をしてはどうかと思いますが、いかがでしょうか。品川区でも、ぜひこういったアプリの利用、また夜間の信号の音の出る時間帯の拡大なども検討していただけるよう、こちらは要望とします。","respondent":"森道路課長","answer":"より効果的なものを考えていきたいと思いますし、「My City Reportがそうです」というようなことも、しっかりとＰＲしていきたいと考えております。","id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私は、３４５ページのコミュニティバスと、時間があれば３５５ページのＰａｒｋ－ＰＦＩについて、質問をお願いします。利用者で７０％を超えていますし、利用者でない無作為の方でも５０％、荏原や大崎ルートを早急に運行していただけると考えてよろしいか尋ねました。","respondent":"鈴木都市計画課長","answer":"コミュニティバス運行開始に当たりましては、より効果的な地域の新設などの検討を行って、まずは実施したです。本格実施か、大崎ルートにつきましては、この状況を見て適時適切に判断していきたいです。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その指標の中には、収益、収支率というのも重要な項目になっておりますか尋ねました。","respondent":"鈴木都市計画課長","answer":"大井ルートの判断基準につきましては、収支率５０％というところを１つの判断基準にしています。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１００円ということで、子どもは５０円となっております。ぜひその辺、収益率にこだわらず利便性を重視してほしいと考えているのですけれども、お考えはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"コミュニティバスを実施しているわけですが、公共が行う一方で、やはり区民の皆様から頂いている税金で運営していると。昨年度も今年度も予定していますが、様々なアンケートやお声も、頂いた内容を精査しながら総合的に判断していきたいです。","id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望としては、例えば体操教室やミニデイサービスといった高齢者の集いの場に、ぜひ運行ルートをつくっていただきたいという要望があります。要望ですけれども、要望が本当に多いので、ぜひ。","respondent":"鈴木都市計画課長","answer":"バスが非常に充実しておりまして、比較的、交通不便地域についてコミュニティバスを実施していくという基本的な姿勢を持ってあります。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"Ｐａｒｋ－ＰＦＩは、一言、要望です。やはり地域の方の憩いの場というものを考えていただきたいので、地域の方が楽しめるということもしっかり考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"こしば委員","kind":"質問・要望","question":"３４５ページ、３５５ページ、順にお伺いいたします。新規で家庭などといったところに井戸を設置しているようなところはあるのかどうかも含めて、まず教えてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"区内にどれだけ民間の井戸があるかですが、詳しい数字は把握しておりませんが、５０か所程度ではないかということで認識しているところです。災害時用に、公助として井戸は、各避難所に水利として確保しています。","id":"exchange-071"},{"speaker":"こしば委員","kind":"質問","question":"井戸が、大体１８０か所と言われておりますが、指定されているそうです。一定の補助をつけるなど、環境を整えてもらいたいと考えますが、ご見解をお伺いいたします。","respondent":"羽鳥防災体制整備担当課長","answer":"品川区内には、都心にいながら路地に手押しポンプ型の井戸があるというところは、品川区ならではの魅力的な風景の一つであると認識しています。引き続き、他区の状況等も観察しながら、取組を進めていきたいと考えております。","id":"exchange-072"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ前向きに、品川区における井戸の活用を検討いただきたいと思いまして、シェアサイクルの質問に移らせていただきます。そういったことを募集するなどすれば、今の１つ目の課題解決にもつながってくると思いますが、ご見解をお伺いしたいと思います。","respondent":"櫻木土木管理課長","answer":"そこに自転車が集中することによって交通の不便等も発生してしまうという可能性もありまして、調整が少し難しいということではあります。","id":"exchange-073"},{"speaker":"こしば委員","kind":"質問・要望","question":"駅のサイクルスポットにシェアサイクルが密集することを防げるとも考えますし、また例えば西大井駅にはサイクルスポットが今ない状況です。ぜひサイクルスポットを設置することを検討してほしいと求めましたが、ご見解をお伺いいたします。","respondent":"櫻木土木管理課長","answer":"基本的に、公有地につきましても、使えるところはできるだけ検討していくような方向で、これまで考えてまいりました。シェアサイクルまたは駐輪需要が多いという状況は把握しておりますので、様々お声を聞きながら進めてまいりたいと考えています。","id":"exchange-074"},{"speaker":"こしば委員","kind":"質問・要望","question":"普及拡大に努めていただきたいというのもあるのですが、先ほどコミュニティバスの話も出ていたところです。ぜひそういったことも踏まえて、地域のモビリティの需要を酌んでいただきまして、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"つる委員","kind":"質問・要望","question":"今年ですか、当時の作文や絵を活用して、それをいろいろな区で学ぶという防災教育をやっているところもあると伺いました。これはほかの委員会でも確認させていただきましたが、今の現状の品川区のお考え、またこうした協定についての考え方を説明するよう求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"有効活用を行いながら、様々お声を頂いて、備蓄物資の改善に努めているという状況です。コストなど、様々課題があると思いますので、よりよい有効活用の手法について今後検討してまいりたいと思います。","id":"exchange-076"},{"speaker":"つる委員","kind":"質問","question":"実際、令和７年度、２０２５年３月かと思いますが、来年度に向けて今、粛々と、しながわシティランということで準備をされています。対応できないときもありますというエクスキューズが一応あるのですが、私道の場合の対応について現状を、概要を説明するよう求めました。","respondent":"森道路課長","answer":"私道についての陳情が寄せられますと、私道整備助成を行っております建築課と情報共有するように、体制を改めて確認したところです。","id":"exchange-077"},{"speaker":"つる委員","kind":"意見","question":"間違いない業者といったところをご紹介するというような流れが１つあろうかと思います。１つ、この辺の条件緩和などについて、今現在のお考えをお示しくださいとの意見を述べました。","respondent":"長尾建築課長","answer":"２.５ｍ以上の道幅の場合は、全額、区が負担して私道を整備している状況です。私道の所有者の方、沿道の方に承諾いただければ、助成ができます」というところもご案内している状況です。","id":"exchange-078"},{"speaker":"つる委員","kind":"提案","question":"根上がり対策だけれども根下げということで提案して、３か年度かけてやっていただいていて、桜の木であります。それに関連して、今現在、品川区内にある街路樹に対して、桜の本数が何本あるのか説明を求めました。","respondent":"森道路課長","answer":"現在、街路樹につきましては３,８３３本、桜につきましては、そのうち１,４６７本、３８.２％です。","id":"exchange-079"},{"speaker":"つる委員","kind":"質問・要望","question":"昨年の決算特別委員会で確認させていただいたより分母が少し減って、桜が増えている。桜を増やしてほしいという強い思いを実現していただいていると思いますけれども、桜がまた来年度、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、３５３ページ、みんなに愛される公園づくり、３３１ページ、交通安全啓発費、そして３６５ページ、防災対策全般についてお伺いします。民間の方たち、特に避難所運営をされる方たちで、誰がそういった方たちを本当に止めることができるのか尋ねました。","respondent":"高梨公園課長、工藤交通安全担当課長、平原防災課長","answer":"委員がおっしゃるとおり、あらゆる人が１００％満足できる公園というものは、私どもとしてもあり得ないと思ってあります。… これは警察と連携してになりますけれども、実施しています。引き続き、新たな道路法の改正等もありましたら、順次、周知に努めてまいりたいと考えておりま… 何が必要か、その時々の判断をしながら、対策を重ねて対応していくこととなっていくかと思います。","id":"exchange-081"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん子どものうちから教えていただくのはそうですけれども、大人が今乗っているので、しっかり検討してほしいと求めました。これは要望で終わりますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私たちも本当に求めてきたわけですけれども、説明会を何度どれだけ求めても、５月１１日に工事を再開したわけです。トラブル続きということで、これだけスムーズにいっていないということに対して、区としてどう捉えているかについても伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"抜本的な対応として、ＪＲ東海が事業者の責任の下、進めている事業です。再開の見通しですが、先ほど委員がおっしゃられたとおり、調査掘進の再開は来春を見込んでいると。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それに対して、どういう状況になっているのかということになっているわけですから、説明会を区として求めていただきたい。いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の開催ですが、現状といたしましては、今回の事象に関しまして説明会の開催有無につきましては、ＪＲ東海から報告は受けてございません。区といたしましては、区民の不安の声に対して丁寧に取り組み、不安払拭を図るように引き続き求めてまいります。","id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"では、不安払拭のためにＪＲ東海に求めていくというのは、不安払拭をしてくださいということで求めていくのですか。それなので、不安払拭に努めていきたいというのであれば、区からぜひとも説明会を求めていただきたい。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の開催ですが、ご質問等につきましては工事事務所などで対応し、丁寧にお答えしていくと聞いてあります。区といたしましては、説明会という手法にこだわらず、区民の不安払拭という目的を達成できるように引き続き求めていくものです。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、どうやって不安払拭に努めてくださいとＪＲ東海に求めるのですかということで聞いているのです。説明会をなぜ求められないのかという理由についても伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会を求める、区民一人一人の声に対して真摯に対応していただく、それが区民の不安払拭につながると考えています。説明会に関しましても、しっかりと、そちらの不安の声に対応していくよう繰り返し求めていくものです。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ＪＲ東海に向き合っていただきたいということで、ここのところでぜひとも説明会を求めてほしいと求めましたけれども、改めて伺います。それと、外環道に対しての把握についても、ぜひともしてほしいと求めましたが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"外環道の地盤補強の件ですが、今後そちらの状況もしっかりと把握できるようにしていきたいと思います。工事事務所等を通して誠実にお答えしていくということを聞いておりますので、引き続き、ＪＲ東海に対しては求めていきたいと考えています。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ＪＲ東海に説明会を求めるということで、改めて区として求めるということをしていただきたいということで、求めておきたいと思います。そういう中で、ぜひとも私は中止を求めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"それを１つ、以前の事務事業評価を改めて確認しますと、これは例えば再開発やまちづくりなどといった分野になってくるのだろうと思います。１つの考え方というのでしょうか、切り口、見方をお聞かせほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"あるいは継続的に実施するもの、必要性・有効性、効率性というものを勘案しながら評価作業を進めているところです。どういった手法ができるのか、あるいは細かいところで改善できるのかというところも見ながら、評価作業を進めてきているようなところです。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"なので、人道橋の目的としては、ほとんどが回遊性を求める橋になってしまうのか。そういう、いわゆる費用対効果という視点からの検証や検討状況はいかがなのか尋ねました。","respondent":"森道路課長","answer":"私からお答えしますけれども、かなり地域からの強い要望を頂きながら整備を進めていると区としては考えておりまして、説明会をやる中でも。説明会の中でもお話をしますけれども、国のマニュアルに基づいたＢ／Ｃも算出し、１を十分に超えていくということを確認しています。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問・要望","question":"恐らく２０億円という予算を踏まえた中での要望ではないと私は思っていて、その発表がある前の段階からの要望でありまして、では具体的に２０億円かかるという前提の下での要望なのかどうかというのはしっかり検証すべきですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３３１ページ、道路・公園等監察費、３３５ページ、路面等改良費の２点を、順不同ですが、お伺いします。この遊歩道ですけれども、舗装修繕計画には遊歩道の計画は見当たらないのですが、遊歩道の維持管理計画というのはどのようになっているのか尋ねました。","respondent":"森道路課長","answer":"今ご紹介いただきました品川区の舗装修繕計画につきましては、舗装に大きな影響を与えるのが、大型車がどれぐらい通るかというお話になります。ですので、影響を受けるのが大きな車道ですので、遊歩道については、個々にそれぞれ陳情を頂きながらというふうに考えています。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問","question":"今まで大きな事故はなかったと記憶しておりますけれども、このままでいくと、いつ事故が起きてもおかしくないという状況にも捉えられます。早急に、ここの路面改良をお願いしたいという声がありますけれども、いかがか尋ねました。","respondent":"森道路課長","answer":"それから、水系施設といいましょうか、水が流れる水系施設も今使われていないというような状況です。少しがたつきがあるというようなことは認識しておりまして、非常に高い優先度であると、修繕に向けて検討を様々進めていきたいと考えています。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。ここの公園について、まずルールをお聞きしたいのですが、ペットの立入りについてのルールはどうなっていますか尋ねました。","respondent":"高梨公園課長","answer":"しながわ中央公園の多目的広場西側部分、ヘリポートがある部分ですが、こちらについて、ペットの立入り、主に犬であろうかと思いますが、舗装されている部分のみ立入りをしていただける、草地の部分についてはご遠慮いただくということで運用させていただいています。","id":"exchange-094"},{"speaker":"こんの委員","kind":"確認","question":"それで、その時間帯ですから、芝生にワンちゃんを放して、いわゆるドッグラン化しているということなのです。１つ、今どのような対応をされているか、現状を説明するよう求めました。","respondent":"高梨公園課長","answer":"衛生上も非常に問題のある行為であると、公園管理者としても認識しておりまして、公園の巡回を早朝からしたところです。継続して巡回を回して、人的対応で、そういった迷惑となるような行為がなくなるように努めるという対応を取ってあります。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"公園の通りを道行く人にも分かるように、抑止力の目として、通る人の目も飼い主への抑止力となるのではないかというお声も頂いております。ですので、大きな看板などを設置していただくというのもあるかと思いますが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"ご提案ありがとうあります。看板も含めて検討してまいりますが、昨今、バランスを見ながら効果的な周知・啓発方法に努めてまいりたいと考えています。","id":"exchange-096"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３５５ページ、しながわ水族館と、同じページのＰａｒｋ－ＰＦＩについて伺います。近隣の方とどういうふうにしていくかというのは、私はやはり、ここは２１時ぐらいまでは開けられるようにしてほしいというのが１つのお願い。","respondent":"高梨公園課長、北原河川下水道課長","answer":"そういったところがどの程度改善していくのかというのも見定めながら、恒久的なドックランの設置の可否については検討してまいりたいと考えています。東品川海上公園の仮設ドッグランは今年度から実施していく計画ですので… 我々としましては、仮称ですが水辺利活用推進計画を策定する予定でおりまして、その中で地元の意見も踏まえて検討していきたいと思っています。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"イベント型にしても、これは私もその中でやっていきますけれども、ぜひそれを頭に入れてやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"３６４ページ、防災費全般から伺わせてほしいと求めました。改めて、ぜひとも専門的視点を積極的に反映してほしいと求めましたが、今後の検討と区の見解について尋ねました。","respondent":"平原防災課長","answer":"災害時における助産師との連携ですけれども、連絡体制の確認というようなレベルで、まだ具体的な中身に入っていないのが現状です。そういった視点がかなり重要だということはこちらも認識しておりますので、今後、その中で話合いを拡大してまいりたいと考えています。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問","question":"以前の決算特別委員会で、我が会派のまつざわ委員が、避難所における女性の参画促進について質問をしています。男性その他、様々な状況にある方がバランスよくいる必要があると思いますけれども、現在の状況と区のお考えを説明するよう求めました。","respondent":"平原防災課長","answer":"災害・環境対策特別委員会でお答えさせていただいたのですけれども、女性の参加というところでは、女性は極めて少ないというのが私の認識です。区といたしましては、どのような形で女性に参画いただけるかも含めて、検討を現在進めているところです。","id":"exchange-100"},{"speaker":"西村委員","kind":"質問","question":"そういった意味におきましては、事前に伺いましたときに防災課に行かせていただきましたら、女性の職員の方が増えているという実感がありまして、防災課内で防災対策を考える女性のプロジェクトがあるとも伺っておりますので、改めまして取組に関して説明を求めました。","respondent":"平原防災課長","answer":"２.３倍になっております。女性職員がどのような形で当たることができるのかといったところも含めて検討いただいておりまして、現在まだ検討が進んでいるところなので、今。","id":"exchange-101","title":"町会・自治会支援"},{"speaker":"西村委員","kind":"質問・要望","question":"まさにそのお話を今させていただきたいと思っていたのですが、令和３年なのですけれども、まさに女性職員の方たちだったという資料を拝見しました。年齢等にかかわらず、働きやすい環境を実現するために取り組んでいただいていると思うのですが、現状と今後の課題や取組について説明を求めました。","respondent":"平原防災課長","answer":"防災課の中で検討を進めているところで、女性ならではでどのようなスペースが必要なのか、あるいはどのようなローテーションが必要なのか。検討を進めているところでございまして、また一定程度、形にできるようになりましたら取り入れてまいりたいと考えています。","id":"exchange-102"},{"speaker":"西村委員","kind":"提案","question":"もう一つ、違う角度からご提案させていただきたいのが、防災語学ボランティアになります。こちらは、今、何かご検討段階や、これまで検討されたことがありましたら説明を求めました。","respondent":"平原防災課長","answer":"原則の流れでいきますと、一方で、東京全域を含めて人数がそんなにいないのではないかということでお聞きしています。区ではまだ、要配慮者のうち外国人に対してもどのような形で対応が必要かといったところは、今後も引き続き検討してまいりたいと考えています。","id":"exchange-103"},{"speaker":"西村委員","kind":"質問・要望","question":"実際に語学ボランティアの方にお話を伺ったのですけれども、地震のない国から来た外国人の方はなかなか実感が湧きづらいと。それぞれの区でも募集をされておられるのを拝見しておりますので、ぜひともいま一度ご検討いただきたいと思うのですが、もう一言お願いいたします。","respondent":"平原防災課長","answer":"実際に顔の見える関係でやっていただく対応というのはどうしても必要になっていくような場で、どのような形でそういった方々が確保できるのか。これはまず、大本のところの東京都の語学ボランティアを含めて、しっかりと連携しながら進めてまいりたいと考えています。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"そこでお伺いいたします。区内の自転車での交通事故発生状況と、その特徴についてお伺いいたします。","respondent":"工藤交通安全担当課長","answer":"次に、自転車利用者に対する交通安全の周知ですけれども、こちらは先ほどの答弁と重複する形になりますが、非常に重要であると認識しております。子どもから大人、高齢者まで幅広い方々を対象に、しっかりと交通ルールを周知してまいります。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"最近は自転車利用者のルール・マナー違反が大きな社会問題になっていることを踏まえ、区としてどのような取組を行っているのでしょうか。説明を求めました。","respondent":"工藤交通安全担当課長","answer":"小学校に入りますと３年生ぐらいから、自転車に乗るような指導が行われております。令和４年度から実施しました自転車安全利用指導員を、事故の多い交差点、自転車の交通量の多い交差点等に配置しまして。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"伺います。子どもから高齢者まで幅広い層に、どのように交通安全の浸透を図っているのかをお聞きいたします。","respondent":"工藤交通安全担当課長","answer":"やはりこの辺をしっかり認識されていない方もまだいらっしゃると思いますので、警察と連携しながら、その辺の周知に努めてまいります。","id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"子どもから高齢者まで幅広い層に、どのように交通安全の浸透を図っているのかをお聞きしましたけれども、また働き盛りの方や子育て世代の方に対する周知はどのように行っているのかを説明するよう求めました。","respondent":"工藤交通安全担当課長","answer":"幼稚園等での交通安全教室を行い、交通安全について触れて、話をしていただくといったこと。これも警察と連携しまして、広く周知し、交通安全をしていただくよう努めているところです。","id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"伺います。自転車安全利用指導員の具体的な活動内容を説明するよう求めました。","respondent":"工藤交通安全担当課長","answer":"自転車安全利用指導員の具体的な活動内容についてご説明いたします。警備員が直接指導を行うということで、幅広く注意喚起を行いながら、交通ルールの周知活動を行っているところです。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"意見","question":"各会派にお願いしているのに、会派で集まっていないところがあるのに始めるわけにはいかないと思う。そんなのだったら、きちんと理事会で話したほうがいいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"意見","question":"それだったら理事会でもう一回しっかり話すのだ。そういう申合せを出しているのだからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"会派政治をきちんとしっかりやっているのだから。私はそう思うので、終わってからでもいいので、ぜひそれはもう一度やってくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"成果があるのですかということ。この「等」というのがよく分からないし、それから、本当にこれは役に立っているのですかということを、まずお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"コーディネート業務、地域のにぎわいの創出を行っているとか、大崎駅の北口自由通路の検討を今行っているというような状況です。今のまちづくりの状況を、ビラ等を作って約６,０００部、または地域で行っていますまちづくりの支援といったところを委託で掲出しています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区のまちづくりに対してどういう成果があるのかというのを示していただきたいのです。どこがどういう役割分担になっていて、どういう成果があって、その調整をどうされますか。","respondent":"中道都市開発課長","answer":"その中で地域で話し合って再開発事業を進めていくという決定をした中で、準備組合をつくっていくと区は認識しております。そうしたものをつくるに当たっても、地域の方々と話をしながら、またアンケートを取りながら進めているです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"商店街は商店街の中での再開発というのはあるべきだと思うし、それを支援するという形を取ったら納得がいくという方法も出てくるのではないか。やはり細分化して、そのパートごとに再開発を進めていくという手法も必要ではないかと思いますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"大井町駅周辺地域まちづくり方針を策定して、活力創造ゾーンという形で、地域のにぎわいを創出していきたいというところで方向性を示しています。区としては、また地域の声を聞きながら、まちづくりを支援していきたいと考えています。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"ですから、細分化して考えたらいかがでしょうかということを言っているのです。住民の生活を維持しながらというところの視点で、再開発というのを変えていくべきところがあるのではないかと思いますが、お考えをお聞きします。","respondent":"中道都市開発課長","answer":"まちづくりのことですけれども、特に今、一体的にやるかやらないかということも決まっていないです。一体的にしていくのかということも踏まえて、今、お話合いが行われているという状況です。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜかといったら、やはり丸ごとやっていこうという人もいれば、それは嫌だという人もいれば、新しい方法を見いだしていく。再開発をするための新たな視点での、国、それから東京都へ助成金をぜひ求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"３６９ページの医療救護体制整備費からは２点ほど、過去の話ですが、確認させてほしいと求めました。医療資器材で言いますと８５種類、こういったランニングストックというのでしょうか、ローリングストック。","respondent":"平原防災課長、北原河川下水道課長","answer":"この３つがありますが、まず２つ、有効期限を確認しながら入替えを進めるというような状況です。こういったところの関係で、使用期限等々を確認させていただいているところです。新たな補助制度を開始しておりまして、事業費の立ち上げの運航費や、船のバリアフリー化を行う補助を新しくつくったものです。","id":"exchange-118"},{"speaker":"若林委員","kind":"質問・要望","question":"見通していらっしゃるのかというのを確認するのと、まさに計画がこれからですからという答弁になるのであれば、そんなに遠い話ではないと。呑川でやっているから目黒川でもやってくださいという単純な話ではないのですけれども、ぜひその辺の取組を今後確認させてほしいと求めました。","respondent":"平原防災課長、北原河川下水道課長","answer":"医療資器材ですけれども、私どものところで全量、管理簿をつけておりまして、その管理簿に書かれている有効期限を現場で確認しながら保管しています。そのような形で確認作業を進めております。現在、なかなか時間がかかる問題ではありますけれども、きちんと早く達成できるように検討させていただきたいと思っています。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"提案","question":"今回１１月１日からの無人化に伴ってどのような課題が生じるとお考えになるでしょうか。それも、８時半から１０時までの、ヤマダ電機の開店前までですれば、先ほどのお話、前の質疑にもあった階段を使わなくて済むとご提案いたしましたとの意見を述べました。","respondent":"高梨公園課長、鈴木都市計画課長、森道路課長","answer":"花海道におきましては、通過自転車による陳情が非常に多く区に寄せられておりまして、非常に対応に苦慮している状況です。その中で… ＪＲの社員の対応も非常に減ってきているというところと、都内の駅ですと今現在３０駅、計画的に行われているという説明を頂いたところです。… １つ、きゅりあんを中心に考えていきたいと考えておりまして、所管の文化観光課とは協議を始めたところです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"大井町のところが少し分からなかったのですが、確認も含めて、ヤマダ電機のデジタル館のほうについて協議が進んでいると受け取っていいのでしょうか。都市計画法上、あそこは都市計画でつくられたところなので、それができないのかというところも確認したいと思います。","respondent":"森道路課長","answer":"稼働時間として１０時からというところがありますので、朝の時間帯も含めて、確認できるきゅりあんを中心に今考えていきたいところです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこの交渉を、協議を進めていないという状況なので、ぜひお願いしたいと思います。これは強い要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３３９ページの水辺利活用事業についてお伺いします。昨年度の取組として、天王洲水辺広場整備について、どのような整備を行ったのか示すよう求めました。","respondent":"北原河川下水道課長","answer":"今回はもともと一般開放されていなかった東品川二丁目の天王洲運河護岸沿いの新東海橋から目黒川水門に至る２００ｍの区間を広場として整備しました。舗装しまして照明やフェンスなどを整備し、名称を天王洲アイル第五水辺広場として、今年の５月から開放しております。","id":"exchange-123"},{"speaker":"えのした委員","kind":"質問・要望","question":"今後も機会を捉えて整備を続けていくよう要望します。続きまして、ヒカリの水辺プロジェクトについてお伺いします。","respondent":"北原河川下水道課長","answer":"ライトアップにつきましては、鈴懸歩道橋やアイル橋など、目黒川や運河に架かる１３橋で実施しているところです。冬の桜、自殺予防週間や交通安全の関連とも連携して、社会運動への支援・協賛を表すアウェアネスカラーによる演出も行っているところです。","id":"exchange-124"},{"speaker":"えのした委員","kind":"質問","question":"今後は２０２５年デフリンピック東京大会に向けた周知、先日も委員から質問があった乳がん検診、ピンクリボン期間などいかがでしょうか。区のお考えを示すよう求めました。","respondent":"北原河川下水道課長","answer":"関連する課と連携してプレスを行うなど周知を図っておりまして、一層、ＰＲできる方法を検討してまいります。ほかにも連携できるものがないかというのも検討してまいります。","id":"exchange-125"},{"speaker":"えのした委員","kind":"質問","question":"次に、舟運社会実験についてお伺いします。こちらの事業の概要と成果、またアンケート調査も実施しているとのことですが、その結果についてもお伺いします。","respondent":"北原河川下水道課長","answer":"朝夕の通勤時間に東京都と連携して実施したものでして、都内では６航路、品川区内では五反田・天王洲間で実施しております。満足度についても、よかったという方が９割以上、７割近くの方から「利用する」または「多分利用する」という回答を頂いているところです。","id":"exchange-126"},{"speaker":"えのした委員","kind":"質問","question":"会派では７月に、先日は水辺議連として、しながわ水辺の観光フェスタのお手伝いをしてきました。今後の取組をお伺いします。","respondent":"北原河川下水道課長","answer":"先ほどからもお伝えしているように、区では令和６年度に向け、新たな推進計画を策定する予定で検討を進めております。そういった形で検討を進め、ソフトにもつながるような対策を進めていければと考えております。","id":"exchange-127"},{"speaker":"えのした委員","kind":"意見","question":"新たな人を水辺に呼び込む仕掛けやイベントの割引等、誰もが水辺を楽しめる機会の創出のためにも、イベントに参加しやすい取組が必要だと考えます。区のご見解をお知らせくださいとの意見を述べました。","respondent":"北原河川下水道課長","answer":"どう取組を伝えていくか、また、どう参加していただくかというのが非常に重要と考えています。委員のご提案を踏まえて、可能な取組がないか、他の都市などの事例も含めて、関連部署と連携して研究・検討してまいります。","id":"exchange-128"},{"speaker":"松本委員","kind":"質問","question":"私からは、３３１ページ、駅周辺等放置自転車対策事業、３５９ページ、コンクリートブロック塀等安全化支援事業について伺います。例えば、平日なのか土日祝日なのかなど、その辺りをお願いいたします。","respondent":"工藤交通安全担当課長","answer":"こちらは年１回、東京都が実施している調査になります。１０月の平日に行われまして、各駅周辺の１日の放置自転車の台数を調査した数値となります。","id":"exchange-129"},{"speaker":"松本委員","kind":"質問","question":"ただ一方で、飲食店の近くに、夜になると放置自転車がよく見られるというのを拝見いたします。品川区としても夜の時間帯、どういうふうに放置自転車があるのかということは把握されたほうがいいのではないかと思いますが、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"平日のおおむね午前１１時頃、駅周辺の放置自転車を調査しているものです。その必要性を検討しまして、実施に向け、検討してまいりたいと考えております。","id":"exchange-130"},{"speaker":"松本委員","kind":"確認","question":"分かりました。もう一回確認で、撤去の時間帯といいますか、どういうふうに行われているのかを改めて伺えればと思います。","respondent":"工藤交通安全担当課長","answer":"放置自転車の撤去の関係ですけれども、こちらは業者に委託しまして、午前９時から午後７時までの間で、それぞれの駅等、放置自転車の多いところを重点的に回って撤去を行っているというような状況です。","id":"exchange-131","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"質問・要望","question":"ご要望も頂いているので具体的なお話をしたいのですけれども、ただ一方で飲食店が十数軒ぐらいですか、並んでいる道路かと思います。先ほどは午後７時までということで、夜間についてもご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"撤去自転車ですが、撤去の時間については午前１０時から１７時まで、保管所に運び込まれる最終時間が１９時までということになってあります。","id":"exchange-132"},{"speaker":"松本委員","kind":"質問・要望","question":"１７時ということなので、夜間も委託していただけるようにご要望させていただきまして、次の質問に移りたいと思います。たしか当時お伺いしたのは、８０ｃｍ以上が１００km以上あるというお話だったかと思うのですけれども、区としては除却の助成をされていると。","respondent":"長尾建築課長","answer":"これまで事業を大体５年ほど行う中で、除却も年間に２００ｍから４００ｍ程度、進んでいる状況です。１００kmほどのうち、老朽化している部分の数量については正確には把握していないところなのですけれども、かなりの数量があると認識しております。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問・要望","question":"他の自治体でも、実際に危険なところを調べて、そのうちの１割ぐらいしかまだ終わっていないという話もあります。最後は要望になってしまいますけれども、特に通学路近くについては、ぜひ戸別もしていただくようにお願いいたしまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、今まで要望等もしてきたので、質問しますが、まず西大井駅の、毎回言っていますが、西口改札口開設はどうなっていますか。お伺いします。","respondent":"溝口防災まちづくり部長、大串会計管理者、鈴木都市計画課長、工藤交通安全担当課長、北原河川下水道課長、森道路課長、小川木密整備推進課長、中道都市開発課長、大石まちづくり立体化担当課長、高梨公園課長、櫻木土木管理課長、長尾建築課長、竹田住宅課長","answer":"やはり品川区の特徴として、公共交通機関がしっかり整備されている中、自転車の利用はというところの方針を取っていたところもあります。今後… それに伴いまして、平成３０年の予算書から、いわゆる１課１目という形で表記を今現在までさせていただいているです。… 自転車活用推進法が平成２８年に国で策定されたというところで、区でも促進計画の策定を進めているところですが、計画の策定を進めているです。… こちらにつきましては、年間１０件弱の事故が発生しているということで警察から伺っております。","id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６４ページ、防災費について、予防対策の拡充を求めて、３５１ページ、武蔵小山駅周辺地区再開発事業について、中止を求めて伺います。防災対策に予防策をしっかりと位置づけてほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"災害時にいかに被害を軽減させるかという点も含めまして、普及啓発という形で、自助・共助といった取組の支援をさせていただいたところです。今般、地域防災計画の見直しも進めておりますが、そういったところもさらに取組を強化する方向で現在検討を進めているところです。","id":"exchange-136"},{"speaker":"のだて委員","kind":"質問・要望","question":"その前に、やはり予防策として被害を軽減していくということが公助に求められると思いますので、伺います。住宅の耐震化・不燃化をさらに促進していくのに向けて、その課題は何か、伺います。","respondent":"長尾建築課長、小川木密整備推進課長","answer":"昨年度から戸別訪問を実施しておりますが、これまでも支援事業をやってきている中で、またアンケートをやる中で確認してきております。そういった事業周知のところが、やはり１つ、課題であると認識しております。不燃化の課題につきましても、耐震化と同じように、事業の周知といったものが非常に重要かと考えています。","id":"exchange-137"},{"speaker":"のだて委員","kind":"質問・要望","question":"現状から全壊棟数を６割減らせると示していますので、そこを目指してほしいと求めましたけれども、いかがでしょうか。やはり建て替えなども進んで、耐震化・不燃化が区内全体として進んでいくと思いますが、いかがか尋ねました。","respondent":"長尾建築課長、小川木密整備推進課長","answer":"特に木造住宅につきまして、品川区内、荏原エリアにまだ多く密集している状況が続いております。引き続き、耐震化支援事業を、周知も含めてしっかりとやっていきたいと考えております。 不燃化特区以外の２町丁目につきまして、今現在、建物の状況や不燃領域率の調査を行っているところです。この調査を踏まえて、来年度以降、この２町丁目に対して拡大を検討してまいりたいと考えています。","id":"exchange-138","title":"町会・自治会支援"},{"speaker":"のだて委員","kind":"質問・要望","question":"２町丁目に拡大を検討しているということで、耐震化も１００％を目指していっていただきたいと、これは求めておきたいと思います。なかなか全体を把握するのは難しいと思うのですが、区がどう考えているのか伺いたいと思います。","respondent":"竹田住宅課長、平原防災課長","answer":"その原因ですけれども、比較的簡単にお店に行って工具等を購入して、ご自分でできるというケースが多くなってきたものだと考えております。この制度そのものを根本的に今後、見直しというか検討していきたいと考えております。 家具の転倒防止を行っている家庭の割合ですが、大変申し訳ございません。様々なところで販売しているものですので、どういったところから購入してどのぐらいといったことにつきましては、数字は持ってございません。","id":"exchange-139"},{"speaker":"のだて委員","kind":"質問","question":"申請いただいた方がなぜしていただいたのかということなども調査していただいて、検討されていくのか、伺います。","respondent":"竹田住宅課長","answer":"この制度を利用された方からヒアリング等しまして、さらにこちらの制度のスキーム等について、今後しっかり検討していきたいと考えています。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"そちらと併せてやっていただきたいのと、高齢者と同様の拡充をしていっていただきたいと求めておきたいと思います。簡単に出火防止ができるものですので、ぜひ進めてほしいと求めましたが、どう進めていこうと考えているのか伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"機能的に住宅全体を網羅できているというところも、なかなかお伝えできていないのかというところが課題かと思います。この機会に東京都と連携して、感震ブレーカーの機能周知にも活用して、ＰＲを強化してまいりたいと考えております。","id":"exchange-141"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の助成対象をぜひ広げていただいて、今、不燃化特区の範囲だけとなっておりますので、そこは対象を広げていただきたいと求めておきたいと思います。そうしたら、元いた地権者や既存のお店が何割程度戻ってきたのかということもお答えいただけないか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"戻ってきた方というところにつきましては、個人情報等の権利の話になりますので、非公表という形で聞いております。お店につきましても、テナントが入ったり出たりというところもありますので、区としてもこの間、度々、確認しています。","id":"exchange-142"},{"speaker":"のだて委員","kind":"質問","question":"個人情報等で非公表という話なのですけれども、何割が戻ってきたのかというのは個人情報とは関係ないと思うのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"もともと権利を持っている方というところもありますので、そうしたところで非公表と聞いてあります。","id":"exchange-143"},{"speaker":"のだて委員","kind":"質問","question":"区は人数を把握されていますけれども公表できないということで、住民が住み続けられない、お店も続けていけないという状況です。これは区として適切だと思っているのか、伺います。","respondent":"中道都市開発課長","answer":"市街地再開発事業の中では、都市再開発法の中で進めている事業というところで、地区内に住み続けることも保障いただいて、地区外へ移転することも選択できる自由の中で、権利者の方々で権利を保障されているという制度です。","id":"exchange-144"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした選択があると言いますが、それは選びたくない、今のまま住み続けたいという方がいらっしゃる下でこれを進めるのはやめるべきだと求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから３６３ページ、３３５ページか３４１ページになるか、雨水流出抑制費もしくは治水対策推進助成事業から伺います。再開発ビルや再開発地域の保育環境はどうなのかと思いますが、その地域の方たちがそれを求めている状況では、それは必要な施策だったのかと思います。","respondent":"中道都市開発課長","answer":"そこについては、地域の特性を踏まえて、いかに公共性のあるまちづくりを進めるかという観点で、区としても捉えて指導しているです。数につきましては、今現在、詳細なものを持っていないです。","id":"exchange-146"},{"speaker":"吉田委員","kind":"質問","question":"多分、これを聞くと、道路とか空地とか、お答えが来るだろうと思ったので、区民が利用できる公共施設がどれぐらいできたのかという質問にしたのです。実績は一つか二つ、少なくとも把握されているかと思うのですが、説明を求めました。","respondent":"中道都市開発課長","answer":"大崎地区におかれましては、今、区民利用ができるという観点で言えば、美術館を設置しています。武蔵小山におかれましては、地域センターなど、また駐輪場、備蓄倉庫などといったところを整備しています。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問","question":"備蓄倉庫も、確かにいざというときには区民が利用する施設とも言えますが、私が例に挙げたような図書館や高齢者施設、障害者施設については整備されてこなかったということで理解してよろしいか尋ねました。","respondent":"中道都市開発課長","answer":"高齢者施設におかれましては、整備というか、既存にその施設がありましたので、また再開発したときにも設置したという経緯はあります。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、少なくともやはりそういう公共の施設をつくることが、再開発のときには求められているという理解は、それでよろしいですよね。今度の再開発にどういう公共的な施設が求められているか、再開発があるのだったら、こういう施設をつくってほしいと言うのか。","respondent":"中道都市開発課長","answer":"本当に再開発をするのかしないのかというところでの一定程度の判断の中で、庁内で、まずは再開発をする地域というところで情報共有は図っております。その中で、各所管からご提案を受けた中で、最終的にやはり判断するのは、準備組合もしくは組合というところになってきます。","id":"exchange-149"},{"speaker":"吉田委員","kind":"質問・要望","question":"最終的な判断は当然、少なくとも区で今いろいろな施設を求めるときに、それは土地がないからというようなお答えが返ってくると思うのです。その制度を使って、各所管からさぞかし上がっているのではないかと思って伺ったのですが、そういうことはあまりないという理解でよろしいか尋ねました。","respondent":"中道都市開発課長","answer":"要望につきましては、各地域におかれまして大なり小なりあるです。そこに対しては、準備組合、組合といったところで協議して決めていきます。","id":"exchange-150"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ入れてほしいという要望は出してほしいし、公共性のある、足りない施設を求めるようにということを促していってほしいと求めました。対策を求めて、ご相談者へのアドバイスを教えていただき、併せてすぐにご相談者のところへ状況確認をしに行ってくださったということで。","respondent":"竹田住宅課長","answer":"空き家の相談窓口の点から回答します。もう一点は区の住宅課で、空き家対策担当が相談に応じておりますので、３つの窓口が連携しながら、有機的に空き家の改善に努めているところです。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問・要望","question":"区の直接の相談窓口などということも、ぜひ検討していただきたいと思うのですけれども、いかがでしょうか。その辺についても、先ほどご答弁がなかったので説明を求めました。","respondent":"竹田住宅課長","answer":"それぞれ得手不得手、得意分野がありますので、得意分野を有効に活用しながら解決していきたいと考えています。委員ご指摘のような内容につきましても、最大限、実現していきたいと考えております。","id":"exchange-152"},{"speaker":"吉田委員","kind":"質問・要望","question":"今回は、枝がこちらに伸びてしまったということで、これも本当に、切らせるに至るまでは結構な手順が必要だというのを、私も説明を受けました。ぜひ区としても、そういう制度を前向きに検討してほしいと求めましたので、これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問","question":"後で伺ってみたところ、式典の最中に最終的に５人の方が体調を悪くされて倒れたということでした。品川区の防災課は、このような状況であったことをご存じかどうか伺います。","respondent":"伊藤災害対策担当課長","answer":"その後、品川消防団と消防署と連携いたしまして、どのような対応を取ったのか確認をいたしました。その他４人の方々につきましては、体調が割と回復されたということで、そのまま引き上げたと聞いてあります。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"提案","question":"実は平成２６年第３回都議会定例会でも、同様の問題提起と改善を求める内容を確認しました。確認したら、手を打ってほしいと求めましたが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"初めに、品川消防団の今回の５月下旬に消防団消防操法審査会を実施いたしまして、このような事態が発生してしまいました。２点目の質問ですが、今年度、消防団運営委員会は開催を予定しています。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２つ、品川区に要望です。そして、それを勉強会でしっかりと伝えていただきたい、このようにお願いしたいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"階段が２つあるというところでございまして、当然この２つに、エレベーター等の設置によってバリアフリー化が進められなければいけない。このバリアフリー化の検討を、利用状況あるいは区民の声をしっかりお聞きしながら進める必要があると、区としても認識しています。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"令和５年５月から６月の２か月間、品川区でも導入をということで要望しましたところ、「港区に確認したところ。この調査状況というか、注視されている状況の中でも、導入に向けた進捗状況を説明するよう求めました。","respondent":"工藤交通安全担当課長","answer":"品川区を含めまして１６区において取り扱っておりまして、うち４区は先行して、年間の申込を可能にしています。区といたしましては、他区の状況を引き続き注視しながら、効果の上がる形になるように検討してまいりたいと考えています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３月に要望させていただき、区長に緊急要望をして、物価高騰対策として５つの項目を申し入れました。ではどうすればいいのでしょうかと言われたときに、区民交通傷害保険１,４００円で、年間で１億円以上の保険が掛けられるということがありました。","respondent":"工藤交通安全担当課長","answer":"保険会社が支払った件数・金額につきましては、令和４年度で３９件、前年と比較費プラス１５件になっております。金額につきましては１５２万７,０５６円、前年と比較し１７万９,２２５円マイナスというような状況になってあります。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問","question":"そのうち、自転車の事故に関わる件数と、払われた金額が分かれば説明を求めました。","respondent":"工藤交通安全担当課長","answer":"自転車に払われた件数につきましては、保険会社から情報提供を受けておりませんので把握してございません。","id":"exchange-159"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"３５５ページのしながわ水族館リニューアルと、３４５ページのコミュニティバス運行経費について伺います。２０２０年のアンケート結果では、しながわ水族館の最寄り駅はどこでしょうかと聞いたときに、約４０％の方が品川駅と答えた。","respondent":"高梨公園課長","answer":"しながわ水族館のリニューアルに際しましては、品川駅のそばにある水族館との差別化というところは非常に大きなテーマであるとも考えてあります。","id":"exchange-160"},{"speaker":"せりざわ委員","kind":"提案","question":"これがレタスですと分からせるというのも１つ、認知度向上につながるのかというのが、１つご提案です。これも以前、議会で提案したことがあるのですが、大森海岸駅というのは、いざ降りてみると、海岸っぽさというのは実はないのですとの意見を述べました。","respondent":"高梨公園課長","answer":"リニューアルに向けても、さらに最寄り駅との連結、また大井町駅だけでなく大森駅との接続等々もしっかりと検討してまいりたいと考えています。","id":"exchange-161"},{"speaker":"せりざわ委員","kind":"提案","question":"２０２１年に議会でご提案したことがあるのですが、例えばそこから海を伝って、屋形船を使って引っ張ってくる。水路を使ってしながわ水族館に客層を呼び込むというのも１つ、手なのかと思うのですが、最後にこちらの見解を説明するよう求めました。","respondent":"高梨公園課長","answer":"バスで結んでまいりましたけれども、引き続き重要なルートであると考えていますので、検討してまいりたいと考えています。しっかりと桟橋も有効利用しながら、舟運でいろいろなところと結ぶ取組についても検討してまいりたいと考えています。","id":"exchange-162"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1540#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":125831,"voices":383}},{"id":"r05-20231016-4","meetingId":"r05-c-settlement","date":"2023年10月16日","dateIso":"2023-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件整理しています。","topics":[{"id":"topic-01","title":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、３８６ページ、図書館運営費、３９１ページ、学校図書館運営費についてお伺いします。学校図書館に整備すべき蔵書の標準がありますが、基準や内容、また、品川区内の学校図書館の状況はいかがか尋ねました。","respondent":"吉田品川図書館長","answer":"３７校中３０校が達成され、義務教育学校（後期）においては、１７校中７校が達成されているところです。ほとんどの小中学校におきまして、標準蔵書数の９０％以上は達成されていることとなっております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。そこで、実際、小学校、中学校で、本の貸出し数はどのようになっているのか、状況を示すよう求めました。","respondent":"吉田品川図書館長","answer":"傾向といたしましては、ここ数年、小学校の貸出数は著しく伸びが見られておりまして、令和３年度以降、１００万冊の貸出数を超えております。中学校につきましては、年間４万冊から５万冊と、少し貸出数が伸び悩んでいるところです。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"そこで、これからも本への興味が湧き、貸出数が増え、新たな取組を行えるように、職員の充実はされていますでしょうか。学校の先生にも話を伺いましたが、やはり資格をお持ちの方、専門性の高い方などのお力が必要だと強く感じました。","respondent":"吉田品川図書館長","answer":"現在の学校図書館運営支援につきましては、週２.５日の委託契約を４９週間、年間７３５時間の委託を行っているところです。これからも未来を担う子どもたちとの本の出会い、学ぶ喜びを与える場として、最も身近な学校図書館の支援を充実していければと考えております。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問・要望","question":"続いて、地区図書館についてお伺いします。私も品川区史を少し拝見し、映像は懐かしさを感じましたが、現在まで、どのくらい閲覧されていますか尋ねました。","respondent":"吉田品川図書館長","answer":"現在、古い資料につきましては１７資料公開中、今年度新たには１０資料を公開の予定です。今後も総合実施計画に基づきまして、アーカイブの拡充を進めてまいります。","id":"exchange-004"},{"speaker":"えのした委員","kind":"意見","question":"品川区立図書館の地区図書館１０館で指定管理者による運営を行い、事業連携を図りながら、各館で様々なサービスを展開されていると示されております。主な取組内容および成果をお知らせくださいとの意見を述べました。","respondent":"吉田品川図書館長","answer":"各図書館にはティーンズコーナーを設置しまして、ＰＯＰコンテストの開催とか、あとは試験前の自習スペースも図書館での提供を行ってきたところです。ティーンズボランティアを募集しておりまして、この応募につきましては、年々増加しています。","id":"exchange-005"},{"speaker":"えのした委員","kind":"確認","question":"本当に読書離れが進んでいるティーンズに向けてのイベントなど、様々な取組をされていることを確認できました。いろいろあると思いますが、授乳室があるところとないところがありましたので、こういったハードの面でも今後の整備をお聞かせ願えますか尋ねました。","respondent":"吉田品川図書館長","answer":"図書館においての授乳室は、今、６か所でそろえておるところです。比較的新しめのところについては、大きさの大小はありますけれども、授乳室を整備しています。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"学習環境、読書環境が向上するよう期待して、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、２点お伺いいたします。３８９ページの英検チャレンジ事業、３８１ページの市民科・各教科充実経費について、それぞれお伺いいたします。","respondent":"柏木学務課長","answer":"平成１８年度から、１年生からの英語科を実施するなど、品川区の教育の特色として英語の教育について力を入れてあります。そのことから、私立等への拡大については、現在のところ、検討はしてございません。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"現在の実情を確認させていただきました。区立学校に通学しているかどうかに関わらず、品川区内の子どもや大人たちの学習意欲の向上が、改めて区の今後の方向性をお聞きできればと思います。","respondent":"柏木学務課長","answer":"ですので、学校なり保護者がお金を１回支払うということは発生していないという状況があります。ただ、区民の方からのそういう声は教育委員会もいただいておりますので、今後については、そういう区民の声を参考に考えていきたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"続いて、３０１ページの市民科・各教科充実経費に関連して、学校における救命教育について質問いたします。瞬時にＡＥＤの場所と道順が確認できるアプリ登録をすることで、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"一般質問でも答弁したとおり、第８学年の保健の授業で実技を行っているところです。１０月の校長・園長連絡会で、学校保健のポータルサイトの紹介や、ＡＥＤ財団の『命を守る心肺蘇生・ＡＥＤ』教本の紹介をしたところです。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ＡＥＤや救命に関する普及啓発資材の無償配布申込みチラシが投入されております。こちらは、こちらの公立学校等へさらなる周知等について要望したいと思いますが、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"ご案内の無償配布の冊子につきましても、併せて学校のほうに周知を図っていきたいと考えております。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"私からは、３８５ページの介助員等委託、３７３ページのクラブ・部活動等経費、３８９ページの学校ＩＣＴ活用経費について伺います。３８５ページの介助員等委託について伺います。","respondent":"唐澤特別支援教育担当課長","answer":"学習支援員の配置状況については、令和４年度の実績として、小学校（前期）課程は３７０人、中学校（後期）課程は５８人となっております。支援が必要な児童・生徒は増加しており、今後もニーズがあるものと認識しております。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"そこで、少し細かくなるのですが、学習支援員、介助員の方々は、週何回、１日当たり何時間ほど働いていらっしゃるのでしょうか。各学校に何名配置されているのでしょうか、説明を求めました。","respondent":"唐澤特別支援教育担当課長","answer":"学習支援員は、基本的には１名の配置、介助員は、学校ごとに支援が必要な児童・生徒数に応じての配置となっております。１日配置が介助員についても多い現状となっております。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"そう考えますと、現状、要望がある児童・生徒に対して、十分に応えられていない状況ではないかとの認識ですが、いかがでしょうか。応えられていない場合は、その理由は何なのでしょうか、説明するよう求めました。","respondent":"唐澤特別支援教育担当課長","answer":"通常学級での支援がどのようにできるのかというところや、学習支援員の配置、または特別支援教室の利用といった様々な観点から支援を実施しています。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"要望する学校には週５回、そして少なくとも各クラス１名を配置できるよう、予算を増やしていただくことを要望いたします。ちなみに、令和４年度の当初予算の内訳、ＳｉｄｅＢｏｏｋｓで確認しましたら、学習支援員予算は約３,０００万円でした。","respondent":"唐澤特別支援教育担当課長","answer":"自閉症・情緒障害特別支援学級については、中学校で２校開設しており、宮前小学校で開設する予定となっております。まずはこの立ち上げを確実に行い、特別支援学級の教室などを設置する場所の確保など、総合的に判断しながら今後の状況を検討してまいります。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"次に、３７３ページのクラブ・部活動等経費について伺います。現在進んでいる区立学校の部活動の地域移行に向けた取組について簡潔に説明するよう求めました。","respondent":"中谷指導課長","answer":"円滑な実施ができることを目指していきたいと考えております。その成果と課題を整理しまして、次年度の継続実施や、学校の部活動への民間委託の導入などを進めていくことを検討しています。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"続いて伺います。主体的に部活動の地域連携、地域移行に取り組みたい意向があるところがあるようですが、区としてのお考えを説明するよう求めました。","respondent":"中谷指導課長","answer":"各学校がその部活動にふさわしいと考える方法を取り入れていくことが持続可能な活動につながっていくと考えております。そのアプローチの中の１つとして、地域の実態に応じて学校と連携しながら導入をして検証してまいりたいと考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"学校、地域の現場の声を聞き、子どもたちにとって望ましい持続可能な部活動の体制整備を進めていただけることを要望いたします。そのような考えの下でお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"正確な利用件数は把握できておりませんけれども、チャイルドラインからは、品川の児童・生徒たちからの利用が増えたという情報はいただいております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"時間も限られておりますので、この後の部分については、また別の機会で質問、要望します。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"令和５年度の委員のメンバーについても伺いますが、構成員については変わりはないのでしょうか、伺います。区長部局のほうにも伺うのですけれども、２回目の調査を行ったいじめ問題調査委員会の委員長はどなたになるのでしょうか、伺います。","respondent":"丸谷教育総合支援センター長、勝亦総務課長","answer":"令和５年度まで、このメンバーに変わりはございませんけれども、先日、学識経験者の斎藤氏につきましては、本人のご事情で退任されるです。新たに法律の専門家を１名追加したところです。これまで区には関わったことはございませんけれども、各分野の専門家としての実績のある方々をこちらのほうで探しまして、お願いした次第です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"すみません、区長部局のほうですが、誰が決めるのかという選出する方を説明するよう求めました。","respondent":"勝亦総務課長","answer":"委員会は区長部局で設置していますので、区長で決定しています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"区教委に伺いたいのですが、身内に近いというか、区教委に甘い答申を出したのはなぜなのでしょうか。区教委としての認識を伺います。","respondent":"丸谷教育総合支援センター長","answer":"今ございました区教委に甘いのではないかということですけれども、第三者的な立場で答申を出していただいたものです。こちらとしては、内容につきましても真摯に受け止めるということで、特段、区教委に忖度しているような内容というふうには捉えておりません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"６つの調査内容と調査結果について問題点を指摘しているのですけれども、問題点を指摘されたということについては、どのように捉えているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今回、いじめ問題調査委員会からいただきました指摘につきましても、品川区いじめ対策委員会のメンバーもご覧いただいていますので、そうしたものを踏まえながら、今後、同じような指摘を受けないように、調査、報告に当たっていただこうというふうに考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"その理由は何だったのか、改めて伺いたいと思います。それについてはどのように感じておられますでしょうか、伺います。","respondent":"勝亦総務課長","answer":"それから、重大事態としての認定の遅れがあったというふうに捉えてございまして、そちらについて調査を行っていくということで設置したものです。こちらにつきまして、そういった形で、いじめ対策委員会の調査についても評価を行っているです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"やはり質問に答えていないと思うのですけれども、区長部局の報告書の中では、区長部局が思った以上に、もしかすると、厳しい指摘になったのですよね。諮問事項も６つにわたっていますけれども、もう一回伺いたいのですけれども、伺いたいと思います。","respondent":"勝亦総務課長","answer":"事務局の対応について調査が行われていない、それから、調査期間が長い等の指摘がされてあります。先ほど教育委員会から答弁がございましたけれども、そういった指摘が無いように教育委員会でも今後対策をとっていくというふうに考えてあります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"隠蔽体質を引きずっていると言われても仕方ないのではないかと思うのですけれども、伺いたいと思います。たまたま発見してしまったもので伺っているのですけれども、重大事態の定義のどこに当たる案件なのか、答えられる範囲で伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"議会への報告につきましては、調査、報告が終了した段階で報告をする予定です。調査結果を踏まえて、議会も含めて、ホームページ上にも公表する形で考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"教育の根本に関わる問題でやっているわけですから、これはいかがなものかと思いますので、それはぜひ改善してほしいと求めました。今後の対策の１つとして、いじめ防止対策推進基本方針の改定を掲げておりますが、改定のポイントはどこなのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"現在の基本方針につきましては、対応できるように、ボリュームを増やすような考えです。そういったものも盛り込むという形で、現在、改定の作業を進めているところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"５.２倍、中学校では１５５人から３６２人、２.３倍ということを紹介しました。これは改善が必要だと思うので伺っているのですけれども、どこにあると分析しておられるのか、率直に伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今ございましたとおり、不登校の児童生徒数は、ここ５年間で急増しております。いろいろ検証を進めなければいけないところですけれども、現状のところ、把握ができておりませんというのが実際のところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"どうですかと伺ったのですが、困難とはどういうことなのでしょうか、伺いたいと思います。困難とはどういう意味なのでしょうか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"例えば学校と家庭の連携事業を推進したりですとか、現在、荏原第五中学校で実施しております校内別室指導支援員の配置等は進めているところです。そうした外部人材も有効に活用して、不登校対策に努めていきたいと考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"さらに支援してほしいという話をしたら、結構もうみんな知っているのですよと、申込みもあったということだったのです。到底思えないのですが、実際何人ぐらい申込みがあったのでしょうか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールの東京都の事業についてですけれども、調査協力金ということで、今年度は２万円の支給がされるというものになっております。令和４年度の実績ですけれども、１６名の申込みがあったところで、フリースクールから案内を行っているというふうにも聞いております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだまだ少ないと思うのです。そこを選べるようになるためにも、ぜひフリースクール等への支援も、品川区としてもぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"令和２年に発生しましたいじめ重大事態に当たるいじめ事案についてお伺いいたします。このいじめ加害者の特定というのは、非常に重要な要素だと思うのですけれども、品川区として、いじめ加害者の特定の重要性のご認識を伺います。","respondent":"丸谷教育総合支援センター長","answer":"いじめの行為の加害生徒、加害児童の特定ですけれども、委員のご指摘のとおり、加害者を特定することによって、反省を促したり、今後の再発防止に努めると、また、被害生徒だけではなくて、加害生徒の心のケアもしていくということで、重要なことだというふうな認識です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"早い段階でカメラの設置を提案されており、被害生徒の保護者の方からもご要望されており、この３者からも要望を受けております。現在、現在、品川区の学校の防犯カメラの設置の状況についてお伺いいたしますとの意見を述べました。","respondent":"森学校施設担当課長","answer":"現在、３１校で１５８台、〔１０月１９日に「８６台」と答弁訂正あり〕屋内に向けてカメラがついている状況。３１校は全体の６７.４％です。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"その屋内というのは、具体的にどこの場所なのか、教室なのか、廊下とかもあるのか、その点をお伺いしたいのと、そのカメラの位置は、生徒たちに認識されてしまっているのか、一目でカメラだと分かるような状況で設置されているのか、そうした設置状況についてもお伺いいたします。","respondent":"森学校施設担当課長","answer":"カメラの位置が児童・生徒に分かるかどうかというところですけれども、恐らく隠しているわけではないので、ある程度は認識されているとは思います。教室内にカメラを設置するというふうには聞いてはございません。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"条件付で、柔軟なカメラの設置、教室内でもカメラの設置をするべきかと考えております。本当に隠しカメラのような感じで生徒に分からないように置くようなものが必要かと思いますけれども、その点、いかがお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"継続されるというときにおいては、保護者、子どもたちの了解を得ながら設置するということは必要な措置かなというふうに考えております。設置には、日頃から常に見守る、見張るというようなことも併せて行うことが大切だと考えております。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"当然、そもそもいじめをしようと思わせないような教育が必要だと思いますので、その点をよろしくお願い申し上げます。学校組織として大丈夫なのかなと不安になってしまいますけれども、この点、今後そうした学校の体制整備とかはいかがお考えなのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"学校の中では、学校いじめ対策委員会がいじめの対応を検討し、実施していくということになっておりますので、こうしたところを徹底的に学校へは指示、指導しながら、組織的な対応ができるように働きかけていきたいと考えております。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"「子育て・教育で選ばれるしながわ」を重点政策の１番上に掲げておりますので、ぜひ生徒、組織づくりをよろしくお願い申し上げます。その点、最後に、いかがお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"区長部局とも連携して、いじめ対策を進めていきたいと思います。","id":"exchange-037"},{"speaker":"せらく委員","kind":"提案","question":"３８５ページ、一般質問でもご提案させていただいた教員の補助要員について、細かいところをお聞きし質問します。この２つの予算執行率、実際の配置実績はどの程度でしょうか、伺いますとの意見を述べました。","respondent":"中谷指導課長、唐澤特別支援教育担当課長","answer":"６０人から７０人程度となっておりまして、総時数が１万５,０００時間超えとなっておりまして、経年変化で見ましても年々ニーズが上がっております。チームティーチングで行っておりますので、同僚性を育むとともに… 私からは、学習支援員、介助員の役割についてご説明申し上げます。予算執行率については、ほかの事業と収まっているところでありますけれども、９０％を超えて高い執行率となっております。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"こちらを拡大できれば、見守り体制がより安心できるものになるのではないかと考えるのですが、いかがでしょうか。併せて、指導助手の年間２９時間という時間数についても考え方を説明するよう求めました。","respondent":"中谷指導課長","answer":"学級数掛ける２９時間を定数としまして、学校の希望等を考慮しまして、指導課で査定して決定しているというものになります。今後、ニーズが上がってきているということ把握しておりますので、学校からの希望をしっかり把握をして事業を進めてまいりたいと考えています。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問・要望","question":"これらの２つと、担任とのコミュニケーションにおいて、そういった情報共有はされていますでしょうか。大人が見守るということを充実していただきたいのですが、サポート役について一般質問でも、今後の方向性を、示すよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"何かクラスの中、児童・生徒の様子を見て気づいたことがありましたら、担任との情報共有は欠かさずに行っているところです。多くの人材を学校に、今、配置されているメンバーをしっかりと情報共有も含めて児童・生徒の支援に役立てていきたいというふうに考えております。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"５年生と７年生で全員面談を行っていると思いますが、その期間は、そういった取組はありますでしょうか。品川区の学校現場でのニーズをどのように考えていますか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"１校当たりの児童・生徒数が２６７人以上の学校には追加配置を希望できて、これは５校で実施をしているところです。１対１の面談ではなくて、困る家庭、お子さんがないように努めているところです。","id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"お問合せがあったときに、なるべくしっかり対応していただきたいと、こちらは要望します。スクールカウンセラー以外にも電話相談なども実施していると思うのですけれども、引き続き、取組を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"実践を重ねていただきたいということを要望いたしますが、区教委のお考えをお聞かせください。公教育で日本人が英語を話すために、現在はどのような課題があるのでしょうか、区のお考えを説明するよう求めました。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"その子にとって話しやすい教員が中心となって、いわゆるグリーフ、悲しみについての心のケアに努めているところです。ＨＥＡＲＴＳをはじめ保健センターとも連携をして、子どものケアに当たっているところです。国は５０％以上ということを求めておるのですが、品川区の子どもたちは約８割に達するなど、着実に力をつけていると考えています。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"万が一、加害者となってしまった子どもたちがいた場合に、どのようなケアをしていますでしょうか。いじめの加害者が特定できたケース、特定できなかったケース、それぞれについて現状を確認したいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"加害者となってしまった子どもたちへの対応ですが、組織的、継続的な指導を行うとしております。補導や非行傾向のあるお子さんについては、警察や少年センターとも連携をしながら、保護者とともに子どものケアについて努めているところです。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"５点目に、教材教具等経費についてお伺いいたします。目的外使用許可の現状と、各学校における基準の有無について、学校現場での現在の状況を確認したいと求めました。","respondent":"宮尾庶務課長","answer":"いただいた指摘の内容、それから原因がどこにあったか、そして今後の対応策等を校長たちと共有をします。考え方に基づいて記載をしておりまして、支援、指導を行っているところです。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問","question":"目的外使用の許可の現状について、簡単に教えていただけますか。","respondent":"宮尾庶務課長","answer":"こちらは、規則には細かく表示はないのですが、各学校、地域との良好な関係づくりに沿ってです。","id":"exchange-046"},{"speaker":"西村委員","kind":"質問・要望","question":"３８９ページ、３９１ページ、自由進路学習についても伺えたらと思います。区のお考えや方向性があれば説明を求めました。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"教育委員会のほうでは、教員研修をはじめ、児童・生徒が円滑に学習のアプリ等を使えるように支援してきたところです。そうしたものを有効に活用しながら、子どもたちの意見交換ですとか、学びを深めているところです。 ２０２５年度のＮｅｘｔＧＩＧＡ構想ですが、それが来ましたら、品川区としての対応を検討してまいります。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"さらなる可能性を、広がりを感じておりますので、お伺いさせていただきました。昨今の状況を伺えたらと思います。","respondent":"丸谷教育総合支援センター長","answer":"本区のタブレット端末ですけれども、家庭でもＷｉ－Ｆｉ環境がなくても使えるような仕様になっておりまして、家に帰っても学習が個々に応じて進められるような配慮をしているということで、他の自治体に比べてもかなり活用は進んでいるというふうな認識です。","id":"exchange-048"},{"speaker":"西村委員","kind":"意見","question":"そういった動画でのフォローでしたり、日頃から２次元コードなどを使って子どもが学習しているのを親としても実感しています。できない先生の課題はいまだ残っていると感じておりますが、どのように対応しておられるのか、課題と今後の取組も併せて説明を求めました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"ＧＩＧＡスクールのＩＣＴの先生たちの対応ですが、基本的には、研修等を実施しています。その苦手な先生の底を上げるために、今、ＩＣＴ支援員等を活用しながら行っているところです。 昨年度、各校の実践事例を集めまして事例集を作成して配布をして活用を広げているところです。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"こういった知見を学校内外でシェアする機会はあるのかということを正に伺おうと思っておりました。３年がたちまして、導入当初と、ＩＣＴ支援員の方々の業務内容がどのように変わってきているのか伺えればと思います。","respondent":"柏木学務課長","answer":"ＩＣＴ支援員の業務内容の変わっているところですけれども、教員と連携しながら、そちらのほうにシフトしている状況です。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"区内の授業状況を伺えればと思います。自由進路学習も全国的に広まっておりますので、自由進路学習について区内で取り入れている事例や、区のお考えがあれば、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"児童間、生徒間でも意見交換をしたり、話合いの場を設けている授業が増えてきております。将来、どのような職業に就いたり、そうした子どもたちの夢や希望というものをしっかり教員が把握しながら推し進めていきたいと思っています。","id":"exchange-051"},{"speaker":"西村委員","kind":"提案","question":"最後に、不登校の課題につきまして、歳入でも提案をさせていただきました。ログインで出席確認ができ、児童生徒の安心安全にもつながると思うのですが、区のお考えを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールに通われているお子さんも出席の扱いにできるよう、学校がしっかりと家庭と連携しながら進めるということが大切だと認識しております。","id":"exchange-052"},{"speaker":"西村委員","kind":"意見","question":"とはいえ、全部学校でやっていくとなると難しいことも現実にあるのではないかとおっしゃっていました。ぜひとも連携を前向きにお考えほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"３８３ページ、３８９ページ、関連をして伺ってまいります。区内のスクールと品川区との連携や関わりについても伺います。","respondent":"柏木学務課長","answer":"次に、区内のインターナショナルスクールと区立の学校との連携等ですが、実績については把握をしてございませんが、多分ないと思われます。インターナショナルスクールの就学の状況ですが、例年３０人から４０人程度がインターナショナルスクールに就学していると把握しています。","id":"exchange-054"},{"speaker":"新妻委員","kind":"確認","question":"先ほど確認をいたしましたインターナショナルスクールの学校法上の位置づけにつきましては、この学校案内にもしっかりと明記されております。どこでご相談をお受けいただいているのか示すよう求めました。","respondent":"柏木学務課長","answer":"まず、インターナショナルスクールの小学部を修了したとしても、小学校の教育課程を修了していないので中学校には入ることができない。それらの相談の先ですが、教育委員会の学務課が就学を担っておりますので、学務課でお受けしております。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"そしてまた、この原因がなかなか把握し切れない、そのような現状があるということも確認いたしました。この国がまとめたアンケートが、どのように品川区に生かされてくるのか、このアンケートについて少しお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今回、不登校を対象にアンケートを国が行うということですけれども、そちらの結果が示されたところで、本区と、大きく増加の理由等は変わらないと思いますので、そうしたものをしっかりと把握しながら、今後の施策に生かしてまいりたいと考えております。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"児童のお子さんからの要望で、不登校でのＺｏｏｍ対応はできないという、そういう残念な回答があったと伺いました。この学校についての対応がどうなったのか、しっかりと進めてほしいと求めましたが、見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"オンラインでの授業参加につきましては、特段コロナ禍だからやったものではございません。不登校児童・生徒が、今ご指摘いただいたことが全ての学校でないように、しっかりと対応するように学校への指導を進めていきたいと考えております。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"３８９ページの英語教育と、３８１ページ、３７３ページのクラブ・部活動についてお伺いいたします。最初に、品川区としては、どういった人物を育成したいのか、教育の方針や目標などを説明するよう求めました。","respondent":"中谷指導課長","answer":"品川教育ルネサンスを未来を切り拓く子どもの育成ということで、子どもたちが粘り強く生き抜く力を養えるようにということで推進しています。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"粘り強くということで、本当に今後さらなる検討を重ねて、いろいろやっていってほしいと求めました。後半のほうが７年生から９年生の学習かなと思われますが、７年生から９年生のグローバル人材育成塾、こちらの対象や内容を説明するよう求めました。","respondent":"中谷指導課長","answer":"３年生からの外国語活動が主流になっておりますが、品川区としましては、１年生から英語科を実施しているというところが特徴になっております。非常に出席率、参加率が高い生徒に対して、イングリッシュキャンプを福島県のほうで実施させていただいているという状況です。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"１点、今、生徒の中では何割ぐらいの生徒が希望して参加していますでしょうか。こういった様々な事業は、品川区教育委員会が独自で企画しているのか、または民間の業者に委託しているのかも説明を求めました。","respondent":"中谷指導課長","answer":"今、同じ方が継続しているケースもあれば、新たに申込みをされるようなケースもあるかなというふうに思っております。こちらにつきましては、民間に対して委託という形で実施しています。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"意見","question":"海外の友達と文通しようとか、そういった企画しかありませんでしたので、今の子どもたちは本当に英語が身近になっているなと感じます。一方で、日本の文化や歴史についての学習はどのようなことを行っているのか、説明を求めました。","respondent":"中谷指導課長","answer":"日本で昔から育まれてきたことのすばらしさや、他国の文化に触れたときの気づきを促したり、理解を深めることにもつながっていると考えております。異文化を理解しようとする意欲の醸成によって、相互理解を深めていくということが目指していくところになります。","id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"最後に、クラブ・部活動等経費についてお伺いします。３７５ページ、どういった方で、現状を説明するよう求めました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"クラブの外部の指導員ですが、すみません、どういう方かというところまでは、すぐは分からないのですけれども、年度途中でありますが、今年度の状況でいきますと、約１００人ほど雇用をしている状況です。 部活動指導員も配置をしております。","id":"exchange-062"},{"speaker":"ひがし委員","kind":"確認","question":"品川区でも不登校児童が増えているということ、そして、特に小学生児童の不登校が増加しているとの答弁を確認することができました。そこで、お伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールですけれども、こちらは区教育委員会が設置している適応指導教室となりまして、区内に３か所あります。連携が求められているものであり、なかなか学校も把握できていない部分もありますので、今後広げていきたいと考えております。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"一方で、現在、品川区のマイスクールでは、１年生からを対象にしたものがありません。今まで小学校１年生、２年生を対象にしていなかった理由、お考えを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"５年前までは、二年生の不登校の児童の数は１０人にも満たないということで、かなり低い数字でございました。昨年度は２０名を超えておりますので、そういった意味で、今後、必要な取組かなというふうに考えております。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ１年生からも対応できるマイスクールの整備、不登校児童が増えているということを含めまして、拡大も前向きに検討いただけるように要望をします。１年生から対応できるマイスクールの整備、現在、検討している状況があれば説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールだけではなくて、例えば、学校の中に居場所をつくるというような取組も広げていきたいというふうに考えております。ガイドブックの作成を検討しておりまして、また、ホームページの充実ということで保護者への周知も図っていきたいと考えております。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問","question":"続いて、市民科・各教科充実経費に関連して、性教育についてお伺いいたします。品川区として、この包括的性教育、生命の安全教育についての必要性について、どのようにお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"生命の安全教育についてですけれども、本年度より全校で教育課程に位置づけをして全学年で実施をしております。理科や市民科の中で、生命、性に関連づけた教育は進めているところです。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"品川区公立校の中で、外部講師を招いての授業をしている学校はあるのでしょうか。もし行われている場合は、実施した際の生徒、保護者、教員などから反応はどのようなものだったのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"例えば浜川中学校で、今年の７月に９年生を対象に「ライフスキル講座」という名称で、産婦人科医を呼んだ講演会を行っております。保護者、教員からも、なかなか自分たちで教えられないことを教えてくれた大変よい取組であるというふうに評価をいただいております。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ進めていただきたいのですが、教えるために考慮するべきことが多く、現場のハードルが高いとの声もあります。がん教育推進事業のように、予算化も検討してほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今回、１校が行っておりますけれども、学校のニーズに応じた取組支援ができるように努めてまいりたいと考えております。","id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"意見","question":"会計年度任用職員が７５名ということで、大体１対９の割合で会計年度任用職員がいるということで、非常に多いと思います。非常に大事なポジションである会計年度任用職員、３年で雇い止めになってしまうような状況に今なっているのか、その辺のご認識をお願いしますとの意見を述べました。","respondent":"中谷指導課長","answer":"この２４５名の内訳としましては、区役所だけではなく、学校というところも含めてお考えいただければというふうに思っております。単年度でという契約になっておりますが、そういった意味では、今の品川の学校を非常に助けていただいているというふうに考えております。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"よく学校のことも分かっていらっしゃる方も多いと。一覧を確認させていただいたのですけれども、私の手元にあるのは令和５年度の募集要項なのですけれども、その辺の受け止めはいかがか尋ねました。","respondent":"宮尾庶務課長","answer":"教育委員会全体の会計年度任用職員に関わることですので、私のほうからお答えをさせていただきたいと思います。当然ながら、例えば物価高等の状況が変わりましたら、その状況に応じて、当然に見直しはされるべきだというふうに思っております。","id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３８１ページの市民科なのですけれども、先ほど、ほかの委員、ひがし委員とかも質問がありました性教育に関してです。学校のニーズではないと思うので、ぜひそういったことは積極的に取り組んでいただきたいというふうに思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"外部講師によって、より深く学べる機会を得るということで、浜川中の取組を紹介した次第です。全校で取り組んでいることは取り組んでいるのですけれども、外部講師を呼ぶというニーズには応えていきたいという趣旨での答弁でございました。","id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私からの提案なのですけれども、外部に任せてというようなことをすると、ぜひ前向きに検討していただきたいという要望で終わります。３７９ページのルネサンス推進事業なのですけれども、義務教育、公立だけに限ったことなのか尋ねました。","respondent":"中谷指導課長","answer":"一貫教育ということで、こちらに掲げさせていただいておるのは、品川区の公立の学校の９年間の教育をどう充実させていくかというものになってあります。","id":"exchange-072"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。品川区としてどういった対応をとられたりとか、窓口は、相談体制はどのようになっていますか尋ねました。","respondent":"柏木学務課長","answer":"学校ですけれども、品川区が所管するのは、品川区が設置者になっております品川区立学校となります。それ以外の私立等については、基本は運営する学校法人または東京都になります。","id":"exchange-073"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ何か区としてできるようなこととか、相談体制とかがあるといいなというふうに思ったのですけれども、そういったことはいかがでしょうか。何か進めていったりとかということは。","respondent":"柏木学務課長","answer":"保護者、生徒から、品川区立の学校に関わってとか、本人の相談というのは受けられるのですが、私立の学校自体に品川区教育委員会では指導する権限等がございませんので、そういうものは受けられないということになります。","id":"exchange-074"},{"speaker":"こしば委員","kind":"質問・要望","question":"３８１ページ、３７７ページ、人権尊重教育推進経費に関連した「Peace of Cake」を使った平和教育についてお伺いいたします。初めに、３８３ページ、英語科経費、推進経費についてお伺いいたします。","respondent":"中谷指導課長","answer":"指導されている外国人の方についてのご質問かと思います。その方とチームティーチングということで、お二方で１つの英語の授業を教えるというようなスタイルになっております。","id":"exchange-075"},{"speaker":"こしば委員","kind":"質問","question":"このＡＬＴの先生なのですけれども、これまでは委託であったということですが、今回、令和４年度から人材派遣に変更になったと聞いています。その辺り、どのような経緯で委託から人材派遣に変わられたのか、教えてほしいと求めました。","respondent":"中谷指導課長","answer":"見守るというような直接的な指導をしたりですとか、授業プラスアルファの部分で様々な支援をいただけるようになったというところが一番大きなメリットとしてございまして、現在もそのようなところで非常によかったというような学校からのお声もいただいているところです。","id":"exchange-076"},{"speaker":"こしば委員","kind":"質問","question":"この英語力の評価というところで、この３０年間で、日本人生徒の語学力が相当向上しているといった話があったとお聞きいたしました。４年生、中身についてはお聞きしませんが、評価について教えてほしいと求めました。","respondent":"中谷指導課長","answer":"４年生でやっておるものがジュニア・イングリッシュキャンプ、自校での実施ということもやっておりまして、２つでやっております。様々なオンラインも含めて提供していますので、お子さんの希望に沿って提供できるような事業を進めていきたいというふうに考えております。","id":"exchange-077"},{"speaker":"こしば委員","kind":"質問・要望","question":"こういう将来の未来像を描く選択肢を与えてくれる事業の中に、ぜひ英語を主にした事業をたくさん展開してほしいと求めました。それが英語力の向上、英語を学ぶというモチベーションの向上にもつながると考えますが、品川区のお考えについてお聞かせほしいと求めました。","respondent":"中谷指導課長","answer":"やはり自分の将来の姿を考える時期が来ますけれども、職業を通じて自己実現をどう図っていくかを考える機会につながっていると考えております。","id":"exchange-078"},{"speaker":"こしば委員","kind":"質問・要望","question":"次に、市民科・各教科充実経費に関連しまして、日本人の母国語となる国語教育についてお聞きしたいと思います。まず、この品川区のオリジナルの教材「ことのはノート」について、簡単に教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"我々教育委員会で「漢字ステージ１００」という教材を作って配布していたわけですけれども、「ことのはノート」というものを作成いたしました。１年生から６年生までは各１冊ずつ、７年生から９年生で１冊という形で、各児童・生徒に配布をしているものです。","id":"exchange-079"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、なかなか文字数の限られた情報では、どうしても一定の読解力がないと、なかなか正確に読み取ることができない。それを国語教育の中で結びつけていることがあるとすれば、どういったものなのか、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"それを受け取った児童・生徒が、どのように読み解くのかということで、発信力、読解力ともに必要なものだというふうに考えております。区立学校では、「ＳＮＳ東京ノート」というものも活用しながら、情報リテラシーの充実向上を図っているものです。","id":"exchange-080"},{"speaker":"こしば委員","kind":"質問・要望","question":"そして読解力をぜひ向上していただきたいとお願いをしまして、３７７ページ、平和に関する指導についてお伺いいたします。これについて少し教えていただきたいのと、今後の平和教育の在り方について、お気持ちをお聞かせ願いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"毎年、区立学校の８年生を広島に派遣させていただいて、それを校内で還元するという事業を進めております。そういったものを活用しながら、各校での取組を充実させていきたいと考えております。","id":"exchange-081"},{"speaker":"つる委員","kind":"質問・要望","question":"３７５ページ、就学支援費、３９５ページ、給食運営費、３８７ページ、図書館運営費、３９１ページ、学校図書館経費について伺っていきます。そうしたところで、夏休みの食事がどうだったのかというところも少し気になるところでありますが、この辺についてご見解を示すよう求めました。","respondent":"柏木学務課長","answer":"今年度から無償化に伴って、夏休みの子どもたちの食事の件ですが、特に教育委員会として把握しているところではございませんが、学校から何か子どもたちに異常があるとか、気になるところがあるという声は、特には寄せられてございません。","id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"答弁等を確認すると、どういった方をと、こういう視点でぜひお願いしたいと思います。品川区が求める人材像、そうした視点の質問もありましたけれども、その辺りもお願いしたいと思います。","respondent":"吉田品川図書館長","answer":"そういうものを使いまして、お声かけをするなり、お持ち帰りの際に不便にならないような対応をしているということは聞いているところです。こちらについては、先方を含めまして研究させていただければと思います。","id":"exchange-083"},{"speaker":"つる委員","kind":"提案","question":"私も今まで様々な決算特別委員会の提案をさせていただきました。結果が出るまでは頑張っていきたいと思いますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"石田（し）委員","kind":"質問","question":"そして３７９ページ、３７９ページ、それぞれ質問していきます。そういった様々な不用額があると思いますが、令和４年度ではどのくらい総額があったのか、大体で構いませんので説明を求めました。","respondent":"中谷指導課長、丸谷教育総合支援センター長、大串会計管理者","answer":"ご一緒の机で座らせていただいておりますが、区の職員の方とは異なる職に当たっているというところを申し上げさせていただきたいと思います。… 不登校についてのお尋ねです。それが全てではないというふうな捉えで、是とも非とも言い難いところはあるのですけれども… 教育費における不用額、こちらにつきましては９億２,７２９万８,２８０円という形です。","id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜ質問をしたか、やはりこういった今の時代に合わないような法律は改正をするべきだということを強く訴えていただきたいなというふうに思います。その失われた３年間を、何らかの形で取り戻していただきたいなと思いますが、その辺のご見解を説明するよう求めました。","respondent":"丸谷教育総合支援センター長、森学校施設担当課長、米田教育次長","answer":"不登校の児童・生徒への根本的な考え方というところですけれども、最終的には、義務教育９年間を終えた子どもたちがどう社会に羽ばたいていくか。… 不用額の大きなところは、学校の整備関係でかなり不用額が大きくなっております。契約落差であったりとか、大きいのは、国有地の購入についての半額ぐらい… 例えば、移動教室などで、次年度に繰越しができるという内容については、翌年度１年遅れましたが実施したりというようなことになっております。","id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。このジェネレーションギャップをどうやって埋めて、これはまた別の機会でやりたいと思いますが、ぜひ心の準備だけしておいてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３９１ページの学校図書館経費に関わって、図書館司書の配置拡充を求めて質問をします。なぜこの学校図書館司書の配置を増やさなかったのでしょうか、伺います。","respondent":"吉田品川図書館長","answer":"図書館といたしましては、学校司書の拡大について前向きに検討してきたところです。そのように進めてきたところですが、所管の考え方が所管としてありまして、また、予算となりますと、全体の中で調整をする形になると思います。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"図書館としては検討してきたけれども、予算上、無理だったということだと思いますが、予算上無理だと判断をした理由を伺いたいと思います。","respondent":"吉田品川図書館長","answer":"所管の思いだけで動いているわけではございませんので、全体の中で必要なところに必要な額というところで、全体を調整された結果としての数値がこのようなものというふうに所管として受け止めているところです。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ図書館司書の配置を増やさなかったのかということを伺いたいと思います。やはり国も図書館の活用ですとか、教育環境の整備が遅れてしまったと思いますが、いかがか尋ねました。","respondent":"遠藤財政課長","answer":"いろいろな形でぜひやりたいという形でいただいているのですけれども、予算上の制約などもあり、今回については見送ったです。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこで拡充をしていくということがやはり求められていたと思いますけれども、そこをなぜ重視しなかったのか伺いたいと思います。それと、教育環境の整備が遅れてしまったのではないかという質問もしたので、お答えほしいと求めました。","respondent":"吉田品川図書館長","answer":"予算については、所管としては、折りを見て、必要な時期にまた事業の拡張について考えているところです。時間数としては、２３区の中で大体中真ん中辺のところの位置を占めておりますので、著しく遅れたというふうには認識しておりません。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問","question":"ぜひ財政課からも改めて、なぜ重視をしなかったのかというところを伺いたいと思います。区としては、これを重要だと考えていないのか、伺います。","respondent":"遠藤財政課長、吉田品川図書館長","answer":"大事な事業ということは理解させていただいているところですけれども、やはり先ほど言いました、どうしても予算には限りがありますので、どうしても取捨選別しなければいけない部分がありますので、ご理解いただければと思います。 区として重視しなかったのかというところなのですけれども、先ほども申し上げましたけれども、２３区の中で真ん中辺の図書館司書の確保をしています。そういう部分もありまして、重要と考えていないわけではございません。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした状況を区は把握をしているのか、ぜひ教育環境が確保できるようにしていただきたい。今の状況では確保できていないというふうに思いますけれども、いかがか尋ねました。","respondent":"吉田品川図書館長、丸谷教育総合支援センター長","answer":"それを含めまして、全体、必要なところと、足りていないところもあるとは思います。ただ、現在は、できるところで頑張っているです。朝読書の時間、昼休みの時間に図書の貸出しを行うなど、そうしたことで読書の推進を図っているところです。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"学校のほうからも図書の時間を増やしてほしいという声もあるということですので、そうした声も生かしてやってほしいと思いますし、一時期。週５日、毎日学校図書館司書を配置することが子どもたちの学習をよりよいものにすると思いますが、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"学校司書は確かに２.５日配備ですけれども、それ以外の日は図書館が開いていないということではございません。それから図書委員等で、図書館が開いていないということにつきまして、図書館を開けていないというふうには思っておりません。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"お昼休みとかは開いているということですか。子どもたちの学習をよりよいものにすると思いますが、いかがでしょうかということも伺ったので、お答えほしいと求めました。","respondent":"吉田品川図書館長","answer":"品川図書館で研修などをすることによりまして、司書までにいかないかもしれませんけれども、一定程度のサポートはしています。地域、それから学校の図書委員等を含めまして、みんなで学校図書館を盛り上げていければと考えています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"５日はぜひ、毎日いるような形で司書配置をしていただきたいと、これは求めておきたいと思います。ぜひそうしたことを強めていっていただきたいと思うのですが、現在、図書館司書は、職員会議に参加しているのか、伺います。","respondent":"吉田品川図書館長","answer":"現在の図書館司書が職員会議等に参加しているかという件についてのお答えですけれども、今回、そのところは行っていないところです。職員会議等でもし必要であれば、委託の事業者の長、責任者に話していただいて、それが社員のほうに話が伝達される形になります。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすることで、先ほどありました職員会議にも参加でき、子どもたちと接する機会も増えてくると思います。区が図書館司書を直接雇用して図書環境の充実を図ってほしいと求めましたが、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"休暇とかが起こった場合、代替の職員を確保することが、急にはかなり困難な形です。そういう中では、一定レベルの知識、技術を持った専門業者に委託したほうが安定的運用が図れると考えて、現在の形をとっているところです。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもたちのために充実をさせていくというところで進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"田中委員","kind":"質問","question":"ページで言いますと、３７９ページのいじめ防止対策費、それとルネサンス推進事業に関しましてお伺いいたします。やはり自らの問題として取り上げていくべきだと思いますし、これまでの経緯に対しましての教育委員会としての受け止めをぜひお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"令和２年に起こったいじめに対する、今回、ホームページへ調査報告の結果を掲示するということをもともとは考えておりました。今回、そういったことも踏まえまして、記者会見の場をお借りして我々のほうからも説明をしたという流れです。","id":"exchange-099"},{"speaker":"田中委員","kind":"質問・要望","question":"記者会見は、もちろんあれなのですけれども、そこから先の自己解決能力がどこまで発揮されたのかというところに、私は他人事、他人任せのような、要は、区長任せのようにしか感じとれないのですけれども、そこら辺の受け止め、ぜひ教育長からもお聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"基本方針の改定でありますとか、教育委員会事務局内で改めて法律に基づいたいじめの認識を行うこと、我々の中でもしっかり行うということで認識を改めたところです。","id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、毎年のように１３０人から１５０人、どうだったかということをぜひヒアリングをしてほしいと求めました。もう時間がありませんので終わりますが、今後、私も質問に対応していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問","question":"３７７ページ、３９３ページ、この３点をお伺いしたいと思います。今後この事業については、どのようにお考えなのか、方向性を説明するよう求めました。","respondent":"柏木学務課長","answer":"ここ三、四年で、小学校ですと２０万円ぐらい増えているという国の調査もあります。そういうことを鑑みますと、就学援助に関わらず、保護者が負担する金額については減らす必要があると考えています。","id":"exchange-102"},{"speaker":"こんの委員","kind":"質問・要望","question":"今年の３月の予算特別委員会でもこのことは取り上げさせていただいて、工夫をしてはどうですかという、こうした質問をさせていただきました。ご家庭の学納金の納め方の状況をお聞きしたいのですけれども、学納金の支払いが滞ってしまうようなご家庭はあるのか尋ねました。","respondent":"柏木学務課長","answer":"ただ、教育委員会のほうでは、滞納の人数等は把握してございません。滞納が続くような方については、就学援助は随時受けておりますので、そこで学務課のほうにご相談いただくというようなことをとってあります。","id":"exchange-103"},{"speaker":"こんの委員","kind":"意見","question":"ご相談をいただいても、そこで本当に認定されるのかどうか、少しそこが懸念されるところです。私費による教材・教具のこの点について援助するなど、負担軽減策を検討してはどうかと思いますが、ご見解を説明するよう求めました。","respondent":"柏木学務課長","answer":"前回、予算特別委員会でご質問をいただいておりまして、今年度、全校を対象に、保護者が購入しています、教材等の調査を全校に行いました。その調査等を参考に、今後、保護者の負担を軽減する策等について検討をしてまいります。","id":"exchange-104"},{"speaker":"こんの委員","kind":"質問","question":"こうした状況について、区の教育委員会としては、どのようにこの現状を捉えていらっしゃいますでしょうか。品川区の教育現場の実態についてお伺いしたいと思います。","respondent":"中谷指導課長","answer":"小学校では１３名、中学校では６名、計１９名が不足しているという状況があります。ご指摘いただいた管理職の先生がこの対応に大変お忙しくなるという状況は把握しておりまして、そういったタイミングで随時できるようにということで。","id":"exchange-105"},{"speaker":"こんの委員","kind":"質問・要望","question":"ここをぜひ区教委のほうでサポートができる体制をとられたらいかがでしょうか。どうか区教委のほうでも、こうした体制をとる支援を検討していただきたいのですが、いかがか尋ねました。","respondent":"中谷指導課長","answer":"今は名簿だけではない詳しい情報を入れたサイトというか、データバンクを持っておりまして、これを使い始めているところです。１つだけの方法に頼らない方法ということで、こちらも組み合わせたりということでやってまいりたいと思います。","id":"exchange-106"},{"speaker":"こんの委員","kind":"質問","question":"直接校長先生、この分野だけでも、区教委で探してさしあげるぐらいまでの体制がとれたらというところです。その点をいま一度お願いしたいと思いますけれども、いかがか尋ねました。","respondent":"中谷指導課長","answer":"そのような中で、副校長補佐という事業を少しずつ今導入しております。調査への回答ですとか、もう１人の方にプラスアルファで入っていただいて、こういったものの拡大ということも検討してまいりたいと思います。","id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校選択制によって通学路は範囲が広いですので、この台数で十分なのでしょうかというのが１つです。ここ３年間で少しずつ微増という照会の協力をしているようですけれども、子どもたちの防犯という観点から、現状どのように捉えていますか尋ねました。","respondent":"森学校施設担当課長","answer":"防犯カメラのご質問ですけれども、委員ご案内のとおり、各校２台から５台程度、全部で２１２台設置しています。即対応するような考えでおりますが、違う方法で対応をとっているところですけれども、答申が出れば対応していきたい。","id":"exchange-108"},{"speaker":"こんの委員","kind":"意見","question":"答申が出たところは対応してくださるということですけれども、いわゆる照会の事案等もありますので、そうしたところには防犯カメラがあっての事案の照会ですけれども、そうした事案を見て、積極的に設置をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１つ言うと、今、変化が激しい時代だからこそ、教員に求められるのは資質能力を確実に身につけること、これが重要だということで言われています。ここら辺のところを改めて教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"１０年目であっても、２０年目であっても、授業力を身につける。保護者への対応についてですけれども、対応がうまくいかないときには、フォローの体制をしっかり整えているところです。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問","question":"学校にいるのは１日７時間ぐらいであって、いろいろなところ、もちろん家庭なのだよ。それぐらいまでしっかり言い切ったほうがいいような気がしてならなくて、改めて、もう一度そこら辺を説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"指導主事のほうで把握した内容について、何かこれは大きな問題に発展しそうであるとか、なかなか保護者との関係がうまく構築できない。４月の入学時、併せて、それぞれの学校が同じ温度でできるように周知をしていきたいというふうに考えます。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"もう１点、これはどうしてもやりたかったので、３８９ページ、部活動支援みたいな形なのだけれども、先日、大相撲の巡業がありました。ここら辺のところ、最後、それだけ聞きたいとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"教員、それから子どもたちが挨拶をするというのは非常に大切だというふうに思います。目配せ、アイコンタクトも非常に大切だと思いますので、そうしたことも充実というか、学校が取り組めるようにしたいと思います。","id":"exchange-112"},{"speaker":"まつざわ委員","kind":"質問","question":"我々大人が見てもそう感じるものですから、子どもたちの心境は計り知れないと思います。教育委員会として、近年増えつつあるネガティブニュースの課題をどう捉えているのか、示すよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"子どもに関する事故、戦争などが起こったりしたときなど、児童・生徒の心に大きな影響を起こすおそれがあるというふうに認識しております。つらい思いをする視聴者への配慮も必要であるというふうに捉えております。","id":"exchange-113"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"国は、４月以降、学校の授業などで、基本的にマスク着用を求めないとする通知を各地の教育委員会に出しました。やはり常にポケットにマスクを隠しているというのですか、忍ばせている子ども、「どうして？","respondent":"丸谷教育総合支援センター長","answer":"学校教育を進めておりまして、こうしたつらい３年間ではありましたけれども、そういった期間だったのではないかというふうに考えております。なかなか子どもたちとの対話もできなかった３年間ではありましたので、学校教育を進められるというふうに考えております。","id":"exchange-114"},{"speaker":"まつざわ委員","kind":"質問","question":"ぜひ子どもたちの、一般質問でもさせていただきました。改めまして、教育委員会が考えることとは何でしょうか、示すよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"そのためには、我々大人、教員も、より柔軟な考え方を持つなど、児童・生徒の見本になることが大切だと考えます。教育委員会として、不易を大切にしながら、流行にも柔軟に対応できるよう、市民科等の学習活動の中で実践できればというふうに考えております。","id":"exchange-115"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ソーシャルスキルの教育、ピアサポート活動、レジリエンス教育、大体この３つを柱にして福井県ではやっています。ぜひ品川教育ルネサンスの中にも、このポジティブ教育を推進してほしいと求めましたが、ご見解をお願いします。","respondent":"中谷指導課長","answer":"品川教育ルネサンスが掲げている困難に負けず生き抜く児童・生徒、未来を切り拓く力を持つ子どもの育成につながるものであると認識しています。","id":"exchange-116"},{"speaker":"木村委員","kind":"質問・要望","question":"３７３ページの教職員福利厚生費から、家庭教育学級、家庭教育力向上支援についてお伺いいたします。それぞれの事業の概要について教えてほしいと求めました。","respondent":"宮尾庶務課長","answer":"ひいては学校教育の円滑な実施、健康診断、それからストレスチェックなどを行ったものです。講習会の開催、それから産業医による健康相談や面接指導、こういったものを行いました。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問・要望","question":"やはり子どもたちは品川区の、いや、日本の宝物だと私たちは思っています。大事に見守っていただきたいが、子どもたちに対してのお考え、何かアイデアがあればお聞かせほしいと求めました。","respondent":"宮尾庶務課長","answer":"委員おっしゃるように、学校で、正に子どもたちと、児童・生徒たちと最前線で向き合っていただいているのは先生方です。様々な福利厚生の対策、こういったことも充実させていって、先生方をこのような側面から支えて支援してまいりたいというふうに思っております。","id":"exchange-118"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、今言われた教職員の皆さんの健康を守るためにも、健康診断の受診状況と、ストレスチェックの概要、実施状況についても教えてほしいと求めました。","respondent":"宮尾庶務課長","answer":"それから週２０時間以上勤務をしている会計年度任用職員の方で、それらの方々にストレスに関する質問書を送って回答していただいております。回答に係る教職員の皆様の負担を軽減するために、これに加えまして、ウェブ上でも回答できるようにしたところです。","id":"exchange-119"},{"speaker":"木村委員","kind":"意見","question":"子どもたちにはどのような影響を与えているのか、与えているというのは失礼かもしれませんが、あるのか。そういうことがあれば説明を求めました。","respondent":"宮尾庶務課長","answer":"申込みのなかった方につきましても、別途、こちらのほうから連絡をさせていただいて、面接を受けていただくように勧奨をしています。本人のご希望により、産業医と対面形式に加えまして、オンライン形式でも対応できるようにということで選択肢を拡充しています。","id":"exchange-120"},{"speaker":"木村委員","kind":"質問・要望","question":"健康診断の受診率が高い数値になっておりますけれども、何か工夫をされたようなことはあるのでしょうか。これがあれば、お聞かせほしいと求めました。","respondent":"宮尾庶務課長","answer":"健康診断の受診率につきましては、対象者となっている先生方が受診しやすいように、まず実施時期を学校の夏季休業期間を中心に設定しております。こうしたことが、結果として高い受診率につながっているのではないかというふうに考えてあります。","id":"exchange-121"},{"speaker":"木村委員","kind":"質問・要望","question":"昨今、働き方の健康管理については、より一層の強化が求められていると思います。これからストレス、教職員の方々に対して、何か取り組んでいることがあればお聞かせほしいと求めました。","respondent":"宮尾庶務課長","answer":"令和４年、昨年の４月から、それを基に校長への情報提供を行っております。ご本人の負担を軽減するという目的で、希望によりまして、対面プラスオンラインでもできるようなやり方に改めているところです。","id":"exchange-122"},{"speaker":"木村委員","kind":"質問・要望","question":"引き続き、ＰＴＡ関係費から、ＰＴＡ活動支援、家庭教育学級、家庭教育力向上支援についてお聞きいたします。それぞれの事業の概要について、簡単にご説明を願います。","respondent":"宮尾庶務課長","answer":"ＰＴＡの活動支援についてですが、研究発表会、こういった事業をＰＴＡの連合会に委託をして実施をしているものです。保護者の方々が自らの子育てについて考えていただき、講演会、こういったものを実施しています。","id":"exchange-123"},{"speaker":"木村委員","kind":"質問・要望","question":"時間がありませんので、ぜひとも未来の大人たちのために、皆さんの力を十二分に発揮できるように頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"３７９ページのいじめ防止対策費についてお伺いします。教育委員会ですか、区長部局ですか、答えるよう求めました。","respondent":"勝亦総務課長","answer":"区長部局におきますいじめ調査委員会の結論につきましては、調査結果がまとまりました段階で、事務局立会いの下、委員長より保護者の方に概要を説明した上で、最終的に報告書をまとめてあります。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ですから、納得されたのですかということです。どうか尋ねました。","respondent":"勝亦総務課長","answer":"こちらの内容につきましては、内容、それから公表につきましても、ご了解をいただいております。今、最終的に加害者が見つけられなかったこと、そういった解決ができなかったことについては残念だというコメントはいただいております。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"自分の子どもが学校に行けなくなってしまった、パニック障害になってしまった、どうしてくれるのだというのは当たり前ではないですか。どういう役割分担をされるつもりか尋ねました。","respondent":"丸谷教育総合支援センター長、勝亦総務課長","answer":"品川区いじめ対策委員会の役割ですけれども、区の教育委員会のいじめ対策の施策の推進に当たるための会議体です。重大事態が発生したときに、調査、報告に当たる機関というふうになっております。 期間を設けて調査を行う等の方法によりという、こういった法律の中の記載に基づいて実施しているもので、そういった役割分担になっております。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"なぜこの２つの機関があるのですか。なぜ常設するのか尋ねました。","respondent":"勝亦総務課長","answer":"いじめの調査委員会につきましては、もともとこの法律に基づいて必要なときに開催できるように条例を定めてあります。常設で委員会を設けるという趣旨での補正予算の要求ではございません。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問","question":"それから、いじめ情報収集促進チラシの配布、積極的な情報収集と早期発見、これ、ＨＥＡＲＴＳとか教育委員会とかでやっていることではないのですか。これ、なぜ区長部局のいじめ調査委員会がやることなのか尋ねました。","respondent":"勝亦総務課長","answer":"専門相談員、こちらは常設で、こちらは区長部局に相談受付体制を設置するという形で常設いたします。いじめを受けている方、そういった現場に入って支援を行う、そういったものを第三者的に客観的に行っていくというための機関です。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"充実させるという形に、私は税金を使ってもらいたいと思うし、子どもたち、それから親たちも、そのほうが迷わずに相談ができるのではないでしょうか。いかがか尋ねました。","respondent":"勝亦総務課長、丸谷教育総合支援センター長","answer":"教育委員会のほうでも、様々ないじめですとか、相談の窓口を設置しています。いじめを見た方、そういった方からもいじめを積極的に情報するという意味で間口を広くとるという形での窓口の設置になりまして、より区民の方に。 ご指摘いただきました教育委員会内部の支援につきましても充実させるように、次年度に向けて計画を進めているところです。","id":"exchange-130"},{"speaker":"西本委員","kind":"質問","question":"それがなぜ区長部局が出てくるのですか。なので、教育委員会でもっと自信を持って、いじめ対策に対してはしっかりやっていくということを意思表示をしていただくよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会で行えること、教育的なアプローチは、我々得意とするところですけれども、我々だけではなし得ない行政的なアプローチも必要だというふうに考えまして、連携を進めていきたいと思います。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、今月１１日には、初めて公募されました教育委員がご就任されまして、そういったことも含めて、少し確認をさせてほしいと求めました。いわゆる５人の教育委員会と、また、教育長及び教育委員会事務局のチェックを行うことというふうに文科省から求められているところです。","respondent":"宮尾庶務課長","answer":"教育委員会の体制ですが、委員お話のとおり、教育長を筆頭に、４人から成る教育委員から成り立っているところです。一定程度、独立した教育委員会としての職務権限、こちらを教育長の下に事務を執行しています。","id":"exchange-132"},{"speaker":"若林委員","kind":"質問・要望","question":"ここに区長部局からの方が一緒に参加するということは可能なのかどうか、こういったところも教えてほしいと求めました。今後こういったけが、事故が起こらないための今後の対応を確認します。","respondent":"宮尾庶務課長、森学校施設担当課長","answer":"コロナ前は大体１泊で行っていた行程を日帰りという形にいたしまして、これもコロナの感染拡大予防という観点から行ったという経緯があります。相談なり、お声があれば… それ以外に、コンクリートの塊等が２か所から出てまいりました。基本的に第２校庭はあまり使っておりませんので、今週中に土をさらってきれいにするという作業を行う予定で、即対応するようにしております。","id":"exchange-133"},{"speaker":"若林委員","kind":"質問・要望","question":"大変な作業なのですが、ぜひ教育委員会におかれましても、報告書を作成して、区民、議会と、ぜひ成果を共有させていただきたい。区長部局との連携という意味では、そういった観点でも進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"３８１ページの市民科になるのでしょうか、性教育ですが、東京都のほうで性教育に関する講師の補助があると伺っています。これはモデルで５校で、今年１５校、まず来年度、どのような計画か尋ねました。","respondent":"丸谷教育総合支援センター長、唐澤特別支援教育担当課長","answer":"令和６年度の都立高校の入試の男女枠の撤廃についての対応ですけれども、先日、進路指導主任会でも区教委から説明を行ったところです。こういったものも、今後、必要に応じて活用してまいりたいと考えます。 今後、その成果を踏まえながら、次年度については検討していければと考えています。特別支援教室の１年原則ですけれども、そのような形で考えながら、また発達障害教育支援についても検討していければと考えています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、来年度は、今年１５ですから、相当数増やす予定ではないかと思います。品川区としては、令和６年度に向けて、どのような構想を考えていらっしゃるか尋ねました。","respondent":"丸谷教育総合支援センター長、唐澤特別支援教育担当課長","answer":"そうしたことも踏まえまして、進路指導、都立校にするのか、私立校にするのか、そういったことを丁寧に説明と指導をしていくです。性教育の周知についてですけれども、こちらのほうも教育委員会でしっかり把握をいたしまして… 発達障害教育支援員について、令和４年度５校は会計年度任用職員、令和５年度１０校は派遣というような形で実施しております。そうした形態の成果なども踏まえながら、次年度以降、拡充に向けて検討していきたいと考えております。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけ、学習支援員や介助員の予算立ては減らさないでいただきたいというふうにお話ししたのですが、その点についてはいかがでしょうか。１つだけ、保護者や児童に知らせるということが効果的であると思うのですが、その点についてはいかがか尋ねました。","respondent":"唐澤特別支援教育担当課長、丸谷教育総合支援センター長","answer":"発達障害教育支援員、学習支援員、介助員を含めまして、その在り方、対象となる児童・生徒もおりますので、そうしたものも整理しながら次年度に向けて検討していきたいと思います。 学区域内で不審者情報があった際には、各校それぞれ、学校からそれぞれの学校、全校に周知するように現在行っているところです。","id":"exchange-137"},{"speaker":"澤田委員","kind":"質問・要望","question":"今後も校舎改築の際は、ぜひまたこの取組を区として後押ししていただきたいと要望いたします。区として、この取組について、どのようにお考えでしょうか、説明を求めました。","respondent":"森学校施設担当課長","answer":"今月の中頃には浜川中学校でも同様に工事見学会を実施いたします。参加していただけるようなことを様々検討していきながら、地域とともにある学校づくりのようなものを考えていきたいというふうに思っております。","id":"exchange-138"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、３７５ページ、学校給食費、学用品給与費についてお伺いいたします。そして、国立、私立の特別支援学校のお子さんへも給食費補助を拡充していただきたいのですが、ご見解をお伺いします。","respondent":"柏木学務課長","answer":"２つ目、都立特別支援学校の給食費補助の事業を開始してから、私立の特別支援学校の給食費補助についてはお問合せをいただいてあります。教育委員会といたしましては、いただいた内容を踏まえて、国立、私立の特別支援学校の給食費補助について検討をしてまいります。","id":"exchange-139"},{"speaker":"澤田委員","kind":"質問・要望","question":"こんの委員からも質問がありましたが、その助成対象に含まれない世帯の方たちからも、学用品の助成を望む声もお聞きしております。全ての子どもたちが等しく教育を受けられるように、その助成対象の枠を広げることを要望いたしますが、区としてのご見解をお伺いいたします。","respondent":"柏木学務課長","answer":"先ほどの答弁と繰り返しになる部分はありますが、保護者の負担の軽減については必要であると考えていますので、今後、保護者負担軽減を図る策について検討してまいります。","id":"exchange-140"},{"speaker":"澤田委員","kind":"質問","question":"今回は、３７９ページ、いじめ防止対策費についてお伺いいたします。そこでお伺いしたいのは、今年度、いじめ防止プログラムの一環として新たに行われた取組などがありましたら、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"今年度に入りまして、まず、教育委員会内部の認識を改めるということを行いました。現在は、研修会を中心ですけれども、今後は、児童・生徒が学校の中でいじめ予防ができるような取組を検討しています。","id":"exchange-141"},{"speaker":"澤田委員","kind":"質問・要望","question":"いじめが生まれないような環境をつくってくださること、生まれやすい環境を知ることで、いじめを抑えることができるのだと思います。引き続き、いじめを防ぐための子どもたちに向けた予防プログラムの検討を心より要望いたします。","respondent":"丸谷教育総合支援センター長","answer":"９月６日には、「いじめに関する事実と具体的な対応」ということで、子どもの発達科学研究所の和久田主席研究員をお招きして研修会を行いました。これは品川区立学校の全教員、全管理職を対象としておりまして、いじめについての認識を深めたものです。","id":"exchange-142"},{"speaker":"澤田委員","kind":"質問","question":"そこでお伺いしたいのは、発達に特性を持つ児童たちの通常学級での支援についてです。学校によって違うとは思いますけれども、現在の各支援員の配置状況と今後の予定、人材確保の方法について説明を求めました。","respondent":"唐澤特別支援教育担当課長","answer":"発達障害教育支援員につきましては、令和５年度からは、こちらの１０校に配置しています。人材の確保につきましては、委託である学習支援員、介助員につきましては、特定非営利法人ピアサポートに委託し、人材の確保に努めているところです。","id":"exchange-143"},{"speaker":"澤田委員","kind":"質問","question":"令和４年度のモデル校５校に加え、令和５年度はさらに拡充していらっしゃいますけれども、各学校に発達障害教育支援員は何名配置されているのか尋ねました。","respondent":"唐澤特別支援教育担当課長","answer":"発達障害教育支援員の配置の状況につきましては、毎日１人７時間程度配置されています。その内訳につきましては、２名程度でその５日を分けて、各日、１日いるというような形で実施しております。","id":"exchange-144"},{"speaker":"澤田委員","kind":"質問・要望","question":"発達障害教育支援員の全校への配置を強く要望するとともに、ぜひ毎日２名以上配置されることを望んでおりますけれども、区としてのご見解を説明するよう求めました。","respondent":"唐澤特別支援教育担当課長","answer":"現在、１５校、モデル実施しておるところですが、まずは今、小学校（前期）課程に１５校配置しておりますが、全ての小学校（前期）課程の配置を目指して、成果を振り返りながら拡充について努めていければと考えています。","id":"exchange-145"},{"speaker":"澤田委員","kind":"質問・要望","question":"本当に今、小さい子どもたちがどう育っていくかでこの品川区も変わっていくと思いますので、ぜひ前向きに検討してほしいと求めました。積極的にアピールしたりして募集することにより、人材の拡充を進めていただきたいと考えますが、区としてのお考えを説明するよう求めました。","respondent":"唐澤特別支援教育担当課長","answer":"学習支援員、または医療的ケアが必要な看護師の配置なども実施しておりますので、そうした配置については今後も努めていきたいと考えております。学習支援員の人員確保につきましては、区内６大学への連絡など、こちらも引き続き努めていければと思います。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"ここは今日はあくまで事実確認で、そこの部分、誰が権限を持って判断していくのかというところは考えていかないといけないと思っています。ここの話はまた総括質疑でやらせていただいて、今日は事実確認のところをさせてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"今のお話ですけれども、発生時の報告が起案が漏れていて報告できていなかった。そのまま調査に入っていったということでございまして、調査結果がまとまってから、令和５年４月２５日付で書面にて教育長から区長へ報告をしたです。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"２つあるわけですけれども、この３月付の教育委員会が諮問されたほうの答申でも、研修の必要性が挙げられている。この３月の答申から半年ぐらいたっているわけですけれども、そして教育委員会を対象とした研修も行われているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"９月には、全教職員、管理職を含めた教員を対象に、１,０００人を超える教員向けに研修を行っているものです。教育委員会内部に向けての研修ということですけれども、我々が自ら法律を確認するといったことで、それぞれ委員会の事務局の中で確認をしたものです。","id":"exchange-148"},{"speaker":"松本委員","kind":"確認","question":"なので、法律を確認するだけでは何が重大事態なのか分からないというふうなことではないかと思います。確認をしておかないといけないのですが、現在の認識として、この令和２年６月５日が重大事態の発生時期というふうに認定しているかお伺いします。","respondent":"丸谷教育総合支援センター長","answer":"３月の答申には適応障害と診断され、「いじめにより当該学校に在籍する児童等の生命、その場合場合によっては変わってくるものと思います。今回の事案については、適応障害と診断された時点、もしくは頻繁に倒れた時点というようなことで認識はしています。","id":"exchange-149"},{"speaker":"松本委員","kind":"確認","question":"でも、やはり法の確認をしても、重大事態かどうかということは認定できないと思っています。今回のような精神的な被害が生じている場合に、現在、品川区はどのような基準をもって重大事態の判断をしているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"いつの時点で重大事態と認定するかですけれども、８月の答申には、そうした認定のフローがないということが、まず課題として挙げられております。今後、適切に認定ができるような対応、対策をとってまいりたいというふうに考えております。","id":"exchange-150"},{"speaker":"松本委員","kind":"質問","question":"基準を明確に答えられないというのは、対応ができないというふうに考えられる可能性もありますので、そこはまた総括質疑で伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"３７６ページ、教育指導費についてお伺いしたいと思います。品川区の公立小・中学校、状況はどうなのか尋ねました。","respondent":"中谷指導課長","answer":"人数としましては、今、１０月１日の時点で、病気休職者数は合計で２１名、そのうちの精神面によるものは１７名というような状況になっております。","id":"exchange-152"},{"speaker":"須貝委員","kind":"確認","question":"それで、いろいろな方が、不登校はどうなっているのだ、いじめはどうなっているのだと何度も聞いているわけではないですか。何のために予算特別委員会、決算特別委員会で皆さんとお話ししているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"重大事態としての認定が遅れたというようなことで、不十分さがそこにあらわれていたというふうに認識しております。必ず教員が対応しているわけですけれども、我々も認識を改めまして、各学校には現在指導しています。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問・要望","question":"そんなに足りなくありませんとおっしゃっていましたけれども、現に教室に出ていない先生のカウントまで入れたら、もっと多いのではないですか。これは品川区だけではなくて全国もそうですが、その辺について、どのように品川区ではお考えか尋ねました。","respondent":"丸谷教育総合支援センター長、中谷指導課長","answer":"早期対応ということで進められるように、検討と申しますか、準備を進めているところです。今後も引き続き、区民の皆様の信頼回復ができるように努めてまいります。４５時間を超えていくと疾患と業務の関連性が強まるというふうにされておりますので、ご案内と支援をしていきたいというふうに思っております。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"これはおかしくないですか。このようなことをやっていていいのか尋ねました。","respondent":"中谷指導課長","answer":"今現在、今も全国から品川区の教育に携わりたいということで来てくださる方が一定数いらっしゃるということをお伝えしたいと思います。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういう方を、責任を持った職員を、教員を配置させなければいけないのではないでしょうか。私は、通勤時間の短縮や災害対策にもなる安価な家賃住宅を提供して教員の負担を減らしたらいいと思うのですが、ご見解を説明するよう求めました。","respondent":"中谷指導課長","answer":"若手教員の労働改善というところですけれども、まず、こちらにつきましては、関係課と連携しながら検討を考えていきたいと思っています。今、そういったサポートを強力にやっているところなので、いい取組をぜひ全校で広げていくというようなことをやっていきたいと思っています。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"このようなやり方をいつまでも繰り返していては駄目ではないですか。このような区でいいのでしょうか、企画課、企画部長。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"鈴木委員","kind":"質問・要望","question":"病休をとられている方の人数は、小学校、中学校２１名ということですけれども、それぞれ何人なのかも伺いたいと思います。それで改善されたのか、それでも補充できていない状況があれば、その人数も伺いたいと思います。","respondent":"中谷指導課長","answer":"そのうち代替教員で補充できた数が１６名、時間講師の任用は０名ということで、未補充が４名という状況です。それから、今年度より新規に開始されました産・育休代替の教員の前倒し任用、これまでに１５名が実績として活用されているというような状況です。","id":"exchange-158"},{"speaker":"鈴木委員","kind":"質問","question":"すべきことが明白なのに、品川区でも大変な実態も先生方から伺っていますけれども、そのような状況になっていると思います。先生のなり手がすごく少なくなっているということで伺っているのですけれども、その応募者の割合についても伺いたいと思います。","respondent":"中谷指導課長","answer":"４５時間を超えた教員に個別に丁寧に対応していくことや、また、実施していただくようお願いしています。そして報道で出てきております小学校の採用応募率が１.１倍ということで、過去最低というようなご報告があります。","id":"exchange-159"},{"speaker":"鈴木委員","kind":"質問・要望","question":"超過勤務命令が出せるのは限定４項目となっていますけれども、労働時間が無制限となり、今の実態を招いているということになっていると思います。この残業代が払われない制度を廃止して、残業代を支給できる仕組みに変えることが必要ではないかと思いますけれども、区の見解を伺いたいと思います。","respondent":"中谷指導課長","answer":"そのことによって、副校長の業務が減るだけではなくて、教員と向き合える時間もきちんとつくっていきたいと考えています。こちらを踏まえて、変更が生じた場合には適切に対応してまいりたいと思います。","id":"exchange-160"},{"speaker":"鈴木委員","kind":"質問・要望","question":"中学校の保健体育の中で、これは品川区でも、生命の安全教育の中でもそういう立場でやっているのかということを１つ伺いたいと思います。それを担うのが性教育だと、こういうふうに言っているのですけれども、区教委もこの立場に立つべきだと思うのですが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"生命の安全教育につきましても、国が出している方針に従って、発達段階に応じた指導をしています。まずは保護者の了解を得るなど、今後これがよい取組であるということで学校からございましたら、広がりを見せていくものというふうに考えております。","id":"exchange-161"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この歯止め規定の内容についても、文科省では、各学校で必要であると判断すれば指導することができるとなっているのです。それなので、ぜひ私は、この外部指導の講師の活用を広げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-162"},{"speaker":"吉田委員","kind":"質問","question":"お話を伺う中で、たくさんありますよということを教えていただいたので訪ねたところ、感動いたしました。私は、今回は特にさわる絵本作成に関して、貸出し事業に対する図書館としての評価を伺いたいと思います。","respondent":"吉田品川図書館長","answer":"活動自体は、品川区にあるボランティア団体「むつき会」が、昭和４５年辺りから、品川図書館と大崎図書館を拠点に活動なさっているところです。","id":"exchange-163"},{"speaker":"吉田委員","kind":"質問・要望","question":"単価の４,０００円なのですけれども、これ、材料費なのでしょうか、製作費も込みなのでしょうか。ぜひ継続していただきたいのですけれども、ボランティア団体への支援など、ほかに政策的なものがあったら説明を求めました。","respondent":"吉田品川図書館長","answer":"この制度によって、ほかの自治体から要求といいますか、貸してほしいというものがあったものについて対応しています。定期的に毎週火曜日、こちらの品川図書館のほうに来ていただいて、品川図書館の会議室で作業をしていただいているところです。","id":"exchange-164"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川図書館の事業として継続を求めたいのですが、その点についても見解を伺いたいと思います。この点について見解を伺います。","respondent":"吉田品川図書館長、宮尾庶務課長","answer":"支援については、４,０００円の費用感のところですが、この辺とのバランスも兼ね合いまして定まっているものと考えているところです。２番目にいただきました、品川図書館に３つほどブース… 私からは、ＰＴＡに関するご質問にお答えしたいと思います。あくまでも任意でございまして、会員になれば、誰もがご自身の意思で活動に参加ができるものというふうに認識をしております。","id":"exchange-165"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、だからといって、一人一人の保護者が、その活動に参加することを強制されるべきではないと考えます。今のご答弁を伺うと、それからもう１つ、どのようになっているか伺いたいと思います。","respondent":"宮尾庶務課長","answer":"ＰＴＡに加入するかどうかというところですけれども、こちらは任意ですので、強制等をするべき性格のものではないというふうに認識をしています。こちらも当然のことながら、加入の意思をお示しになられた方を対象に、適正な方法で徴収をするべきだというふうに考えてあります。","id":"exchange-166"},{"speaker":"吉田委員","kind":"質問","question":"徴収については、本当におっしゃるとおりだと思うのですけれども、そこにやはり学校が便宜的に仕組みを使っておられますよね。今のところ、当然のように学校が代わりに徴収しているのではないのかというようなことを伺ったのですけれども、その点についてはいかがか尋ねました。","respondent":"宮尾庶務課長","answer":"何か考えというようなものをお示しをしたということはございませんけれども、それは何か改善できるべきところがあれば、学校等からもお話を伺っていくべきだというふうに考えます。","id":"exchange-167"},{"speaker":"吉田委員","kind":"質問・要望","question":"子どもが２人いて、小学校だけで４つ学校に行っていますので、非常にセンシティブな問題になりつつあると思います。その点については大丈夫というふうにお返事をしてもよいですねということを最後に確認したいと求めました。","respondent":"宮尾庶務課長","answer":"このような考え方で学校とＰＴＡの皆様とが、よりよい関係づくりができるように、我々教育委員会としてもしっかりとお支えしてまいりたいというふうに考えております。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問・要望","question":"スクールゾーン設置の要望は、通常、教育委員会は関与しないで、学校側が直接警察へ相談をするのか、その手順を教えてください。そして、今回の城南第二小学校のスクールゾーン設置の要望について、教育委員会は把握をしているのか尋ねました。","respondent":"森学校施設担当課長","answer":"なぜスクールゾーンに入ることができないかというところなのですけれども、やはり他の学校のスクールゾーンよりも道路幅員が広いというところ。学校と教育委員会で連携をとりまして、各関係機関に働きかけをしていきたいと、そのように考えてあります。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問・要望","question":"正に今回、学校側、保護者側が心配しているような悲惨な事例があったから創設をされた通学路の安全対策を活用することもできるのではないでしょうか。やはり品川区教育委員会が主導して、警察への働きかけや庁舎横断的な安全対策の強化を行ってほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"通学路の安全管理についてですけれども、こちらは教育総合支援センターでも定期的に確認をしております。現在の城南第二小学校の現状を見ながら、学校とも連携しながら、必要な関係各所とも連携をしながら、児童の安全確保に努めてまいります。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問・要望","question":"改築を実際に行う事業者が、仮用地の用地取得を求めていますが、その理由をどうお考えか教えてくださいというのが１つ。これからは、そういう適正な工期とか予算を設定していただけるのかどうか、最初に質問したものと併せて伺います。","respondent":"森学校施設担当課長","answer":"実は、現在改築工事中の各学校についても４週８閉所で考えてはいるのですけれども、土日に出るというような状況が起きています。今後もそういうことがないように、土日は休むことができるように、しっかり検討をしていきたい、そのように考えております。","id":"exchange-171"},{"speaker":"せりざわ委員","kind":"提案","question":"３８９ページ児童・生徒用タブレット端末等運用、それから、教育費全般から教育長の方針についてお伺いしたいと思います。それを受けて、私も２０２０年に本会議で、区の区立学校全体でタブレットを１人１台にできないのかというような提案をしましたとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"２０１４年に、主に規模の小さな学校を中心に、１人１台のタブレット端末を配布して活用を進めてきたという経緯があります。今回、２０２１年にＧＩＧＡスクール構想の１人１台タブレット、全校に広がるその基礎となったというふうには認識しております。","id":"exchange-172"},{"speaker":"せりざわ委員","kind":"提案","question":"それの具体的な提案も続けてします。３つある中で、例えばＺｏｏｍを使って英語でのディベートをしたらいかがですかとか、座り過ぎですよということを注意してくれたりしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"ＩＣＴも活用しながら教育活動を進めていくということで研究を進めておりますので、また周辺の学校にも取組を広げられるような取組を進めていきます。こういった取組も学校で進められるというふうに考えております。","id":"exchange-173"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"それに対して、そういうあえて取り組んで新しい技術を学んでいくということも１つ方法かと思いますので、こちらは要望で終えたいと思います。お願いします。","respondent":"伊崎教育長","answer":"そこをきちんと子どもたち一人一人が認識をしながら、また、そのような教育をしていきたいと考えています。誰一人取り残されない、そのような全ての子どもたちの可能性を引き出す学びを学校教育の中で進めていきたいと考えております。","id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1542#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":122287,"voices":397}},{"id":"r05-20231019-4","meetingId":"r05-c-settlement","date":"2023年10月19日","dateIso":"2023-10-19","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは、ふるさと納税と品川区の広報戦略についてお伺いします。そして、これまで取り組んできた区の取組と、これまでやってきた中での課題感というのがあれば、まず教えてほしいと求めました。","respondent":"堀越総務部長","answer":"例えば、地元企業との連携も促進しながら、区の魅力の発信をさらに充実させていかなければならないと考えています。併せて、ガバメントクラウドファンディングの取組もさらに拡充していきたいということで、寄附の増加に努めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"せりざわ委員","kind":"提案","question":"品川区でこれまで議会でも様々提案させていただきましたが、品川区が２３区等と手を取り合って、国に強く働きかけを行っていくしかないと思います。以前も提案させていただきましたが、まだまだ返礼品に足りていないと思いますので、そちらについては今後の展開をお聞かせほしいと求めました。","respondent":"堀越総務部長","answer":"先ほどお答えした中で、地元企業との連携をさらに促進しながらというお話をさせていただいたところです。先ほど申し上げた企業などと様々な連携をする中で、企業のターゲット層といいますか、様々な面で努力していきたいと考えているところです。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"提案","question":"昨年これも提案させていただきましたが、所管が税務課で、今回の決算特別委員会でもずっと税務課長にお答えいただいていたと思います。私は、執行体制の改変の検討というのもぜひ進めてほしいと求めましたが、今考えている組織体制の検討状況を説明するよう求めました。","respondent":"久保田企画部長","answer":"総務部門が９区、税務部門が４区、企画財政部門が４区、あとはその他、専門の部署を設けている区もありますが、そういった状況です。私どもとしましても、しっかりと対応できる執行体制について検討していきたいと考えているところです。","id":"exchange-003"},{"speaker":"せりざわ委員","kind":"提案","question":"既に納税した方の横のつながりといった展開を求めていくというのも、１つ、こちらもご見解をお聞かせください。１つ、ふるさと納税に対しての特別サイトでそれぞれが補完し合うような制度の構築というのも１つ、それぞれご見解を説明するよう求めました。","respondent":"久保田企画部長","answer":"次に、特別区での連携したふるさと納税への対応についてですけれども、特別区、他の区においても危機感を持っていると認識しております。ただ、特別区における連携につきましては、他区の動向等も踏まえつつ、調査研究が必要な課題であると認識しています。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"そういったことがそもそもできるのかというのもやはり確認してほしいと求めましたが、そういった品川区のサービスに結びつけるというのも１つ。もしくは会派要望でもお伝えさせていただきましたが、ここの広報戦略について、今の検討状況を説明するよう求めました。","respondent":"久保田企画部長","answer":"品川区も、区の魅力の一つであるという認識をしておりますので、区のプロモーションにつながると考えているところです。今後は、開始から約８年を迎えるといったところもありますので、新たな取組を検討していきたいと考えているところです。","id":"exchange-005"},{"speaker":"せりざわ委員","kind":"提案","question":"その中で、もしくは再発掘して広報してほしいと求めましたが、例えば観光大使についても以前も提案させていただきました。例えば１日観光大使でもいいと思いますし、１日区長など、そこについてご見解を説明するよう求めました。","respondent":"久保田企画部長","answer":"観光大使等を活用してプロモーションを図っていくということは大変有意義な手法だと認識しておりまして、サンリオにご協力いただきながら進めていて。","id":"exchange-006"},{"speaker":"せりざわ委員","kind":"質問","question":"私からの質問は以上で終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"せお副委員長","kind":"質問","question":"令和４年度に事業を安定的に執行するために心がけたことは、どのようなことでしょうか。そのようなシティプロモーションをはじめ、今後の事業展開はどのようになっていくのか尋ねました。","respondent":"森澤区長","answer":"物価高騰への対応は喫緊の課題でありまして、速やかに補正予算を提案することで、区民や区内企業の皆様方の支援を進めました。地元企業、各地域で活動する団体等とも連携しながら、戦略的なシティプロモーションを検討していきたいと考えています。","id":"exchange-008"},{"speaker":"せお副委員長","kind":"質問・要望","question":"令和４年度、社会を明るくする運動において、主にどのような目的で事業を展開され、どのような成果がありましたでしょうか。品川区では再犯防止推進委員会が設置され、再犯防止推進計画を策定中であり、保護司会からも計画策定の要望があったと伺っております。","respondent":"川島地域振興部長","answer":"民生委員、関係機関が連携することに一定の成果があり、犯罪や非行した方の立ち直りを支える地域社会を目指すことを目的として実施しているものです。その素案についてパブリックコメントを今実施しており、令和６年１月には、３月に計画を公表する予定です。","id":"exchange-009"},{"speaker":"せお副委員長","kind":"質問","question":"今お話ししたような、出所してから福祉サービスを利用したケースは、今までありましたでしょうか。そして、そのようなケースがあってもなくても、このような取組にどのような課題がありますか尋ねました。","respondent":"今井福祉部長","answer":"現時点ではサービスご利用者の状況は把握してございませんが、過去に窓口で、出所後であることをご本人からお伺いして対応した事例はあります。支援につなげていくことが、地域共生社会、地域全体の課題と捉えております。","id":"exchange-010"},{"speaker":"せお副委員長","kind":"提案","question":"そういった官民連携は、再犯防止推進計画が策定されるに当たって、どのように検討されていますでしょうか。情報提供もできるのか尋ねました。","respondent":"川島地域振興部長","answer":"官民連携まで踏み込んだ具体的な検討というのはしてございませんが、適切な保健医療や福祉サービスにつなげるために重要な視点と認識しています。","id":"exchange-011"},{"speaker":"せお副委員長","kind":"質問","question":"先ほどおっしゃっていましたが、保健医療との連携も大変重要で、再犯防止はまさにこの事業の中で取り組まなければならない支援だと思っています。地域福祉計画や重層的支援体制整備事業に再犯防止施策を取り入れることについて見解を伺います。","respondent":"今井福祉部長","answer":"地域福祉を支える区民の皆様による実行委員会形式で策定中の第四期地域福祉計画においては、相互に連携を図る計画として位置づけをする予定です。重層的支援体制整備の中で、所管の地域活動課だけではなく、庁内および多機関連携の中で対応してまいりたいと考えております。","id":"exchange-012"},{"speaker":"せお副委員長","kind":"質問","question":"東京都の何かしらの補助金を利用する、区の職員が業務に慣れるまで都の職員を派遣してもらうなど、できないのでしょうか。見解を伺います。","respondent":"柏原子ども未来部長","answer":"児童相談所の設置市事務について、庁内で検討を計画的・継続的に進めてきておりまして、事務の中の精査といったところを行ってきたところです。","id":"exchange-013"},{"speaker":"せお副委員長","kind":"質問・要望","question":"医療機関に関しては、一時保護に協力していただける病院を増やす努力をしていただきたいのですが、見解を伺います。個別の支援計画も立てていただけると伺っておりますが、ＳＴなども含めた、個々の特性に対する具体的な支援を説明するよう求めました。","respondent":"柏原子ども未来部長","answer":"お一人お一人の支援プログラムを作成して、個別計画を基本に対応するといったことになってあります。治療行為やリハビリなどが必要な場合は、医療機関等への一時保護委託、また職員による同行通院などを想定しながら進めていきたいと考えています。","id":"exchange-014"},{"speaker":"せお副委員長","kind":"質問","question":"この視点における、令和４年度の成果と現在の課題を教えてください。そのような観点から、スピード感を持って有効活用に取り組むべきと考えますが、区の見解を説明するよう求めました。","respondent":"久保田企画部長","answer":"公有地の活用につきましては、地域の方や関係する団体など、様々な区民の意見や要望をお聞きしながら検討することが大事だと考えているところです。今後も公有地の有効活用に向けまして、スピード感を持って検討してまいります。","id":"exchange-015"},{"speaker":"せお副委員長","kind":"質問・要望","question":"そのような視点・考え方を区として持っていただきたいのですが、見解を伺います。障害者の清掃業務などの労働機会を現状より減らすことがないようにしていただきたいのですが、こちらも見解を伺います。","respondent":"溝口防災まちづくり部長","answer":"併せまして、せお副委員長ご指摘の社会貢献や地域貢献といったものを併せて進めていくといったことも重要であると認識しています。本制度を導入することで、減らすことのないように留意しながら、本事業の導入を進めていきたいと考えているものです。","id":"exchange-016"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ですから、優先順位はどこなのか、私なりに調査したり考えたりしていました。そして今後、障害児の福祉に関する事業での所得制限を段階的に撤廃することについて、それぞれ見解を伺います。","respondent":"今井福祉部長","answer":"区負担額１２０万円余に約４００万円を追加することとなり、総額で５２０万円余が全額の区の負担額となろうかと考えています。子どもの支援を進める観点から、それぞれの事業の性質に鑑み、多角的に検討してまいりたいと考えております。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"地域共生社会の実現に向けた包括的支援体制を推進する重層的支援体制整備事業（しあわせ創設プラン）と、孤独・孤立対策についてお尋ねいたします。２０２０年の第１回定例会より、体制整備を求めてきたことから、２０２５年度の本格稼働に向けた盤石な体制を求めるものです。","respondent":"今井福祉部長","answer":"令和７年度の本格実施に向けまして、鋭意検討を進めております。相談支援の対応につきましては、ケース会議での協議を経て、関係者間協働で相談者への回答を行うなど、成果が出ているところです。","id":"exchange-018"},{"speaker":"つる委員","kind":"意見","question":"人生のあらゆる段階において何人にも生じ得るものであり、社会のあらゆる分野において孤独・孤立対策の推進を図ることが重要と明記されました。そこで、品川区の孤独・孤立の現状と把握状況、区がこれまでに取り組んできた孤独・孤立対策についてお知らせくださいとの意見を述べました。","respondent":"今井福祉部長","answer":"同世代の支援体制や施策の検討が必要なこと、特に、やはり関係が希薄化と言われている都市型の孤独・孤立について分析が求められると考えております。私どもは今年度から、区民の皆様の孤立・孤独を防止する様々な対策について検討を進めていきたいと考えています。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"過日の一般質問の答弁では、また、孤独・孤立に悩む幅広い世代に対しての基本的施策の体系化の検討が行われていると認識しています。孤独・孤立対策推進協議会の設置時期、構成メンバー、具体的な役割など、改めて示すよう求めました。","respondent":"今井福祉部長","answer":"孤独・孤立対策事業を行っていらっしゃいます区内のＮＰＯ法人などの組織・団体の洗い出しを行い、活動内容を把握してまいります。設置時期につきましては来年度を予定しているため、設置時期です来年度にお示しすることを予定しております。","id":"exchange-020"},{"speaker":"つる委員","kind":"意見","question":"高齢分野においては６４.４％、子ども分野においては４２.９％という回答で、各世代において孤独・孤立の課題が存在していることが分かりました。若年層に向けた具体的な孤独・孤立対策をどのように強化していくのか、区のお考えをお知らせくださいとの意見を述べました。","respondent":"今井福祉部長","answer":"今年度、孤独・孤立対策に係るアンケート調査などを実施いたしまして、さらなる情報の集約と分析を行ってまいります。この分析を基に各事業あるいは新規対策として、庁内横断的に施策を展開して検討してまいりたいと考えております。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問・要望","question":"今、「新規」とございましたけれども、若年層に向けた具体的な孤独・孤立対策を積極的に検討してほしいと求めました。品川区の孤独・孤立対策の区民への周知、意識啓発をどのように行っていくのか、併せて示すよう求めました。","respondent":"今井福祉部長","answer":"現在、区が取組を進めております重層的支援体制整備事業と一体的に推進していく必要があるとの認識の下、９月８日付で採択されたところです。庁内や関係団体との共有・議論を行い、ＳＮＳなどの発信のほか、シンポジウムなどの開催を考えております。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"そうした方へのアプローチも含めてお考えいただきたいので、ここについては改めてご答弁ほしいと求めました。在宅介護支援センターや、しあわせ創設プランでの位置づけはどうなるのか、現在の相談対応実績と併せて示すよう求めました。","respondent":"今井福祉部長","answer":"まず相談件数ですが、直近の令和４年度の在宅介護支援センターの相談対応実績につきましては、支え愛・ほっとステーションの相談・対応実績は。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"ドクターの元には、病気そのものの診察だけでなく、地域福祉に該当する相談も寄せられていると、医師会所属のドクターからも伺っています。社会福祉士の活用など、地域福祉的なご相談への支援策が必要と認識しますが、ご見解を示すよう求めました。","respondent":"今井福祉部長","answer":"地域福祉に関わる医師・医師会等との連携につきましては、在宅を支援します関係者の皆様との意見交換や、地域ごとに進めてきたところです。相談機関の情報リーフレットの提供などを行い、地域福祉、そして地域資源の情報共有に努めていきたいと考えております。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"孤独・孤立の具体的な予防策の一つとして、ｅスポーツを活用した多世代交流の推進を求めてきました。ｅスポーツを通じた多世代交流の事業の進捗状況と、同事業の継続・拡大を視野に入れた実施を求めますが、ご所見を説明するよう求めました。","respondent":"柏原子ども未来部長","answer":"実施時期につきましては、まだ確定はしてございませんけれども、なるべく早期に実施したいということで調整を図っているといったところです。機会があれば多世代交流事業を実施していきたいという考えでございまして、今回こうした事業を実施する中で、検証していきながら。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"協定について、また引き続き、ぜひ積極的な検討をお願いしたいと思います。加工が可能な状態での提供や、防災資機材整備助成金の対象に地図データを含めるなど、対象の拡大および交付額の増額を検討してはいかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"街頭消火器、地図の保管や印刷も任意の縮尺で行えるものとなっておりますので、まずは「しながわＭＡＰ」の活用を考えていただければと思います。共助を担う組織の地域防災力向上のための支援として、今後はその費用助成についても検討してまいりたいと考えております。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"それぞれ、積極的な検討、そして実施を期待して、私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"単年度収支について、財政運営の面などから説明を伺います。水と緑や災害時協定など、交流を行っている５つの市町のふるさと納税の活用事業についてもお聞かせほしいと求めました。","respondent":"遠藤財政課長、久保田企画部長、堀越総務部長","answer":"令和３年度に実施しました新型コロナウイルスワクチン接種等に国からの支出がありましたが、対象経費に対して収入額が超過したところです。… 今回実施したことによりまして、各事業の達成状況や効果・課題を把握することができました。現在では評価作業を進めているところであり… 区の財政に影響を及ぼしていると考えてございまして、区民サービスの低下を避けるべく、対策が必要となっていると認識しています。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"指導などを行うことで、認知機能低下に自ら努力できることから、あたまの元気度チェックの早期導入を求めております。これにつきましても、改めてお考えをお聞きいたします。","respondent":"堀越総務部長、川島地域振興部長、今井福祉部長","answer":"この５市町とのさらなる理解や交流を深めること、先方の意向も確認しながら、前向きに検討してまいりたいと考えています。そうした区民の声には迅速かつ丁寧に対応するとともに、実態把握と良好な環境の保全に努めてまいりたいと思ってあります。目的や手法… 定量的かつ定期的に高齢者自らが自身の変化を認識することにより、早期発見・早期対応に資する取組として効果が見込めるものと認識しております。","id":"exchange-029"},{"speaker":"若林委員","kind":"質問・要望","question":"３５の団体から区政への意見・ご要望をお聞きするとともに、区民との個別対話を行い、８００人以上の方々からお話を伺いました。全ての人を受益者とする新たなセーフティーネットの整備を求める声が高まっていることから、ポストコロナの新しい社会の構築への視点と定めました。","respondent":"川島地域振興部長、阿部健康推進部長、柏原子ども未来部長、中村都市環境部長","answer":"誤りでございまして、大崎駅東口ではなく、大井町駅東口にコンテナ型喫煙所の設置の準備を進めているものです。失礼いたしました。区民の実際の出産費用については把握してございませんが、区内の分娩取扱い医療機関における通常分娩の費用は、おおむね６０万円前後となっています… 支給人数は令和５年度当初で１５９人、所得制限で受けられていない人数は、およそ２９０人ということで捉えてあります。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"本年３月、学用品と、区立学校以外に通う子どもの給食費の負担軽減策を区長に緊急要望いたしました。款別審査で取り上げた高齢者インフルエンザワクチン接種費用の無償化、補聴器購入費助成の所得制限撤廃についても、改めてお考えをお聞きいたします。","respondent":"米田教育次長、今井福祉部長、阿部品川区保健所長","answer":"全児童・生徒に対する世帯数は把握してございませんが、就学援助認定以外の方に就学援助費相当を支給した場合は約９億１,０００万円余と見込んです。… 現下の厳しい状況に鑑み、介護サービスの安定的な提供が図られますよう、介護人材の確保と定着を促進する方策について検討を進めてまいります。引き続き… 私からは、高齢者インフルエンザワクチンについてお答えいたします。","id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"国・都の支出金も最大限に活用した財源の確保、施策分野や対象世代のバランスにも配慮しながら、積極的な予算編成を行っていただきたいと存じます。ベーシックなサービスへのご見解、また今後の施策展開のお考えを、最後にお聞きしたいと存じます。","respondent":"久保田企画部長","answer":"一方で、施策を実施するには財源の確保が必要であります。区民に求められる施策をバランスよく実施することで、区民の幸せ、ウェルビーイングの向上を目指して区政を進めてまいりたいと考えているところです。","id":"exchange-032"},{"speaker":"若林委員","kind":"意見","question":"ベーシックサービスについては、本格的に今回こういった場で取り入れさせていただきました。この理想的な社会に向けて、私どもはまた区民の皆さんとも議論をしながら、また執行部とも議論しながら進めてまいりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"松永副委員長","kind":"質問","question":"そこで、公共事業の現場について、本区ではどのようなモニタリングをされているのでしょうか。建設団体による独自の調査によると、適正な賃金が支払われていないという調査結果が出てきておりますが、そのことについてどうか、併せて伺います。","respondent":"堀越総務部長","answer":"区では予定価格２,０００万円以上の工事請負および委託請負の契約を対象に、労働環境の確認を行っているところです。関係団体の意見交換の場などを通じまして現状把握に努めるとともに、引き続き、適正なチェックシートの提出を求めてまいります。","id":"exchange-034"},{"speaker":"松永副委員長","kind":"質問","question":"続けて公契約条例について伺いますが、既に制定されている他自治体の様子を伺っている段階だと認識しております。公契約条例について国での検討の動きなどがありましたら、その旨も併せて伺います。","respondent":"堀越総務部長","answer":"検討状況ですが、担い手の確保と持続可能な建設業を目指す方策の検討を行っておりまして、この９月に中間取りまとめを出しています。公契約条例の検討に当たっては、こうした国の動きについても注視していきながら検討していきたいと考えています。","id":"exchange-035"},{"speaker":"松永副委員長","kind":"質問","question":"避難所の受入体制は約３割と言われ、残りの７割の方は在宅避難を進めていると伺っておりますが、そして在宅避難の割合についてお知らせください。現在の状況について併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"それ以外の約７割、約２９万１,０００人の方が在宅避難者になり得ると考えております。令和６年度中に全ての区民避難所においてペットの受入れができるよう、避難所連絡会議などの場でご理解を得て、マニュアルを整備してまいります。","id":"exchange-036"},{"speaker":"松永副委員長","kind":"質問・要望","question":"現在、災害が発生した場合、区内各地区に１か所、学校医療救護所が設置されると伺っております。学校医療救護所の設置数が全体的に少ない感じがいたしますので、ぜひ増設していただくよう要望いたしますが、区のお考えについて示すよう求めました。","respondent":"滝澤災害対策担当部長","answer":"最後に学校医療救護所の設置数ですが、人口比で設置数を検討した場合には、区内１３地区に１５か所設置されることが適切であると算定されております。","id":"exchange-037"},{"speaker":"松永副委員長","kind":"質問","question":"もし可能であれば、町会・自治会加入の資料と同時に配布するなどの工夫も大切だと思いますが、いかがでしょうか。併せて伺います。","respondent":"滝澤災害対策担当部長","answer":"一方で、訓練の参加者が固定化しているなどの課題も認識しております。ご提案の町会・自治会加入などに関する資料につきましても配布していけるようにしてまいります。","id":"exchange-038","title":"町会・自治会支援"},{"speaker":"松永副委員長","kind":"質問","question":"いよいよ来年の４月にリニューアルオープン予定の品川歴史館ですが、４月のいつ頃にオープンされる予定でしょうか。併せて伺います。","respondent":"廣田文化スポーツ振興部長","answer":"リニューアルオープンにつきましては、ゴールデンウイークには多くの皆様に観覧いただけますように、４月の中・下旬頃を想定して準備しています。","id":"exchange-039"},{"speaker":"松永副委員長","kind":"質問・要望","question":"併せて、リニューアルした品川歴史館は、品川区全体の歴史が以前よりも多く詰まっており、またお茶室の利用も可能になると伺っております。ホームページ、そしてコミュニティバスの広告看板等での周知を要望いたしますが、いかがか尋ねました。","respondent":"廣田文化スポーツ振興部長","answer":"オープニングのセレモニーにつきましては、参加者や具体的な内容については現在検討を進めているところです。ご提案の内容につきましても、周知に活用できないかというところは当たっていこうかと思ってあります。","id":"exchange-040"},{"speaker":"松永副委員長","kind":"提案","question":"決まり次第、そしてリニューアルオープンする告知も大切なので、それぞれ区民に配慮した周知をお願いいたします。そして近隣町会や近隣住民にお願いするなど、共同でウォーキング大会やスタンプラリーなどの開催を提案いたしますが、いかがか尋ねました。","respondent":"廣田文化スポーツ振興部長","answer":"公演会や各種イベントのたくさんのご提案をありがとうあります。オープンに向けて検討していますけれども、オープン当初に全て実施するということは困難かとは思いますが、新しくなった歴史館に。","id":"exchange-041"},{"speaker":"松永副委員長","kind":"質問・要望","question":"大森貝塚１５０周年の記念品として、縄文クッキーを作っていただき、それを記念品としてお渡ししてみてはいかがでしょうか。併せて伺います。","respondent":"廣田文化スポーツ振興部長","answer":"大森貝塚発掘１５０周年記念のご要望を頂いたところですけれども、今後、品川区としても考えていきたいと思っているところです。一番早い課題となっておりますので、そちらに注力しながら、もう少し具体的なことについてはお時間を頂きたいと思ってあります。","id":"exchange-042"},{"speaker":"松永副委員長","kind":"質問","question":"ぜひ、大田区も含めた大きなイベントが開催できるよう、ご検討のほどよろしくお願いいたします。最後の質問になりますが、地域の方からのご意見を聞かれるなどして進めてみてはと思うのですが、本区の考えについて示すよう求めました。","respondent":"溝口防災まちづくり部長","answer":"令和９年には節目を迎えるということもありますので、それを見据えつつ、大規模な改修については検証していく必要があると認識しています。","id":"exchange-043"},{"speaker":"松永副委員長","kind":"質問・要望","question":"様々多くのご要望をさせていただきましたが、ぜひともご検討いただければと思いまして、私からの質問を終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"その点について、改めて確認させてほしいと求めました。土木費の質疑の際には、区民が利用できる区有施設についてあまりご答弁がなかったと思うのですが、改めてその点について伺います。","respondent":"有江都市整備推進担当部長","answer":"土木費で答えさせていただきました、権利についてのご相談というかご意見というのは私も聞いておりませんので、課長が答弁した内容と同じです。","id":"exchange-045","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"質問・要望","question":"まだ一件もお答えいただいていないのですけれども、そういう意味では一件もつくられていないという理解でよろしいのでしょうか。それは、そういう施設は区民が要望していないということで要望がなかったのか、地域の方たちからそういう要望が一切上がってこないという意味なのか。","respondent":"有江都市整備推進担当部長","answer":"市街地再開発事業における公共施設の整備については、開発予定地域におきましての地域特性や、関係部署との現況のまずは情報共有を行います。そういった取組の中で、整備ができるかどうかの判断につきましては、再開発事業者が需要性などを踏まえましてつくっていくものです。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区の中で、こういうものが要望に上がっておりますということを、きちんと伝えているのかどうかということです。具体的にこういう施設が何個、実現しておりますというお答えを頂きたいのですけれども、いかがか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"再開発における公共公益施設の設置に関しましては、各関係部署、様々な声を聞きながら設置しています。子育て支援施設、子育て支援施設では８施設、これまで再開発でつくっております。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えばどういう施設が実現しています、どういう要望が上がってきた結果、こういうものが実現していますというふうに教えていただけたらと思います。この中で、例えば障害者施設などが全然ないのですけれども、それはご要望がないという理解でよろしいか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"過去の経緯もありますので、この場では詳細はお伝えできないのですけれども、例えば子育て支援施設としては保育園などが設置されております。これまでの実績がないものですから、そういった中での調整の経緯につきましては、この場ではご答弁できない状況です。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"あくまで、地域や各所管から要望が上がってくるまで検討もされないという意味なのでしょうか。要望したのだけれども、それとも要望していないのかということについては、その点について伺います。","respondent":"有江都市整備推進担当部長","answer":"公共施設の設置についてですけれども、ある程度、場所が決まっているというような状況になっております。区としましては、そういった公共施設が必要であれば、そういった事業者に対して調整していくというような姿勢は持っております。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、例えば子育ての担当や福祉のほうから今までこういう要望を出したというような実績があったらぜひ伺いたいと思いますが、いかがでしょうか。こういう要望、一方で各所管には、うちの所管のこういう施設が足りないという声が上がってきているから」と要望してほしいと思うのですけれども。","respondent":"有江都市整備推進担当部長","answer":"その中で、関係部署に事前に、こういった場所での再開発の動きがありますので何か必要なものはございませんかというようなお問合せをします。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"地域特性でまず判断するというのは、どういう意味のご判断なのでしょうかというのと、最終的に事業性というのはよく分かります。その中で、例えば障害者施設や高齢者施設が入ることが、事業的にそれが不利になるというような判断が働いているという理解でよろしいのか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"そういったニーズというのがそもそも出てきませんので、そういったところではそういった声というのは多分聞こえてこないという形になると思います。拠点における地域特性を我々としては集約しまして、内部的に調整していくというような流れになっていきます。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば大崎を今、そこでは全ての施設が十分に整っているから特に要望しないというふうに聞こえてしまったのですけれども、「こう間違っています。こういうふうに要望しています」とお答えほしいと求めました。","respondent":"有江都市整備推進担当部長","answer":"そういったところがないような形でバランスよく公共施設を設置するというのが地域特性ではないかと考えています。区の考え方としては、やはり示していきたいと考えていますけれども、引き続き調整を進めていきたいと考えています。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区も事後評価は行われていると思いますし、その評価の中で、その辺の事後評価が実施されているかどうかについても併せて伺います。公表していただきたいのですが、私が検索した限りでは公表されていなかったのですけれども、公表についても伺いたいと思います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"そういうことで考えていって、事業者の方にご協力あるいはご理解いただければ、考えられないかというようなこともあります。いろいろ検討させていただければと思います。 新規事業採択における客観的評価指標を提出しておりまして、事業が適正かというものを含めて、国を含めて対応しています。もしくは緑地や空地率、公共公益施設などの増加によって、適正にまちづくりが進んでいると区は認識しております。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、この点については検討してほしいと求めましたが、改めて見解を伺います。そこが計画的に示されていないということが、そもそも問題なのではないかと思うのですけれども、その点についてもお考えを伺いたいと思います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"ただ、もう一つ言えるのは、先ほどから事業者等のお話もありましたけれども、一定、区でかなり努力しないと、これはできないです。最初から計画の中に区で一定の考え方を入れて、違う手法を検討できる例えば事業者等があれば… 事後評価につきまして私からお答えしますけれども、現時点では実施の予定はございませんけれども、他自治体の事例等を研究したいと思います。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"もし何か見解があったら、後で伺いたいと思います。ぜひ品川区でもそういう視点を持っていただきたいのですが、最後にもう一回、コメントを伺いたいと思います。","respondent":"桑村副区長、有江都市整備推進担当部長","answer":"いろいろご意見を頂きまして。なかなかそこまで頭が回らないですけれども、一定のお話になったのはよく理解できますので、十分検討させていただければと思います。 繰り返しの答弁になりますけれども、他自治体の事例等を研究してまいりたいと思います。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ検討していただいて、みんなが本当に賛成できる再開発を目指してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、羽田新ルートの中止、現庁舎跡地の検討、しながわ中央公園の存続を求めて質問をします。いかがか尋ねました。","respondent":"中村都市環境部長","answer":"まず区民アンケートの回答数についてですけれども、８万６,５３７人、割合として２４.２％です。公開についてですけれども、個人情報に配慮しつつ、どのような方法で公開できるかについてはこれから検討してまいります。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ品川区の上を飛ばないことを求めないのか伺います。区が国に要望していた固定化回避とは、何を求めていたのか伺います。","respondent":"中村都市環境部長","answer":"固定化回避検討会ですが、またさらに区民への丁寧な周知と説明を継続して行うように、これまで求めてきたところです。固定化回避検討会につきましては、可能な限り環境影響の軽減につながる方策の検討・実施を国に求めているものです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区の上空を飛ばないことを国に求めるべきです。区長、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"固定化回避検討会については、可能な限りの環境影響の軽減につながる方策の検討、そしてその検討結果の実施を国に求めているものです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"提案","question":"どんな内容で公募しているのかが区民に分かるように、事業者に渡した事業概要書と事前質問、回答シートの公開を求めます。いかがか尋ねました。","respondent":"多並広町事業担当部長","answer":"１０月５日に募集を締め切り、１０月下旬から１１月上旬に向けてヒアリングを行っていく予定です。最後に、応募があった事業者に跡地活用の概要を説明するための事業概要書と、提案内容を確認するために回答シートを事業者へ渡し。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今からでも区民には公開するようにしてほしいと求めましたが、なぜ公開できないのか、伺います。事業概要書と事前質問の内容も、どんな内容だったのか伺います。","respondent":"多並広町事業担当部長","answer":"この内容につきましては、結果を概要としてまとめて公表していくことになってあります。この進め方の手順に当たっては、先ほども少しご説明させていただきました、まとめて必ず公表するです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"このどこが、区長の言う「区民とともに創るしながわ」なのか、伺います。いかがか尋ねました。","respondent":"多並広町事業担当部長","answer":"引き続き、区民と共に検討を進めてまいります。官民連携によるまちづくりは、行政と民間が連携することで、引き続き検討を進めてまいります。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"現庁舎跡地には、特別養護老人ホームや老健施設、障害者総合支援センターなど、福祉施設の整備を求めますが、いかがでしょうか。区が実現を目指す区民ニーズには福祉施設は入っているのでしょうか、伺います。","respondent":"多並広町事業担当部長","answer":"庁舎跡地等活用検討委員会で、区民のニーズの把握に努めているところであり、具体の施設を想定して検討しているものではございません。新庁舎建設に係る区民負担の軽減と、区民ニーズのかなうまちづくりを両立させてまいりたいと思っておるところです。","id":"exchange-063"},{"speaker":"のだて委員","kind":"提案","question":"さきの一般質問で、この公園の存続を求める質問に、区は、「廃止を前提として検討を進めるものではない。現庁舎跡地だけでは企業にメリットが少ないから、しながわ中央公園まで広げたのでしょうか、伺いますとの意見を述べました。","respondent":"多並広町事業担当部長","answer":"検討対象については、あくまで庁舎跡地およびその周辺のまちづくりを一体的に行う観点が必要との考えから設定したものです。現在の公園を活かしつつ、区民ニーズを把握した上で、庁舎周辺の一体的なまちづくりについて検討を進めていく考えです。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"多くの区民が利用するしながわ中央公園を今のまま残し、不足している福祉施設の整備を含め、情報公開と区民参加で検討するよう求めます。以上で、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"都市再開発法に基づく市街地再開発に投入してきた税金額は累計幾らになったのか伺います。その額は２３区の中では何番目になるのか伺います。","respondent":"有江都市整備推進担当部長","answer":"市街地再開発事業に携わっている部署ということでは都市開発課になりますけれども、部長１名と課長２名が所属しております。事業が完了したものと、現在事業中の事業が完了するまでの予定額を合わせまして、合計で約１,５３０億円になります。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"私は款別審査で、武蔵小山で既に建った２棟の超高層開発ビルについての状況について伺いました。それぞれについて伺いますが、土地所有者数と借地権者数、商業店舗数も伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"土地所有者数が２名、借地権者数が１１３名で、約１００店舗程度と考えております。土地所有者が１６４名、借地権者が１５名で、約４０店舗になります。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"では伺いますが、２地区について、地権者のうち何％の方が戻ってこられたのか、割合を伺います。なぜ公表できないのか、改めて伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"パルム駅前地区および駅前通り地区におきましての、戻ってきた地権者の数ですけれども、再開発組合に確認したところ、現在事業中でありまして、個人情報に関する情報につきましては非公表ということで、区としては聞いております。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"どうでしょうか。伺います。","respondent":"有江都市整備推進担当部長","answer":"市街地再開発事業においては事業者が組合となりますので、情報の取扱いにつきましては組合が判断するものと、区は認識しております。地域ごとの課題に対応し、地域全体の発展を目標に進めておりまして、地域主体で進めているまちづくりについては支援したいと考えています。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"中止するよう強く求め、次の質問に移ります。併せて、区教育委員会がいじめの重大事態だと判断したのはいつになるのか、伺います。","respondent":"米田教育次長","answer":"学校では、生徒への指導や調査を行うなどの対応を行ってまいりましたが、当該生徒は他区の中学校への転校を余儀なくされたといういじめの経緯です。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ区教育委員会は、このような事態を把握していたにもかかわらず、いじめの重大事態と捉えることができなかったのか、伺います。なぜ区教育委員会事務局は、これだけの事態に際し、受け身で対応したのか、何が原因だったのか、今後こうした姿勢は変わるのか、伺いたいと思います。","respondent":"米田教育次長","answer":"いじめ行為の停止に向けた取組について、学校訪問や関係機関を交えたケース会議にて今後の対策を検討するなど、当時できる対応は行ってまいりました。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"他の３件の重大事態について、これは法における生命心身財産重大事態なのか、不登校重大事態なのか、伺います。区教育委員会の認識を伺いたいと思います。","respondent":"米田教育次長","answer":"こちらの詳細についての説明につきましては、区ホームページへの公表、議会への報告をします。登校にも至ったものではありますが、いじめの重大事態として認定しておりませんので、説明させていただきました。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"最後に、今後の対策の具体化について伺いたいのですが、２０１２年の区内での痛ましいいじめ自殺の事態を受け、様々な体制を取ってきたと思います。併せまして、報告書の検討事項、提言を受けて、区教育委員会はいじめ解決防止のためにどんな対策を取るのか、伺いたいと思います。","respondent":"米田教育次長","answer":"いじめ防止に関する講演会の実施、いじめ専用電話の設置などのいじめ相談窓口の設置、様々な取組を行ってまいりました。児童・生徒のトラブルが起こった際に、学校はそれぞれ対応を行っておりますが、それが法に基づくいじめに当たるかどうかの検討を組織的に行い。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"報告書の提言が確保要件とする、いじめ事案を迅速に解決するのに必要なリソース・権限を有する組織になっているのか伺います。組織としていじめ事案に取り組むノウハウを蓄積するということも書いているのですけれども、これができるのか、伺いたいと思います。","respondent":"堀越総務部長","answer":"教育委員会や学校へ助言することや対応を促すことなど、ソーシャルワーカー、それから職員も一丸となって進めてまいりたいと考えています。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"これが現場の実態なのですけれども、これでどうして、対策を取る、今後は大丈夫だと思えるのでしょうか。２冊の報告書を全ての教職員に手渡して読んでもらい、区教育委員会はすべきだと思いますけれども、いかがか尋ねました。","respondent":"米田教育次長","answer":"学校では年３回以上の校内研修会実施を義務づけておりまして、併せて２つの調査報告書の活用も求めております。自校で同種のいじめが起こった際にどのように組織的な対応をするのか、教員間で議論する場は大変重要だと考えております。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、実際に議論をしてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"これも間違いないでしょうか。それと、西大井の近辺の新しい開発の状況というのは、どういうふうになっているか尋ねました。","respondent":"中村都市環境部長、有江都市整備推進担当部長","answer":"最大で３,０００人増で、約４,０００人の社員が勤務予定ということで、計画変更するということも聞いておりません。こちらも計画どおり整備される予定となっておりまして、三方の道路に面しまして… まちの課題や将来のまちづくりの方向性などについて、地権者の方々でご検討されております。土地の利用状況や交通量などの基礎調査を今年度、実施しておりまして、まちの状況把握に努めております。","id":"exchange-077"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺はどうでしょうか。なので、ぜひ７時半から８時半はスクールゾーンにしていただきたいのですけれども、この辺についてはいかがか尋ねました。","respondent":"中村都市環境部長、溝口防災まちづくり部長、川島地域振興部長","answer":"生活支援機能のさらなる充実、西大井はこれからもさらに発展していくという認識ですので、必要な支援をしていきたいと考えております。… 解決できるように進めていきたいと考えておりますし、この公園の中に設置できればと、併せて基本設計の中で検討を進めているところです。… 生活安全パトロール隊の指導等の対応、それから今、喫煙所を囲うパーティションの設置に向けていろいろと準備をしています。","id":"exchange-078","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問・要望","question":"伊藤博文公のお墓をはじめ、すごく西側は観光においてすばらしい施設があるのですけれども、観光という意味ではいかがでしょうか。私は５年延長して令和１２年まで、東京都の要望を含め、その辺はいかがか尋ねました。","respondent":"米田教育次長、廣田文化スポーツ振興部長、中村都市環境部長","answer":"ご案内のように、それぞれの子どもも通学のときにその看板を見ながら、自分の学校のつながりというものを認識しているものだと考えています。ほかにも… 近年、しろへびサミットというにぎわいイベントが行われておりまして、この９月も大変にぎわったと聞いているところです。… 二葉三・四丁目および西大井六丁目地区としまして、平成２５年度から不燃化特区支援事業を導入して、建物の不燃化促進に努めているところです。","id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"でも、定年の年齢が延びたのだから、これからずっとまだまだできるじゃないですか」と。これについては、しっかり対策をしていかないといけないと思うのですけれども、いかがか尋ねました。","respondent":"堀越総務部長","answer":"そういったもの、それから先ほどご答弁した例外的な扱いなどを含めて、しっかりと丁寧に対応してまいりたいと考えています。国でもいろいろな総務省の検討会で、人材確保に向けた検討がついこの間始まったと新聞報道等にもありましたので、このように思ってあります。","id":"exchange-080"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、脚立がないとという方もいらっしゃいました。確認します。","respondent":"鈴木選挙管理委員会事務局長","answer":"一番大きな番号を最上段に持っていくことで、候補者が減ればその分、上を使わなければならない方も減るというような考え方で変更をかけたものです。それから２点目の、これはご指摘の通りでございまして、そこに上下はないと認識しております。","id":"exchange-081"},{"speaker":"藤原委員","kind":"質問","question":"１回の会議は何時間ですか。この辺については、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"公費負担とできるものについては品川区でも全て対応していますので、そのための違いであって、平等性を欠くものではないと認識しています。１回当たりの時間は大体おおむね、通常のときであれば１時間程度、時間は１時間から２時間程度になるというのが現状です。","id":"exchange-082"},{"speaker":"藤原委員","kind":"質問・要望","question":"どんどん要望していっていただきたいと思うのです。その辺については、いかがか尋ねました。","respondent":"今井福祉部長、阿部健康推進部長","answer":"今、しっかりと区としても事業者をお支えしながら、適切に処遇改善の対応ができるように支えてまいりたいと考えています。いろいろな事業者に実施していただいている事業もありますので、区民の皆様のお力を借りながら… 実施日数を増やすことにつきましては、急に実施日を増やすということについてはなかなか困難であると考えておりますけれども、実は新型コロナ禍で。","id":"exchange-083"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、一生懸命、企画部でやってくださっているのですから。それも伺いたいので、まず３点、お伺いします。","respondent":"新井副区長","answer":"であるからこそ、言うまでもなく、区政の立場で、区民の立場で、きちんと向き合っていきたいと考えているところです。それは、財政調整に限らず、あらゆる施策に対して、そうしていきたいと思っているところです。","id":"exchange-084"},{"speaker":"藤原委員","kind":"質問・要望","question":"東京都の企画というか中心にいた方ですから、いろいろなやり方が分かると思うのです。だから、その辺をぜひ品川区のために使っていただきたいと思うのですけれども、その２点だけもう一回、答弁いただけますか。","respondent":"新井副区長","answer":"そちらが大事だと考えていますので、品川区の人間として、しっかり汗をかいていきたいと考えているところです。決意表明で失礼いたしました。","id":"exchange-085"},{"speaker":"藤原委員","kind":"質問","question":"担当部長、いつまでに２０億円にするのですか。そして、限りなく２０億円に近づけますという答弁を頂きたいと思っているのですけれども、いかがか尋ねました。","respondent":"久保田企画部長","answer":"令和４年度の事務事業の評価を行ってありますので、今年度中にはきちんと評価を行いまして、区民にも公開していきたいと考えています。１％、２０億円、新たに品川区がこれから取り組む事業に積極的に活用していきたいと考えているところです。","id":"exchange-086"},{"speaker":"藤原委員","kind":"質問・要望","question":"区長、事務事業評価は、最後の英断は区長だと私は思っております。ぜひ目標を達成するために英断を下していってほしいと求めましたが、最後にその辺の答弁を頂けますか。","respondent":"森澤区長","answer":"品川区では１０年ぶりということで、やはり客観的ないろいろな指標を持って、そして自分たちで振り返ることで自律的に見直しをしていく。しっかりと、１％、２０億円ということを実現すべく、区の職員、皆さんと共に一緒に取り組んでいきたいと考えています。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問・要望","question":"教育委員会として真実ではないと考える点、または評価が不当であると考える点があるのか伺います。先ほど教育委員会からの答弁もありましたが、区長部局として、この点、なぜこういう対応になってしまったのか、伺いたいと思います。","respondent":"米田教育次長、堀越総務部長","answer":"調査委員会による報告書は、当時、教育委員会事務局で対応した職員もヒアリングを受け、それに基づき作成されたものです。内容や評価について、教育委員会として… どのような事態がいじめ重大事態に該当するのか、それからどのように判断するのかという点の理解および仕組みが不足していたものと認識しております。","id":"exchange-088"},{"speaker":"松本委員","kind":"質問・要望","question":"なぜ教育委員会が諮問した品川区いじめ対策委員会では、教育委員会事務局担当者へのヒアリングが行われなかったのでしょうか、伺います。諮問文を工夫し、教育委員会事務局担当者へのヒアリングを必須としてほしいと求めましたが、いかがか尋ねました。","respondent":"米田教育次長","answer":"それから学校教育委員会の対応についての検証、また同種の事態の再発防止のために学校教育委員会が取るべき措置の３点を諮問いたしました。","id":"exchange-089"},{"speaker":"松本委員","kind":"質問","question":"この両者の事務局体制の違いが、対策委員会答申と調査委員会答申の内容に差をもたらしたのではないかと考えますが、教育委員会の見解を伺います。同じ係だった場合は、双方の担当職員が同じだったのか、違ったのか、伺います。","respondent":"米田教育次長","answer":"５項目について諮問を受け、調査を行ったものと認識しておりまして、対策委員会等へのご指摘も頂いたものと受け止めてあります。職員は複数で対応しており、同じ担当者も含まれているものです。","id":"exchange-090"},{"speaker":"松本委員","kind":"提案","question":"提案させてほしいと求めましたが、品川区いじめ対策委員会規則を改正し、見解を伺います。行っていないとするならば、今後は推薦依頼を行うべきと考えますが、いかがか尋ねました。","respondent":"米田教育次長","answer":"今後、様々な手法を凝らすことが必要と考えていますので、それも１つの案として検討させていただければと思います。いじめに関する調査委員の選出の相談に乗るような仕組みもつくってありますので、そちらも含めまして、有効に活用してまいりたいと考えています。","id":"exchange-091"},{"speaker":"松本委員","kind":"質問・要望","question":"そこでお伺いしますが、いじめに関する報告は、学校から教育委員会にどのような手段で行われていたのでしょうか。重大事態に当たるかどうかの相談も含めて、証拠が残るような手段によって行われるべきと考えますが、見解を伺います。","respondent":"米田教育次長","answer":"状況によってはその都度、いじめ実態調査報告書の書類にいじめの事実や対応を記録し、教育委員会に提出しております。それらの記録を補完する意味合いも含め、メールの活用も、現在も行っておりますが、引き続き行ってまいりたいと考えています。","id":"exchange-092"},{"speaker":"松本委員","kind":"質問・要望","question":"連絡していただく、相談していただくという体制を要望いたしますが、いかがでしょうか。現時点で明確にご回答いただけないということですと、現状は認定フローが存在しないということになると思いますが、それでよいのかも確認いたします。","respondent":"米田教育次長","answer":"より一層充実を図っていければと考えていますので、今も取り組んでいるものであるということはご認識いただければと思います。いじめの重大事態に至る前までに、教育委員会と学校が連携して、いじめの対応を現在も行っております。","id":"exchange-093"},{"speaker":"松本委員","kind":"質問・要望","question":"これまでの答弁を伺うと、研修は行ったけれども、ではどうやって効果検証をするのかというところは答弁がありません。テストを行うのであれば、これを区議会に公開してほしいと求めましたが、見解を伺います。","respondent":"米田教育次長","answer":"９月６日に実施した全ての教員対象の研修には、教育総合支援センターの管理職、研修を受講しています。今後、また次年度に向けていじめ予防プログラムの実施などの検討も進めてまいりますので、議会の場でもご説明ができればと考えているものです。","id":"exchange-094"},{"speaker":"松本委員","kind":"質問・要望","question":"テストのような形で、こういう事案の場合はどうですかというふうに検証してほしいと求めましたが、いかがでしょうか。まだ恐らく全部の学校に設置できていないと思いますが、これは来年度の予算でしっかり予算要望を出してほしいと求めましたが、いかがか尋ねました。","respondent":"米田教育次長、堀越総務部長","answer":"それから、区立学校の屋内には、３１校に８６台の防犯カメラを設置しており、その多くは昇降口、廊下等についていると認識しております。いじめに関していえば、個々の事案等を勘案しまして… 今回、補正予算でご審議いただいていますように、１月からいじめ問題に対応する部署を区長部局に設置し、対応に当たってまいります。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"令和５年度の品川区予算事務事業に反映され、要望、政策提言をいたしました。以上、品川区議会自民党・無所属の会の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"若林委員","kind":"質問・要望","question":"会派の要望も含め、また３歳児視力検査フォトスクリーナー、行政手続オンライン化などの施策が着実に実施されました。本決算特別委員会を通じ、会派からの意見・要望を真摯に受け止められ、今後の区政運営および来年度予算に反映されるよう求め、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"松永副委員長","kind":"提案","question":"執行率が９３.１％となり、普通会計の実質収支も約６２億円を超える黒字となっており、健全財政を維持していることを確認しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"鈴木委員","kind":"質問・要望","question":"インフルエンザワクチンは、２３区でも多くの区が行い、近隣区が全て行っている、高齢者の接種費用の無料化を行うよう求めます。学校図書館司書は直接雇用とし、週５日の配置を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"須貝委員","kind":"提案","question":"先ほど藤原委員が提案した選挙管理委員の給与は、他の自治体のように日当３万円の出会手当にするべきです。以上、品川改革連合の意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"せらく委員","kind":"提案","question":"いじめの未然防止・早期発見が求められますが、起きてしまった事案に対しては、学校は毅然とした態度を取るべきです。今回の決算特別委員会において、次年度の予算や今後の施策・事業に反映していただくよう要望するとともに、区民サービスの向上が図られることを求めとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1544#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":111297,"voices":245}},{"id":"r05-20231023-10","meetingId":"r05-cm10","date":"2023年10月23日","dateIso":"2023-10-23","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10457,"voices":39}}]);
